export enum Severity {
  LOW = "LOW",
  MEDIUM = "MEDIUM",
  HIGH = "HIGH",
  CRITICAL = "CRITICAL"
}

export enum ScanStatus {
  OPEN = "OPEN",
  FIXED = "FIXED",
  IGNORED = "IGNORED",
  IN_PROGRESS = "IN_PROGRESS"
}

export interface Vulnerability {
  id: string;
  ruleId: string;
  title: string;
  description: string;
  severity: Severity;
  status: ScanStatus;
  resource: string;
  line?: number;
  remediation?: string;
}

export interface ComplianceControl {
  id: string;
  framework: 'SOC2' | 'ISO27001' | 'HIPAA' | 'PCI-DSS';
  title: string;
  status: 'PASS' | 'FAIL' | 'WARNING';
  score: number;
}

export interface GraphNode {
  id: string;
  label: string;
  type: 'compute' | 'storage' | 'network' | 'security';
  status: 'healthy' | 'risk';
}

export interface GraphLink {
  source: string;
  target: string;
}

export type View = 'dashboard' | 'scanner' | 'graph' | 'compliance' | 'settings';

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || ''; 
const ai = new GoogleGenAI({ apiKey });

export const analyzeTerraformCode = async (code: string) => {
  if (!apiKey) {
    console.warn("Gemini API Key is missing. Skipping AI analysis.");
    return null;
  }

  try {
    const model = 'gemini-2.5-flash';
    const prompt = `
      You are a CloudGuardian AI Security Agent. Analyze the following Terraform HCL code for security vulnerabilities, 
      specifically looking for misconfigurations related to SOC2, ISO27001, and general best practices (AWS/Azure/GCP).

      Code:
      \`\`\`hcl
      ${code}
      \`\`\`

      Return a JSON response with the following structure:
      {
        "findings": [
          {
            "ruleId": "string",
            "title": "string",
            "severity": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
            "resource": "string",
            "description": "string",
            "remediation": "string"
          }
        ]
      }

      Only return the JSON object.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json"
      }
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    return null;
  }
};

export const suggestFix = async (vulnerability: string, codeContext: string) => {
  if (!apiKey) return "AI Fix unavailable (No API Key)";

  try {
    const model = 'gemini-2.5-flash';
    const prompt = `
      Provide a Terraform HCL code snippet to fix the following vulnerability: "${vulnerability}".
      Context: 
      \`\`\`hcl
      ${codeContext}
      \`\`\`
      Return only the corrected HCL code block.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Fix Failed:", error);
    return "Failed to generate fix.";
  }
};

