import React, { useState } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, CheckCircle, XCircle, ChevronDown, ChevronUp, Cpu } from 'lucide-react';
import { suggestFix } from '../services/geminiService';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);

  const getSeverityColor = (severity: Severity) => {
    switch (severity) {
      case Severity.CRITICAL: return 'text-red-500 bg-red-500/10 border-red-500/20';
      case Severity.HIGH: return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case Severity.MEDIUM: return 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20';
      case Severity.LOW: return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      default: return 'text-slate-500 bg-slate-500/10 border-slate-500/20';
    }
  };

  const handleGenerateFix = async (vuln: Vulnerability) => {
    if (aiFix[vuln.id]) return;
    setLoadingFix(vuln.id);
    const fix = await suggestFix(vuln.title, codeContext);
    setAiFix(prev => ({ ...prev, [vuln.id]: fix || "Could not generate fix." }));
    setLoadingFix(null);
  };

  if (findings.length === 0) {
    return (
      <div className="text-center py-12 bg-slate-800/50 rounded-lg border border-slate-700 border-dashed">
        <CheckCircle className="mx-auto text-green-500 mb-4" size={48} />
        <h3 className="text-lg font-medium text-white">No Issues Found</h3>
        <p className="text-slate-400 mt-2">Your infrastructure code looks secure.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {findings.map((finding) => (
        <div 
          key={finding.id} 
          className="bg-slate-800 rounded-lg border border-slate-700 overflow-hidden transition-all hover:border-slate-600"
        >
          <div 
            className="p-4 flex items-center justify-between cursor-pointer"
            onClick={() => setExpandedId(expandedId === finding.id ? null : finding.id)}
          >
            <div className="flex items-center gap-4">
              <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getSeverityColor(finding.severity)}`}>
                {finding.severity}
              </span>
              <div>
                <h4 className="font-medium text-white">{finding.title}</h4>
                <div className="text-xs text-slate-400 mt-1 flex items-center gap-2">
                  <span>{finding.resource}</span>
                  <span className="w-1 h-1 rounded-full bg-slate-600"></span>
                  <span>{finding.ruleId}</span>
                </div>
              </div>
            </div>
            {expandedId === finding.id ? <ChevronUp size={20} className="text-slate-500" /> : <ChevronDown size={20} className="text-slate-500" />}
          </div>

          {expandedId === finding.id && (
            <div className="px-4 pb-4 border-t border-slate-700/50 pt-4 bg-slate-800/50">
              <p className="text-slate-300 text-sm mb-4">{finding.description}</p>

              <div className="flex gap-3">
                <button 
                  onClick={(e) => { e.stopPropagation(); handleGenerateFix(finding); }}
                  disabled={loadingFix === finding.id}
                  className="flex items-center gap-2 px-3 py-2 bg-purple-600 hover:bg-purple-700 text-white text-xs font-medium rounded-md transition-colors disabled:opacity-50"
                >
                  <Cpu size={14} />
                  {loadingFix === finding.id ? 'Generating Fix...' : 'Generate AI Fix'}
                </button>
              </div>

              {aiFix[finding.id] && (
                <div className="mt-4 p-3 bg-slate-900 rounded-md border border-purple-500/30">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-xs text-purple-400 font-bold uppercase tracking-wider">CloudGuardian AI Suggestion</span>
                  </div>
                  <pre className="text-xs text-slate-300 font-mono overflow-x-auto whitespace-pre-wrap">
                    {aiFix[finding.id]}
                  </pre>
                </div>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

import React, { useState } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, Code2 } from 'lucide-react';

export const Scanner: React.FC = () => {
  const [code, setCode] = useState(`resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}`);

  const [scanning, setScanning] = useState(false);
  const [results, setResults] = useState<Vulnerability[] | null>(null);

  const performScan = async () => {
    setScanning(true);
    setResults(null);

    // 1. Static Regex Check (Client-side simulation of SecretScannerService)
    const localFindings: Vulnerability[] = [];

    // Simple mock logic for demo
    if (code.includes('0.0.0.0/0') && code.includes('ingress')) {
      localFindings.push({
        id: `vuln-${Date.now()}-1`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group allows open access',
        description: 'The security group allows ingress from 0.0.0.0/0, which exposes the resource to the entire internet.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web'
      });
    }

    if (code.includes('public-read') && code.includes('aws_s3_bucket')) {
      localFindings.push({
        id: `vuln-${Date.now()}-2`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket has public access',
        description: 'The S3 bucket ACL is set to public-read, allowing anyone to list or read object data.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data'
      });
    }

    // 2. Gemini AI Analysis (if available)
    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        try {
            // Clean markdown code blocks if Gemini returns them
            const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
            const parsed = JSON.parse(cleanJson);
            if (parsed.findings && Array.isArray(parsed.findings)) {
                // Merge AI findings
                const aiFindings = parsed.findings.map((f: any, idx: number) => ({
                    id: `ai-vuln-${Date.now()}-${idx}`,
                    ruleId: f.ruleId || 'AI_DETECTED',
                    title: f.title,
                    description: f.description,
                    severity: f.severity || Severity.MEDIUM,
                    status: ScanStatus.OPEN,
                    resource: f.resource || 'unknown'
                }));
                localFindings.push(...aiFindings);
            }
        } catch (e) {
            console.error("Failed to parse AI response", e);
        }
      }
    } catch (err) {
      console.error("AI Scan error", err);
    }

    setResults(localFindings);
    setScanning(false);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-white mb-2">Secret & Infrastructure Scanner</h2>
        <p className="text-slate-400">
          Paste your Terraform (HCL) code below to scan for secrets, misconfigurations, and compliance violations. 
          Powered by CloudGuardian Regex Engine and Gemini AI.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[calc(100vh-250px)]">
        <div className="flex flex-col h-full bg-slate-900 rounded-lg border border-slate-700 overflow-hidden">
          <div className="bg-slate-800 p-3 flex items-center justify-between border-b border-slate-700">
            <div className="flex items-center gap-2 text-slate-300">
              <Code2 size={16} />
              <span className="text-sm font-mono">main.tf</span>
            </div>
            <button
              onClick={performScan}
              disabled={scanning}
              className="flex items-center gap-2 bg-primary-600 hover:bg-primary-700 text-white px-4 py-1.5 rounded-md text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} />}
              {scanning ? 'Scanning...' : 'Run Scan'}
            </button>
          </div>
          <textarea
            className="flex-1 w-full bg-[#0d1117] text-slate-300 font-mono text-sm p-4 resize-none focus:outline-none"
            value={code}
            onChange={(e) => setCode(e.target.value)}
            spellCheck={false}
          />
        </div>

        <div className="flex flex-col h-full overflow-y-auto">
          <div className="bg-slate-800/50 rounded-lg p-1 min-h-full">
            {results ? (
              <ScanResults findings={results} codeContext={code} />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-500">
                <ShieldIconPlaceholder />
                <p className="mt-4 font-medium">Ready to Scan</p>
                <p className="text-sm">Click "Run Scan" to analyze your infrastructure.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

