const Node = ({ x, y, label, type, status }: any) => {
    let fill = "#3b82f6"; // Network
    if (type === 'compute') fill = "#a855f7";
    if (type === 'storage') fill = "#eab308";
    if (type === 'security') fill = "#22c55e";

    const stroke = status === 'risk' ? '#ef4444' : fill;
    const strokeWidth = status === 'risk' ? 3 : 0;
    const glow = status === 'risk' ? 'filter drop-shadow(0 0 8px rgba(239, 68, 68, 0.5))' : '';

    return (
        <g style={{ cursor: 'pointer' }} className="transition-transform hover:scale-105">
            <circle cx={x} cy={y} r="25" fill={fill} stroke={stroke} strokeWidth={strokeWidth} style={{ filter: glow }} />
            <text x={x} y={y + 40} textAnchor="middle" fill="#cbd5e1" fontSize="12" fontWeight="500">{label}</text>
            <text x={x} y={y + 4} textAnchor="middle" fill="white" fontSize="10" fontWeight="bold">{type[0].toUpperCase()}</text>
        </g>
    );
};

