/**
 * SecretScannerService Simulation
 * Implements Regex Patterns + Shannon Entropy
 */

const calculateShannonEntropy = (str: string): number => {
  if (!str) return 0;
  const len = str.length;
  const frequencies = new Map<string, number>();
  for (const char of str) {
    frequencies.set(char, (frequencies.get(char) || 0) + 1);
  }

  let entropy = 0;
  for (const count of frequencies.values()) {
    const p = count / len;
    entropy -= p * Math.log2(p);
  }
  return entropy;
};

export const scanForSecrets = (content: string): Vulnerability[] => {
    const findings: Vulnerability[] = [];
    const lines = content.split('\n');

    const patterns = [
        { name: 'AWS Access Key', regex: /AKIA[0-9A-Z]{16}/, id: 'AWS_ACCESS_KEY' },
        { name: 'AWS Secret Key', regex: /(aws_secret_access_key|secret_key)\s*=\s*["']([a-zA-Z0-9/+]{40})["']/, id: 'AWS_SECRET_KEY' },
        { name: 'Private Key', regex: /-----BEGIN PRIVATE KEY-----/, id: 'PRIVATE_KEY' },
        { name: 'Generic Token', regex: /(api_key|access_token|secret)[\s=:"']+([a-zA-Z0-9-_]{20,})/i, id: 'GENERIC_TOKEN' }
    ];

    lines.forEach((line, index) => {
        // 1. Regex Pattern Matching
        patterns.forEach(p => {
            const match = line.match(p.regex);
            if (match) {
                 findings.push({
                    id: `secret-${index}-${p.id}`,
                    ruleId: p.id,
                    title: `Potential ${p.name} found`,
                    description: `A pattern matching ${p.name} was detected in line ${index + 1}.`,
                    severity: Severity.CRITICAL,
                    status: ScanStatus.OPEN,
                    resource: 'code_scan',
                    line: index + 1,
                    remediation: 'Remove the hardcoded secret and use a secrets manager (e.g., AWS Secrets Manager, HashiCorp Vault).'
                 });
            }
        });

        // 2. Shannon Entropy Analysis
        // Split by common delimiters to find tokens
        const tokens = line.split(/[\s"'{}=,]+/);
        tokens.forEach(token => {
            // Filter out common false positives (short strings, variable names, URLs)
            if (token.length > 16 && !token.includes('/') && !token.includes('\\') && !token.startsWith('arn:')) {
                const entropy = calculateShannonEntropy(token);
                // Threshold from architecture: > 4.5
                if (entropy > 4.5) {
                    // Avoid duplicating if regex already caught it
                    if (!findings.some(f => f.line === index + 1 && f.ruleId.includes('KEY') && line.includes(token))) {
                         findings.push({
                            id: `entropy-${index}`,
                            ruleId: 'HIGH_ENTROPY_STRING',
                            title: 'High Entropy String Detected',
                            description: `String with entropy ${entropy.toFixed(2)} detected. This often indicates a secret or key.`,
                            severity: Severity.HIGH,
                            status: ScanStatus.OPEN,
                            resource: 'code_scan',
                            line: index + 1,
                            remediation: 'Verify if this string is a secret. If so, move it to a secrets manager.'
                         });
                    }
                }
            }
        });
    });

    return findings;
};

