export const VULNERABILITY_TO_CONTROLS: Record<string, string[]> = {
    'S3_NO_ENCRYPTION': ['SOC2_CC6.1', 'ISO27001_A.10.1.1', 'HIPAA_164.312', 'PCI_DSS_3.4'],
    'S3_PUBLIC_ACCESS': ['SOC2_CC6.1', 'ISO27001_A.9.1.2', 'HIPAA_164.312'],
    'SECURITY_GROUP_OPEN': ['SOC2_CC6.6', 'ISO27001_A.13.1.1', 'HIPAA_164.312'],
    'AWS_ACCESS_KEY': ['SOC2_CC6.1', 'ISO27001_A.9.1.2', 'PCI_DSS_3.4'],
    'HIGH_ENTROPY_STRING': ['SOC2_CC6.1', 'ISO27001_A.9.1.2']
};

export const getComplianceReport = (findings: Vulnerability[]): ComplianceControl[] => {
    // Start with all controls passing
    const report: Record<string, ComplianceControl> = {};

    // Initialize
    Object.values(CONTROL_REGISTRY).forEach(ctrl => {
        report[ctrl.id] = { ...ctrl, status: 'PASS', score: 100 };
    });

    // Map failures
    findings.forEach(vuln => {
        const controls = VULNERABILITY_TO_CONTROLS[vuln.ruleId] || [];
        controls.forEach(controlId => {
            if (report[controlId]) {
                report[controlId].status = 'FAIL';
                report[controlId].score = 0;
            }
        });
    });

    return Object.values(report);
};

