export const VULNERABILITY_TO_CONTROLS: Record<string, string[]> = {
    'S3_NO_ENCRYPTION': ['SOC2_CC6.1', 'ISO27001_A.10.1.1', 'HIPAA_164.312', 'PCI_DSS_3.4'],
    'S3_PUBLIC_ACCESS': ['SOC2_CC6.1', 'ISO27001_A.9.1.2', 'HIPAA_164.312'],
