    'HIGH_ENTROPY_STRING': ['SOC2_CC6.1', 'ISO27001_A.9.1.2']
};

export const getComplianceReport = (findings: Vulnerability[]): ComplianceControl[] => {
    // Start with all controls passing
    const report: Record<string, ComplianceControl> = {};

    // Initialize
    Object.values(CONTROL_REGISTRY).forEach(ctrl => {
        report[ctrl.id] = { ...ctrl, status: 'PASS', score: 100 };
    });

    // Map failures
    findings.forEach(vuln => {
        const controls = VULNERABILITY_TO_CONTROLS[vuln.ruleId] || [];
        controls.forEach(controlId => {
            if (report[controlId]) {
                report[controlId].status = 'FAIL';
                report[controlId].score = 0;
            }
        });
    });

    return Object.values(report);
};

/**
 * InfrastructureGraphService Simulation
 * Parses HCL2 to ReactFlow compatible graph structure
 */
export const parseHclToGraph = (hcl: string): { nodes: GraphNode[]; edges: GraphEdge[] } => {
    const nodes: GraphNode[] = [];
    const edges: GraphEdge[] = [];

    // Regex to find resources: resource "type" "name"
    const resourceRegex = /resource\s+"([\w_]+)"\s+"([\w_-]+)"/g;

    let match;
    const resources = new Set<string>();

    // Layout state
    let x = 100;
    let y = 100;

    // 1. Extract Nodes
    while ((match = resourceRegex.exec(hcl)) !== null) {
      const [_, type, name] = match;
      const id = `${type}.${name}`;
      resources.add(id);

      let category: GraphNode['data']['category'] = 'compute';
      if (type.includes('s3') || type.includes('db') || type.includes('storage')) category = 'storage';
      else if (type.includes('vpc') || type.includes('subnet') || type.includes('route')) category = 'network';
      else if (type.includes('security') || type.includes('iam') || type.includes('acl')) category = 'security';

      // Check risks (Simple mocks based on strings present in the code block would be better, but we check global for now)
      let status: 'healthy' | 'risk' = 'healthy';
      if (type === 'aws_s3_bucket' && hcl.includes('public-read')) status = 'risk';
      if (type === 'aws_security_group' && hcl.includes('0.0.0.0/0')) status = 'risk';

      nodes.push({
        id,
        data: {
          label: name,
          category,
          resource_type: type
        },
        position: { x, y },
        status
      });

      // Simple layout increment
      x += 200;
      if (x > 700) {
        x = 100;
        y += 150;
      }
    }

    // 2. Extract Edges (Approximation)
    // We split by "resource" keyword to approximate blocks.
    // This is fragile but works for the demo code provided.
    const blocks = hcl.split(/resource\s+"/);

    blocks.forEach(block => {
        if (!block.trim()) return;

        // Recover the header: type" "name" { ...
        const headerMatch = /^([\w_]+)"\s+"([\w_-]+)"/.exec(block);
        if (!headerMatch) return;

        const [_, type, name] = headerMatch;
        const sourceId = `${type}.${name}`;

        // Find references to other resources
        resources.forEach(targetId => {
            if (targetId === sourceId) return;
            // e.g., aws_security_group.web.id
            if (block.includes(targetId)) {
                edges.push({
                    id: `${sourceId}->${targetId}`,
                    source: sourceId,
                    target: targetId
                });
            }
        });
    });

    return { nodes, edges };
  };

