    }

    if (code.includes('aws_s3_bucket') && !code.includes('server_side_encryption_configuration')) {
       localFindings.push({
        id: `infra-${Date.now()}-3`,
        ruleId: 'S3_NO_ENCRYPTION',
        title: 'S3 Bucket Encryption Missing',
        description: 'The S3 bucket does not have server-side encryption enabled.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        remediation: 'Add server_side_encryption_configuration block.'
      });
    }

    // 3. Gemini AI Analysis (if available)
    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        try {
            const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
            const parsed = JSON.parse(cleanJson);
            if (parsed.findings && Array.isArray(parsed.findings)) {
