import { Login } from './pages/Login';
import { View } from './types';

const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);

  // Simular persistência de login
  useEffect(() => {
    const auth = localStorage.getItem('cg_auth');
    if (auth === 'true') setIsAuthenticated(true);
  }, []);

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard />;
      case 'scanner': return <Scanner code={terraformCode} onCodeChange={setTerraformCode} />;
      case 'drift': return <Drift />;
      case 'graph': return <Graph code={terraformCode} />;
      case 'compliance': return <Compliance />;
      case 'settings': return <Settings />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-primary-500/30">
      <Sidebar 
        currentView={currentView} 
        onNavigate={setCurrentView} 
        onLogout={handleLogout}
      />
      <main className="flex-1 ml-64 min-h-screen relative">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-indigo-600 to-purple-600"></div>
        <div className="p-6">
            {renderContent()}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, CheckCircle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2 } from 'lucide-react';
import { suggestFix } from '../services/geminiService';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committing, setCommitting] = useState<string | null>(null);

  const getSeverityColor = (severity: Severity) => {
    switch (severity) {
      case Severity.CRITICAL: return 'text-red-500 bg-red-500/10 border-red-500/20';
      case Severity.HIGH: return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case Severity.MEDIUM: return 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20';
      case Severity.LOW: return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      default: return 'text-slate-500 bg-slate-500/10 border-slate-500/20';
    }
  };

  const handleGenerateFix = async (vuln: Vulnerability) => {
    if (aiFix[vuln.id]) return;
    setLoadingFix(vuln.id);
    const fix = await suggestFix(vuln.title, codeContext);
    setAiFix(prev => ({ ...prev, [vuln.id]: fix || "Could not generate fix." }));
    setLoadingFix(null);
  };

  const handleCreatePR = (vulnId: string) => {
    setCommitting(vulnId);
    // Simula PyGithub GitService call
    setTimeout(() => {
        alert("GitHub Pull Request created successfully! Branch: fix/security-patch-" + Date.now());
        setCommitting(null);
    }, 2000);
  };

  if (findings.length === 0) {
    return (
      <div className="text-center py-12 bg-slate-900 border border-slate-800 border-dashed rounded-xl">
        <CheckCircle className="mx-auto text-green-500 mb-4" size={48} />
        <h3 className="text-lg font-bold text-white">Infrastructure Secure</h3>
        <p className="text-slate-500 text-sm mt-1">No vulnerabilities or secrets detected in current HCL context.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {findings.map((finding) => (
        <div 
          key={finding.id} 
          className={`bg-slate-900 rounded-xl border transition-all duration-300 ${
            expandedId === finding.id ? 'border-primary-500/50 ring-1 ring-primary-500/20 shadow-xl' : 'border-slate-800'
          }`}
        >
          <div 
            className="p-4 flex items-center justify-between cursor-pointer"
            onClick={() => setExpandedId(expandedId === finding.id ? null : finding.id)}
          >
            <div className="flex items-center gap-4">
              <span className={`px-2.5 py-0.5 rounded text-[10px] font-bold border ${getSeverityColor(finding.severity)}`}>
                {finding.severity}
              </span>
              <div>
                <h4 className="font-semibold text-sm text-white">{finding.title}</h4>
                <div className="text-[10px] text-slate-500 mt-1 flex items-center gap-2">
                  <span className="font-mono">{finding.resource}</span>
                  <span className="w-1 h-1 rounded-full bg-slate-700"></span>
                  <span>{finding.ruleId}</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3">
                 {expandedId === finding.id ? <ChevronUp size={16} className="text-slate-500" /> : <ChevronDown size={16} className="text-slate-500" />}
            </div>
          </div>

          {expandedId === finding.id && (
            <div className="px-4 pb-5 border-t border-slate-800 pt-4 animate-in fade-in slide-in-from-top-2">
              <div className="p-3 bg-slate-950/50 rounded-lg border border-slate-800 mb-5">
                <p className="text-slate-400 text-xs leading-relaxed">{finding.description}</p>
              </div>

              <div className="flex gap-3">
                <button 
                  onClick={() => handleGenerateFix(finding)}
                  disabled={loadingFix === finding.id}
                  className="flex items-center gap-2 px-4 py-2 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-bold rounded-lg transition-all disabled:opacity-50"
                >
                  {loadingFix === finding.id ? <Loader2 className="animate-spin" size={14} /> : <Cpu size={14} />}
                  {loadingFix === finding.id ? 'Analyzing...' : 'Generate AI Fix'}
                </button>
              </div>

              {aiFix[finding.id] && (
                <div className="mt-5 space-y-3">
                  <div className="bg-slate-950 rounded-xl border border-indigo-500/30 overflow-hidden">
                    <div className="bg-indigo-600/10 px-4 py-2 border-b border-indigo-500/20 flex justify-between items-center">
                        <span className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Remediation Strategy</span>
                        <span className="text-[9px] text-slate-500">FixerEngine v1.2</span>
                    </div>
                    <div className="p-4">
                        <pre className="text-[11px] text-slate-300 font-mono overflow-x-auto">
                          {aiFix[finding.id].replace(/```hcl\n?|\n?```/g, '')}
                        </pre>
                    </div>
                  </div>
                  <button 
                    onClick={() => handleCreatePR(finding.id)}
                    disabled={committing === finding.id}
                    className="w-full flex items-center justify-center gap-2 py-2 bg-green-600 hover:bg-green-700 text-white text-[11px] font-bold rounded-lg transition-all disabled:opacity-50"
                  >
                    {committing === finding.id ? <Loader2 className="animate-spin" size={14} /> : <GitPullRequest size={14} />}
                    {committing === finding.id ? 'Creating PR...' : 'Commit Fix to GitHub'}
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

