  const [currentAction, setCurrentAction] = useState('');

  const isBusinessFeature = format === 'json' || format === 'csv' || period === 'all';

  const handleGenerate = () => {
    if (isBusinessFeature) return;

    setStep('generating');
    setProgress(0);
  };

  useEffect(() => {
    if (step === 'generating') {
      const actions = [
        'Fetching timeline events...',
        'Analyzing risk patterns...',
        'Mapping SOC2/ISO27001 controls...',
        'Generating executive summary...',
        'Finalizing PDF document...',
        'Applying cryptographic signature...'
      ];

      let currentActionIdx = 0;
      const interval = setInterval(() => {
        setProgress(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            setTimeout(() => setStep('success'), 500);
            return 100;
          }

          const newProgress = prev + (Math.random() * 15);
          const actionIdx = Math.floor((newProgress / 100) * actions.length);
          if (actionIdx < actions.length) {
            setCurrentAction(actions[actionIdx]);
          }

          return Math.min(newProgress, 100);
        });
      }, 600);

      return () => clearInterval(interval);
    }
