const getIcon = (type: TimelineEvent['type']) => {
    switch (type) {
        case 'SCAN': return <Search size={20} />;
        case 'RISK': return <AlertTriangle size={20} />;
        case 'PR': return <GitPullRequest size={20} />;
        case 'COMPLIANCE': return <CheckCircle size={20} />;
        case 'DRIFT': return <Activity size={20} />;
        default: return <Shield size={20} />;
    }
};

const getIconBg = (type: TimelineEvent['type'], severity?: Severity) => {
    if (severity === Severity.CRITICAL) return 'bg-red-500/10 border-red-500/30 text-red-500';
    if (severity === Severity.HIGH) return 'bg-orange-500/10 border-orange-500/30 text-orange-500';

    switch (type) {
        case 'SCAN': return 'bg-slate-800 border-slate-700 text-slate-300';
        case 'PR': return 'bg-primary-500/10 border-primary-500/30 text-primary-500';
        case 'COMPLIANCE': return 'bg-emerald-500/10 border-emerald-500/30 text-emerald-500';
        case 'DRIFT': return 'bg-indigo-500/10 border-indigo-500/30 text-indigo-400';
        default: return 'bg-slate-800 border-slate-700 text-slate-300';
    }
};

const getSeverityStyles = (severity: Severity) => {
    switch (severity) {
        case Severity.CRITICAL: return 'bg-red-600 text-white';
        case Severity.HIGH: return 'bg-orange-500 text-white';
        case Severity.MEDIUM: return 'bg-yellow-500 text-black';
        case Severity.LOW: return 'bg-blue-500 text-white';
        default: return 'bg-slate-700 text-slate-200';
    }
};

