export const Drift: React.FC<DriftProps> = ({ isAuditorMode = false }) => {
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [scanning, setScanning] = useState(false);

  const runDriftCheck = async () => {
    setScanning(true);
    const results = await checkInfrastructureDrift();
    setTimeout(() => {
        setDrifts(results);
        setScanning(false);
    }, 1500);
  };

  useEffect(() => {
    runDriftCheck();
  }, []);

  const getSeverityBadge = (s: Severity) => {
    const colors = {
        [Severity.CRITICAL]: 'bg-red-500/10 text-red-500 border-red-500/20',
