import React, { useEffect, useState } from 'react';
import { Activity, RefreshCw, AlertCircle, ArrowRight, ShieldCheck, Loader2, Lock, CheckCircle } from 'lucide-react';
import { checkInfrastructureDrift } from '../services/engine';
import { DriftItem, Severity } from '../types';

interface DriftProps {
  isAuditorMode?: boolean;
}

export const Drift: React.FC<DriftProps> = ({ isAuditorMode = false }) => {
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [scanning, setScanning] = useState(false);
  const [syncingId, setSyncingId] = useState<string | null>(null);

  const runDriftCheck = async () => {
    setScanning(true);
    const results = await checkInfrastructureDrift();
    setTimeout(() => {
        setDrifts(results);
        setScanning(false);
    }, 1500);
  };

  useEffect(() => {
    runDriftCheck();
  }, []);

  const handleSync = (id: string) => {
    if (isAuditorMode) return;
    setSyncingId(id);
    setTimeout(() => {
      setDrifts(prev => prev.filter(d => d.id !== id));
      setSyncingId(null);
    }, 2000);
  };

  const handleIgnore = (id: string) => {
    setDrifts(prev => prev.filter(d => d.id !== id));
  };

  const getSeverityBadge = (s: Severity) => {
    const colors = {
        [Severity.CRITICAL]: 'bg-red-500/10 text-red-500 border-red-500/20',
        [Severity.HIGH]: 'bg-orange-500/10 text-orange-500 border-orange-500/20',
        [Severity.MEDIUM]: 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20',
        [Severity.LOW]: 'bg-blue-500/10 text-blue-500 border-blue-500/20',
    };
    return <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${colors[s]}`}>{s}</span>;
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold text-white flex items-center gap-3">
            <Activity className="text-primary-500" />
            Infrastructure Drift Detection
          </h2>
          <p className="text-slate-400 mt-1">Comparing live Cloud state vs Terraform desired state (using <code>DriftDetectionService</code>).</p>
        </div>
        <button 
          onClick={runDriftCheck}
          disabled={scanning}
          className="bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 border border-slate-700 transition-all disabled:opacity-50"
        >
          {scanning ? <Loader2 className="animate-spin" size={16} /> : <RefreshCw size={16} />}
          Refresh Drift Analysis
        </button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {drifts.length === 0 && !scanning && (
            <div className="bg-slate-900/50 border border-slate-800 border-dashed p-12 flex flex-col items-center justify-center text-center rounded-3xl animate-in zoom-in-95 duration-500">
                <ShieldCheck className="text-green-500 mb-4" size={48} />
                <h3 className="text-lg font-bold text-white">No Drift Detected</h3>
                <p className="text-slate-500 text-sm mt-1">Infrastructure matches the defined Terraform state perfectly.</p>
                <button onClick={runDriftCheck} className="mt-6 text-primary-500 text-xs font-bold uppercase tracking-widest hover:underline">Recarregar dados de teste</button>
            </div>
        )}

        {drifts.map((item) => (
          <div key={item.id} className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden hover:border-slate-700 transition-all shadow-xl">
            <div className="p-4 bg-slate-800/50 border-b border-slate-800 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <AlertCircle className="text-red-500" size={18} />
                    <span className="font-mono text-sm text-white">{item.resource}</span>
                </div>
                {getSeverityBadge(item.severity)}
            </div>
            <div className="p-5 grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
                <div>
                    <span className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Property</span>
                    <code className="text-blue-400 text-xs">{item.property}</code>
                </div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Terraform (Desired)</span>
                    <div className="bg-slate-950 p-2 rounded text-xs text-slate-400 border border-slate-800 font-mono">
                        {item.terraformValue}
                    </div>
                </div>
                <div className="flex flex-col relative">
                    <ArrowRight className="absolute left-[-20px] top-1/2 -translate-y-1/2 text-slate-700 hidden md:block" />
                    <span className="text-[10px] font-bold text-red-500 uppercase block mb-1">Live Cloud (Reality)</span>
                    <div className="bg-red-500/5 p-2 rounded text-xs text-red-400 border border-red-500/20 font-mono">
                        {item.cloudValue}
                    </div>
                </div>
            </div>
            <div className="px-5 py-3 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
                <button 
                  onClick={() => handleIgnore(item.id)}
                  className="text-xs text-slate-400 hover:text-white px-3 py-1 font-bold uppercase tracking-tighter"
                >
                  Ignore
                </button>
                <button 
                    onClick={() => handleSync(item.id)}
                    disabled={isAuditorMode || syncingId === item.id}
                    className={`text-[10px] font-bold px-4 py-2 rounded-xl uppercase tracking-wider transition-all flex items-center gap-2 shadow-lg ${
                        isAuditorMode 
                        ? 'bg-slate-800 text-slate-500 border border-slate-700 cursor-default opacity-50' 
                        : syncingId === item.id 
                          ? 'bg-emerald-600 text-white' 
                          : 'bg-primary-600 hover:bg-primary-700 text-white shadow-primary-900/20'
                    }`}
                >
                    {isAuditorMode && <Lock size={12} />}
                    {syncingId === item.id ? <Loader2 className="animate-spin" size={12} /> : syncingId === null && !isAuditorMode ? <CheckCircle size={12}/> : null}
                    {isAuditorMode ? 'State Locked' : syncingId === item.id ? 'Synchronizing...' : 'Synchronize State'}
                </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, Code2, AlertTriangle, Sparkles } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange }) => {
  const [scanning, setScanning] = useState(false);
  const [results, setResults] = useState<Vulnerability[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const performScan = async () => {
    setScanning(true);
    setResults(null);
    setError(null);
    const localFindings: Vulnerability[] = [];

    // 1. Run Engine: Secret Scanner (Regex + Entropy)
    const secretFindings = scanForSecrets(code);
    localFindings.push(...secretFindings);

    // 2. Run Engine: Infrastructure Rules
    if (code.includes('0.0.0.0/0') && code.includes('ingress')) {
      localFindings.push({
        id: `infra-${Date.now()}-1`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group allows open access',
        description: 'The security group allows ingress from 0.0.0.0/0, which exposes the resource to the entire internet.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6']
      });
    }

    if (code.includes('public-read') && code.includes('aws_s3_bucket')) {
      localFindings.push({
        id: `infra-${Date.now()}-2`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket has public access',
        description: 'The S3 bucket ACL is set to public-read, allowing anyone to list or read object data.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        complianceMapping: ['SOC2_CC6.1']
      });
    }

    // 3. Gemini AI Analysis
    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        try {
            const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
            const parsed = JSON.parse(cleanJson);
            if (parsed.findings && Array.isArray(parsed.findings)) {
                const aiFindings = parsed.findings.map((f: any, idx: number) => ({
                    id: `ai-vuln-${Date.now()}-${idx}`,
                    ruleId: f.ruleId || 'AI_DETECTED',
                    title: f.title,
                    description: f.description,
                    severity: f.severity || Severity.MEDIUM,
                    status: ScanStatus.OPEN,
                    resource: f.resource || 'unknown',
                    complianceMapping: f.complianceMapping || []
                }));
                localFindings.push(...aiFindings);
            }
        } catch (e) {
            console.warn("Could not parse AI response", e);
        }
      }
    } catch (err) {
      console.error("AI Scan error", err);
    }

    setResults(localFindings);
    setScanning(false);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto animate-in fade-in slide-in-from-top-4 duration-500">
      <div className="mb-8 flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-black text-white mb-2 tracking-tight">Secret & Infra Scanner</h2>
          <p className="text-slate-400 text-sm max-w-xl">
            Insira seu código HCL abaixo. O motor CloudGuardian utiliza análise de entropia e o <strong>Gemini 3 Flash</strong> para detectar riscos de conformidade.
          </p>
        </div>
        <div className="bg-primary-500/5 border border-primary-500/10 px-4 py-2 rounded-xl flex items-center gap-3">
           <Sparkles size={16} className="text-primary-400" />
           <span className="text-[10px] font-black text-primary-400 uppercase tracking-widest">IA Engine v3.2 Active</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[calc(100vh-320px)]">
        <div className="flex flex-col h-full bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden shadow-2xl">
          <div className="bg-slate-800/80 backdrop-blur-md p-4 flex items-center justify-between border-b border-slate-700">
            <div className="flex items-center gap-2 text-slate-300">
              <Code2 size={16} />
              <span className="text-xs font-black uppercase tracking-widest">main.tf</span>
            </div>
            <button
              onClick={performScan}
              disabled={scanning}
              className="flex items-center gap-2 bg-primary-600 hover:bg-primary-700 text-white px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all shadow-lg shadow-primary-900/20 disabled:opacity-50 group"
            >
              {scanning ? <Loader2 className="animate-spin" size={14} /> : <Play size={14} className="group-hover:scale-125 transition-transform" />}
              {scanning ? 'Scanning...' : 'Executar Scan'}
            </button>
          </div>
          <textarea
            className="flex-1 w-full bg-[#0d1117] text-slate-300 font-mono text-sm p-6 resize-none focus:outline-none selection:bg-primary-500/30"
            value={code}
            onChange={(e) => onCodeChange(e.target.value)}
            spellCheck={false}
          />
        </div>

        <div className="flex flex-col h-full overflow-y-auto">
          <div className="bg-slate-800/20 rounded-3xl p-1 min-h-full">
            {results ? (
              <ScanResults findings={results} codeContext={code} />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-500 border-2 border-dashed border-slate-800 rounded-3xl">
                <div className="w-16 h-16 bg-slate-900 rounded-2xl flex items-center justify-center mb-4 border border-slate-800">
