import React, { useState } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, Code2, AlertTriangle, Sparkles, CheckCircle2 } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange }) => {
  const [scanning, setScanning] = useState(false);
  const [results, setResults] = useState<Vulnerability[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const performScan = async () => {
    setScanning(true);
    setResults(null);
    setError(null);

    // Simular latência de rede para experiência mais realista
    await new Promise(resolve => setTimeout(resolve, 800));

    const localFindings: Vulnerability[] = [];

    // 1. Motor Local: Secrets
    const secretFindings = scanForSecrets(code);
    localFindings.push(...secretFindings);

    // 2. Motor Local: Regras Básicas de Infra
    if (code.includes('0.0.0.0/0')) {
      localFindings.push({
        id: `infra-sg-${Date.now()}`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Porta Exposta ao Mundo (0.0.0.0/0)',
        description: 'Um Security Group está permitindo tráfego de qualquer IP, o que viola o controle SOC2 CC6.6.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6', 'ISO27001_A.13']
      });
    }

    // 3. IA Gemini 3 Flash
    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanJson);
        if (parsed.findings) {
          const aiFindings = parsed.findings.map((f: any, idx: number) => ({
            id: `ai-vuln-${Date.now()}-${idx}`,
            ruleId: f.ruleId || 'AI_SEC_RISK',
            title: f.title,
            description: f.description,
            severity: f.severity || Severity.MEDIUM,
            status: ScanStatus.OPEN,
            resource: f.resource || 'Terraform Module',
            complianceMapping: ['AI_ASSISTED_CHECK']
          }));
          localFindings.push(...aiFindings);
        }
      }
    } catch (e) {
      console.warn("AI parsing failed, continuing with local findings only.");
    }

    setResults(localFindings);
    setScanning(false);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500">
      <header className="flex justify-between items-end">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tight">Security Scanner</h2>
          <p className="text-slate-400 text-sm">Análise estática de código (SAST) e detecção de segredos com Gemini AI.</p>
        </div>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-900 border border-slate-800 rounded-2xl">
           <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">IA Engine: Online</span>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 min-h-[500px]">
        <div className="flex flex-col bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
          <div className="bg-slate-800/50 p-4 border-b border-slate-700 flex justify-between items-center">
             <div className="flex items-center gap-2 text-slate-400 font-mono text-xs">
                <Code2 size={14} />
                infrastructure.tf
             </div>
             <button 
                onClick={performScan}
                disabled={scanning}
                className="bg-primary-600 hover:bg-primary-700 text-white px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all disabled:opacity-50 shadow-lg shadow-primary-900/20"
             >
                {scanning ? <Loader2 className="animate-spin" size={14} /> : <Play size={14} />}
                {scanning ? 'Analisando...' : 'Executar Scan'}
             </button>
          </div>
          <textarea 
            value={code}
            onChange={(e) => onCodeChange(e.target.value)}
            spellCheck={false}
            className="flex-1 w-full p-6 bg-slate-950 text-slate-300 font-mono text-sm resize-none focus:outline-none"
            placeholder="Cole seu código Terraform aqui..."
          />
        </div>

        <div className="space-y-4">
           {results ? (
             <ScanResults findings={results} codeContext={code} />
           ) : (
             <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-3xl text-slate-600 p-12 text-center">
                <div className="p-4 bg-slate-900 rounded-2xl mb-4">
                   <AlertTriangle size={48} className="opacity-20" />
                </div>
                <h3 className="text-white font-bold">Nenhum scan ativo</h3>
                <p className="text-sm mt-2 max-w-xs">Clique no botão de execução para identificar vulnerabilidades e segredos expostos.</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, CheckCircle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2, Shield, FileText, Info, Check } from 'lucide-react';
import { suggestFix } from '../services/geminiService';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committedIds, setCommittedIds] = useState<Set<string>>(new Set());
  const [committing, setCommitting] = useState<string | null>(null);

  const getSeverityColor = (severity: Severity) => {
    switch (severity) {
      case Severity.CRITICAL: return 'text-red-500 bg-red-500/10 border-red-500/20';
      case Severity.HIGH: return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case Severity.MEDIUM: return 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20';
      case Severity.LOW: return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      default: return 'text-slate-500 bg-slate-500/10 border-slate-500/20';
    }
  };

  const handleGenerateFix = async (vuln: Vulnerability) => {
    if (aiFix[vuln.id]) return;
    setLoadingFix(vuln.id);
    try {
        const fix = await suggestFix(vuln.title, codeContext);
        setAiFix(prev => ({ ...prev, [vuln.id]: fix || "Código de correção indisponível." }));
    } catch (e) {
        setAiFix(prev => ({ ...prev, [vuln.id]: "Erro ao contatar Gemini AI." }));
    }
    setLoadingFix(null);
  };

  const handleCreatePR = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    // Simular fluxo de PR no GitHub
    setTimeout(() => {
        setCommittedIds(prev => new Set(prev).add(vuln.id));
        setCommitting(null);
        setExpandedId(null);
    }, 1800);
  };

  const activeFindings = findings.filter(f => !committedIds.has(f.id));

  if (activeFindings.length === 0) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-12 bg-slate-900/50 border border-slate-800 border-dashed rounded-3xl animate-in zoom-in-95 duration-500">
        <div className="w-16 h-16 bg-emerald-500/10 border border-emerald-500/20 rounded-full flex items-center justify-center mb-4">
           <CheckCircle className="text-emerald-500" size={32} />
        </div>
        <h3 className="text-xl font-bold text-white text-center">Ambiente Seguro</h3>
        <p className="text-slate-500 text-sm mt-2 max-w-xs mx-auto text-center leading-relaxed">
          Nenhuma vulnerabilidade detectada ou todas as correções foram aplicadas.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {activeFindings.map((finding) => (
        <div 
          key={finding.id} 
          className={`bg-slate-900 rounded-2xl border transition-all duration-300 ${
            expandedId === finding.id ? 'border-primary-500 shadow-2xl ring-1 ring-primary-500/20' : 'border-slate-800 hover:border-slate-700'
          }`}
        >
          <div 
            className="p-4 flex items-center justify-between cursor-pointer"
            onClick={() => setExpandedId(expandedId === finding.id ? null : finding.id)}
          >
            <div className="flex items-center gap-4">
              <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black border uppercase tracking-wider ${getSeverityColor(finding.severity)}`}>
                {finding.severity}
              </span>
              <div>
                <h4 className="font-bold text-sm text-white leading-tight">{finding.title}</h4>
                <p className="text-[10px] text-slate-500 mt-1 font-mono uppercase tracking-tighter">{finding.resource}</p>
              </div>
            </div>
            {expandedId === finding.id ? <ChevronUp size={16} className="text-slate-600" /> : <ChevronDown size={16} className="text-slate-600" />}
          </div>

          {expandedId === finding.id && (
            <div className="px-4 pb-5 pt-2 border-t border-slate-800 animate-in slide-in-from-top-2 duration-300">
              <div className="space-y-4">
                <div className="p-3 bg-slate-950 border border-slate-800 rounded-xl">
                    <p className="text-xs text-slate-400 leading-relaxed">{finding.description}</p>
                </div>

                {!aiFix[finding.id] ? (
                  <button 
                    onClick={() => handleGenerateFix(finding)}
                    disabled={loadingFix === finding.id}
                    className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white text-xs font-bold rounded-xl border border-slate-700 flex items-center justify-center gap-2 transition-all disabled:opacity-50"
                  >
                    {loadingFix === finding.id ? <Loader2 className="animate-spin" size={14} /> : <Cpu size={14} className="text-primary-400" />}
                    {loadingFix === finding.id ? 'Gerando com Gemini...' : 'Sugerir Correção com IA'}
                  </button>
                ) : (
                  <div className="space-y-4 animate-in fade-in duration-500">
                    <div className="bg-slate-950 rounded-xl border border-emerald-500/30 overflow-hidden">
                      <div className="bg-emerald-500/10 px-3 py-1.5 border-b border-emerald-500/20 text-[9px] font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                         <Shield size={10} /> Sugestão de Código
                      </div>
                      <pre className="p-4 text-[11px] text-slate-300 font-mono overflow-x-auto">
                        {aiFix[finding.id].replace(/```(hcl|json|terraform)?\n?|\n?```/g, '')}
                      </pre>
                    </div>

                    <button 
                      onClick={() => handleCreatePR(finding)}
                      disabled={committing === finding.id}
                      className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-black rounded-xl shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2 uppercase tracking-widest transition-all"
                    >
                      {committing === finding.id ? <Loader2 className="animate-spin" size={16} /> : <GitPullRequest size={16} />}
                      {committing === finding.id ? 'Criando PR no GitHub...' : 'Corrigir e Criar PR'}
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

