const getIcon = (type: TimelineEvent['type']) => {
    switch (type) {
        case 'SCAN': return <Search size={20} />;
        case 'RISK': return <AlertTriangle size={20} />;
        case 'PR': return <GitPullRequest size={20} />;
        case 'COMPLIANCE': return <CheckCircle size={20} />;
        case 'DRIFT': return <Activity size={20} />;
        default: return <Shield size={20} />;
    }
};

const getIconBg = (type: TimelineEvent['type'], severity?: Severity) => {
    if (severity === Severity.CRITICAL) return 'bg-red-500/10 border-red-500/20 text-red-500';
    if (severity === Severity.HIGH) return 'bg-orange-500/10 border-orange-500/20 text-orange-500';

    switch (type) {
        case 'PR': return 'bg-primary-500/10 border-primary-500/20 text-primary-500';
        case 'COMPLIANCE': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500';
        default: return 'bg-slate-800 border-slate-700 text-slate-400';
    }
};

const getSeverityStyles = (severity: Severity) => {
    switch (severity) {
        case Severity.CRITICAL: return 'bg-red-500/20 text-red-500 border border-red-500/30';
        case Severity.HIGH: return 'bg-orange-500/20 text-orange-500 border border-orange-500/30';
        default: return 'bg-slate-800 text-slate-400';
    }
};

import React, { useMemo } from 'react';
import { parseHclToGraph } from '../services/engine';
import { Shield, Server, Database, Globe, Activity, Lock, Layers } from 'lucide-react';

interface GraphProps {
  code: string;
}

export const Graph: React.FC<GraphProps> = ({ code }) => {
  const { nodes, edges } = useMemo(() => parseHclToGraph(code), [code]);

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-700">
       <div className="flex justify-between items-end">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Infrastructure Graph</h2>
          <p className="text-slate-500 text-sm font-medium">
              Representação lógica da arquitetura definida via HCL (Terraform v1.5+).
          </p>
        </div>
        <div className="flex items-center gap-3 bg-slate-900 p-2 px-4 rounded-xl border border-slate-800">
           <Layers className="text-primary-500" size={16} />
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{nodes.length} Nodes Detectados</span>
        </div>
      </div>

      <div className="flex-1 bg-slate-950 border border-slate-800 rounded-[32px] relative overflow-hidden flex items-center justify-center shadow-2xl">
        {/* Engineering Grid Background */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ 
          backgroundImage: 'radial-gradient(circle, #3b82f6 1px, transparent 1px)', 
          backgroundSize: '30px 30px' 
        }}></div>

        {nodes.length === 0 ? (
          <div className="text-slate-500 flex flex-col items-center p-12 border-2 border-dashed border-slate-900 rounded-[32px] bg-slate-900/20 relative z-10">
             <Layers size={48} className="text-slate-800 mb-4" />
             <p className="font-bold text-white opacity-50">Nenhum recurso detectado no HCL</p>
             <p className="text-xs max-w-xs text-center mt-2">Adicione blocos de <code>resource</code> no Scanner para visualizar a árvore de dependências.</p>
          </div>
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 800 500" className="w-full h-full relative z-10 cursor-grab active:cursor-grabbing">
              <defs>
                  <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="35" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="#1e293b" />
                  </marker>
                  <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                    <feGaussianBlur stdDeviation="5" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                  </filter>
                  <linearGradient id="linkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
                    <stop offset="100%" stopColor="#3b82f6" stopOpacity="0.6" />
                  </linearGradient>
              </defs>

              <g stroke="url(#linkGradient)" strokeWidth="1.5" markerEnd="url(#arrowhead)">
                  {edges.map(edge => {
                      const sourceNode = nodes.find(n => n.id === edge.source);
                      const targetNode = nodes.find(n => n.id === edge.target);
                      if (!sourceNode || !targetNode) return null;
                      return (
                          <line 
                              key={edge.id}
                              x1={sourceNode.position.x} 
                              y1={sourceNode.position.y} 
                              x2={targetNode.position.x} 
                              y2={targetNode.position.y} 
                              className="animate-pulse"
                          />
                      );
                  })}
              </g>

              {nodes.map(node => (
                  <Node 
                      key={node.id} 
                      x={node.position.x} 
                      y={node.position.y} 
                      label={node.data.label} 
                      type={node.data.category} 
                      status={node.status} 
                      subType={node.data.resource_type}
                  />
              ))}
          </svg>
        )}

        {/* Legend Overlay */}
        <div className="absolute bottom-8 left-8 bg-slate-900/80 backdrop-blur-xl p-5 rounded-2xl border border-slate-800 shadow-2xl">
            <div className="text-[10px] font-black text-slate-500 mb-4 uppercase tracking-[0.2em]">Map Hierarchy</div>
            <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                <LegendItem color="bg-blue-500" label="Network" />
                <LegendItem color="bg-purple-500" label="Compute" />
                <LegendItem color="bg-yellow-500" label="Storage" />
                <LegendItem color="bg-emerald-500" label="Security" />
            </div>
            <div className="mt-4 pt-4 border-t border-slate-800 flex items-center gap-2">
                <span className="w-3 h-3 rounded-full border-2 border-red-500 animate-pulse"></span>
                <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Active Risk Detected</span>
            </div>
        </div>

        {/* Technical Data Overlay */}
        <div className="absolute top-8 right-8 text-right hidden lg:block">
           <div className="text-[10px] font-mono text-primary-500/50 uppercase tracking-widest mb-1">Topology Engine v1.0</div>
           <div className="text-[9px] font-mono text-slate-600 max-w-[200px] leading-relaxed">
              X-COORD: DYNAMIC_SPACING<br/>
              Y-COORD: RESOURCE_WEIGHT<br/>
              FLOW: DEPENDENCY_TREE
           </div>
        </div>
      </div>
    </div>
  );
};

const Node = ({ x, y, label, type, status, subType }: any) => {
    let color = "#3b82f6"; // Network
    let Icon = Globe;
    if (type === 'compute') { color = "#a855f7"; Icon = Server; }
    if (type === 'storage') { color = "#eab308"; Icon = Database; }
    if (type === 'security') { color = "#10b981"; Icon = Shield; }

    const isRisk = status === 'risk';
    const stroke = isRisk ? '#ef4444' : color;

    return (
        <g style={{ cursor: 'pointer' }} className="transition-all duration-300 hover:scale-110 group">
            {/* Outer Glow */}
            <circle cx={x} cy={y} r="35" fill={color} fillOpacity="0.05" stroke={stroke} strokeOpacity="0.1" strokeWidth="1" />

            {/* Main Body */}
            <circle 
              cx={x} cy={y} r="28" 
              fill="#0f172a" 
              stroke={stroke} 
              strokeWidth={isRisk ? "2.5" : "1.5"} 
              className={isRisk ? 'animate-pulse' : ''}
              style={isRisk ? { filter: 'url(#glow)' } : {}}
            />

            {/* Icon Circle */}
            <circle cx={x} cy={y} r="18" fill={color} fillOpacity="0.1" />

            <foreignObject x={x - 10} y={y - 10} width="20" height="20">
               <div className="flex items-center justify-center w-full h-full">
                  <Icon size={14} color={color} />
               </div>
            </foreignObject>

            {/* Labels */}
            <text x={x} y={y + 45} textAnchor="middle" fill="#f8fafc" fontSize="11" fontWeight="900" className="tracking-tighter">{label}</text>
            <text x={x} y={y + 58} textAnchor="middle" fill="#64748b" fontSize="9" fontWeight="bold" className="uppercase tracking-widest">{subType}</text>
        </g>
    );
};

const LegendItem = ({ color, label }: any) => (
