import React, { useState, useRef, useEffect } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, Code2, AlertTriangle, Sparkles, CheckCircle2, Terminal, Info } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange }) => {
  const [scanning, setScanning] = useState(false);
  const [results, setResults] = useState<Vulnerability[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const performScan = async () => {
    setScanning(true);
    setResults(null);
    setError(null);

    await new Promise(resolve => setTimeout(resolve, 1200));

    const localFindings: Vulnerability[] = [];
    const secretFindings = scanForSecrets(code);
    localFindings.push(...secretFindings);

    if (code.includes('0.0.0.0/0')) {
      localFindings.push({
        id: `infra-sg-${Date.now()}`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Network Exposure: 0.0.0.0/0',
        description: 'A Security Group rule allows traffic from any IP address. This violates SOC2 CC6.6 and increases attack surface significantly.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6', 'ISO27001_A.13']
      });
    }

    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanJson);
        if (parsed.findings) {
          const aiFindings = parsed.findings.map((f: any, idx: number) => ({
            id: `ai-vuln-${Date.now()}-${idx}`,
            ruleId: f.ruleId || 'AI_SEC_RISK',
            title: f.title,
            description: f.description,
            severity: f.severity || Severity.MEDIUM,
            status: ScanStatus.OPEN,
            resource: f.resource || 'Terraform Module',
            complianceMapping: ['AI_ASSISTED_CHECK']
          }));
          localFindings.push(...aiFindings);
        }
      }
    } catch (e) {
      console.warn("AI parsing failed.");
    }

    setResults(localFindings);
    setScanning(false);
  };

  const renderHighlightedCode = (text: string) => {
    const lines = text.split('\n');
    return lines.map((line, i) => {
      // Basic HCL Highlighting
      const highlighted = line
        .replace(/(resource|variable|output|module|provider|locals|terraform)/g, '<span class="text-indigo-400 font-bold">$1</span>')
        .replace(/("[^"]*")/g, '<span class="text-emerald-400">$1</span>')
        .replace(/(#.*)/g, '<span class="text-slate-500 italic">$1</span>')
        .replace(/([0-9.]+)/g, '<span class="text-amber-400">$1</span>')
        .replace(/(=|{|}|\[|\])/g, '<span class="text-slate-400">$1</span>');

      return (
        <div key={i} className="flex min-h-[1.5rem] group">
          <span className="w-10 text-right pr-4 text-slate-700 select-none font-mono text-xs pt-0.5 group-hover:text-slate-500">{i + 1}</span>
          <span className="flex-1 whitespace-pre-wrap font-mono text-sm leading-6" dangerouslySetInnerHTML={{ __html: highlighted || ' ' }} />
        </div>
      );
    });
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2 mb-2">
            <span className="px-2 py-0.5 bg-indigo-500/10 text-indigo-400 text-[10px] font-black uppercase tracking-widest rounded border border-indigo-500/20 flex items-center gap-1">
              <Terminal size={10} /> SAST Engine
            </span>
          </div>
          <h2 className="text-3xl font-black text-white tracking-tight">Security Code Scanner</h2>
          <p className="text-slate-400 text-sm max-w-xl">Deep HCL analysis for secrets, compliance violations, and misconfigurations.</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-900 border border-slate-800 rounded-2xl">
             <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Gemini 3 Flash: Online</span>
          </div>
          <button 
            onClick={performScan}
            disabled={scanning}
            className="bg-primary-600 hover:bg-primary-700 text-white px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-[0.1em] flex items-center gap-2 transition-all disabled:opacity-50 shadow-xl shadow-primary-900/30 active:scale-95"
          >
            {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {scanning ? 'Analyzing Infrastructure...' : 'Run Security Scan'}
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 min-h-[600px]">
        {/* Editor Column */}
        <div className="lg:col-span-7 flex flex-col bg-slate-900 border border-slate-800 rounded-[32px] overflow-hidden shadow-2xl relative">
          <div className="bg-slate-850 px-6 py-4 border-b border-slate-800 flex justify-between items-center">
             <div className="flex items-center gap-3">
                <div className="flex gap-1.5">
                  <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/30"></div>
                  <div className="w-3 h-3 rounded-full bg-amber-500/20 border border-amber-500/30"></div>
                  <div className="w-3 h-3 rounded-full bg-emerald-500/20 border border-emerald-500/30"></div>
                </div>
                <div className="h-4 w-px bg-slate-700 mx-1"></div>
                <div className="flex items-center gap-2 text-slate-400 font-mono text-[10px] uppercase tracking-widest">
                  <Code2 size={12} className="text-indigo-400" />
                  infrastructure.tf
                </div>
             </div>
             <div className="text-[9px] font-black text-slate-600 uppercase tracking-widest">
               HCL v2.0 • Terraform 1.5+
             </div>
          </div>

          <div className="flex-1 relative bg-slate-950 overflow-hidden">
            {/* The actual editable textarea */}
            <textarea 
              ref={textareaRef}
              value={code}
              onChange={(e) => onCodeChange(e.target.value)}
              spellCheck={false}
              className="absolute inset-0 w-full h-full p-6 pl-14 bg-transparent text-transparent caret-white font-mono text-sm leading-6 resize-none focus:outline-none z-10 selection:bg-primary-500/30"
              placeholder="Paste your Terraform code here..."
            />
            {/* The highlighted background */}
            <div className="absolute inset-0 p-6 pointer-events-none overflow-y-auto custom-scrollbar">
              {renderHighlightedCode(code)}
            </div>
          </div>

          <div className="p-3 bg-slate-900 border-t border-slate-800 flex justify-between items-center px-6">
             <span className="text-[10px] text-slate-500 font-mono italic">Line {code.split('\n').length}, Col 1</span>
             <div className="flex items-center gap-4">
                <div className="flex items-center gap-1.5 text-[9px] text-slate-400 font-bold uppercase">
                   <Info size={12} className="text-primary-500" />
                   AI-ready for remediation
                </div>
             </div>
          </div>
        </div>

        {/* Results Column */}
        <div className="lg:col-span-5 space-y-4 h-[650px] overflow-y-auto pr-2 custom-scrollbar">
           {results ? (
             <ScanResults findings={results} codeContext={code} />
           ) : (
             <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-[32px] text-slate-600 p-12 text-center bg-slate-900/20 transition-all hover:bg-slate-900/40">
                <div className="p-6 bg-slate-900 rounded-3xl mb-6 shadow-2xl border border-slate-800 animate-bounce">
                   <AlertTriangle size={64} className="text-slate-800" />
                </div>
                <h3 className="text-xl font-bold text-slate-400">Scan Required</h3>
                <p className="text-sm mt-3 max-w-xs text-slate-500 leading-relaxed">Execute a scan to identify security vulnerabilities, secrets, and compliance gaps in your code.</p>
                <button 
                  onClick={performScan}
                  className="mt-8 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-700 transition-all"
                >
                  Quick Scan
