             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Vulnerability, Severity } from '../types';
import { 
  AlertTriangle, CheckCircle, ChevronDown, ChevronUp, Cpu, 
  GitPullRequest, Loader2, Shield, FileText, Info, Check, 
  ShieldAlert, Lock, Zap, Target, ArrowRight, ShieldCheck, 
  Layers, Globe, Activity
} from 'lucide-react';
import { suggestFix } from '../services/geminiService';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committedIds, setCommittedIds] = useState<Set<string>>(new Set());
  const [committing, setCommitting] = useState<string | null>(null);

  const activeFindings = useMemo(() => findings.filter(f => !committedIds.has(f.id)), [findings, committedIds]);

  const stats = useMemo(() => {
    return {
      critical: activeFindings.filter(f => f.severity === Severity.CRITICAL).length,
      high: activeFindings.filter(f => f.severity === Severity.HIGH).length,
      medium: activeFindings.filter(f => f.severity === Severity.MEDIUM).length,
      low: activeFindings.filter(f => f.severity === Severity.LOW).length,
    };
  }, [activeFindings]);

  const getSeverityStyles = (severity: Severity) => {
    switch (severity) {
      case Severity.CRITICAL: return 'text-red-500 bg-red-500/10 border-red-500/20';
      case Severity.HIGH: return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case Severity.MEDIUM: return 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20';
      case Severity.LOW: return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      default: return 'text-slate-500 bg-slate-500/10 border-slate-500/20';
    }
  };

  const getFindingIcon = (title: string) => {
    const t = title.toLowerCase();
    if (t.includes('secret') || t.includes('key') || t.includes('token')) return <Lock size={16} className="text-amber-500" />;
    if (t.includes('network') || t.includes('port') || t.includes('ingress')) return <Globe size={16} className="text-blue-500" />;
    if (t.includes('encryption') || t.includes('s3') || t.includes('storage')) return <Shield size={16} className="text-emerald-500" />;
    return <Layers size={16} className="text-indigo-500" />;
  };

  const handleGenerateFix = async (vuln: Vulnerability) => {
    if (aiFix[vuln.id]) return;
    setLoadingFix(vuln.id);
    try {
        const fix = await suggestFix(vuln.title, codeContext);
        setAiFix(prev => ({ ...prev, [vuln.id]: fix || "Remediation code generation failed." }));
    } catch (e) {
        setAiFix(prev => ({ ...prev, [vuln.id]: "Error connecting to Gemini AI." }));
    }
    setLoadingFix(null);
  };

  const handleCreatePR = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    setTimeout(() => {
        setCommittedIds(prev => new Set(prev).add(vuln.id));
        setCommitting(null);
        setExpandedId(null);
    }, 1800);
  };

  if (activeFindings.length === 0) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-12 bg-slate-900/40 border border-slate-800 border-dashed rounded-[32px] animate-in zoom-in-95 duration-500">
        <div className="w-20 h-20 bg-emerald-500/10 border border-emerald-500/20 rounded-full flex items-center justify-center mb-6 shadow-2xl shadow-emerald-900/20">
           <ShieldCheck className="text-emerald-500" size={40} />
        </div>
        <h3 className="text-2xl font-black text-white text-center">Infrastructure Secured</h3>
        <p className="text-slate-500 text-sm mt-3 max-w-xs mx-auto text-center leading-relaxed">
          Zero vulnerabilities detected. Your infrastructure code follows current security best practices.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
      {/* Scan Summary Dashboard */}
      <div className="bg-slate-900/60 backdrop-blur-xl border border-slate-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-[0.03]">
          <Target size={120} />
        </div>
        <div className="relative z-10 space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Analysis Results</h3>
            <span className="text-[10px] font-mono text-primary-400 bg-primary-400/10 px-2 py-0.5 rounded border border-primary-400/20 uppercase tracking-tighter">
              {activeFindings.length} Issues Found
            </span>
          </div>

          <div className="grid grid-cols-4 gap-3">
             <StatBox label="Critical" count={stats.critical} color="text-red-500" />
             <StatBox label="High" count={stats.high} color="text-orange-500" />
             <StatBox label="Medium" count={stats.medium} color="text-yellow-500" />
             <StatBox label="Low" count={stats.low} color="text-blue-500" />
          </div>
        </div>
      </div>

      {/* Findings List */}
      <div className="space-y-3">
        {activeFindings.map((finding) => (
          <div 
            key={finding.id} 
            className={`bg-slate-900 rounded-2xl border transition-all duration-300 overflow-hidden ${
              expandedId === finding.id ? 'border-primary-500 shadow-2xl ring-1 ring-primary-500/20 bg-slate-900' : 'border-slate-800 hover:border-slate-700 bg-slate-900/40'
            }`}
          >
            <div 
              className="p-4 flex items-center justify-between cursor-pointer group"
              onClick={() => setExpandedId(expandedId === finding.id ? null : finding.id)}
            >
              <div className="flex items-center gap-4">
                <div className={`p-2.5 rounded-xl border ${getSeverityStyles(finding.severity)}`}>
                  {getFindingIcon(finding.title)}
                </div>
                <div className="min-w-0">
                  <div className="flex items-center gap-2 mb-0.5">
                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase tracking-widest border ${getSeverityStyles(finding.severity)}`}>
                      {finding.severity}
                    </span>
                    <h4 className="font-bold text-xs text-slate-200 truncate group-hover:text-white transition-colors">{finding.title}</h4>
                  </div>
                  <p className="text-[9px] text-slate-500 font-mono uppercase tracking-tighter truncate opacity-80 group-hover:opacity-100">{finding.resource}</p>
                </div>
              </div>
              <div className="p-1 bg-slate-800 rounded-lg group-hover:bg-slate-700 transition-colors">
                {expandedId === finding.id ? <ChevronUp size={14} className="text-slate-400" /> : <ChevronDown size={14} className="text-slate-400" />}
              </div>
            </div>

            {expandedId === finding.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-800/50 animate-in slide-in-from-top-2 duration-300 bg-slate-950/20">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-[9px] font-black text-slate-600 uppercase tracking-widest">
                       <Info size={12} className="text-primary-500" /> Risk Analysis
                    </div>
                    <div className="p-4 bg-slate-950/80 border border-slate-800/50 rounded-xl">
                      <p className="text-xs text-slate-400 leading-relaxed italic">"{finding.description}"</p>
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {finding.complianceMapping?.map((c) => (
                      <span key={c} className="text-[8px] font-black text-emerald-400/70 bg-emerald-500/5 px-2 py-0.5 rounded border border-emerald-500/10">
                        {c.replace('_', ' ')}
                      </span>
                    ))}
                  </div>

                  {!aiFix[finding.id] ? (
                    <button 
                      onClick={(e) => { e.stopPropagation(); handleGenerateFix(finding); }}
                      disabled={loadingFix === finding.id}
                      className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black rounded-xl border border-slate-700 flex items-center justify-center gap-2 transition-all disabled:opacity-50 uppercase tracking-widest"
                    >
                      {loadingFix === finding.id ? <Loader2 className="animate-spin" size={14} /> : <Zap size={14} className="text-amber-400" />}
                      {loadingFix === finding.id ? 'Analyzing Risk Context...' : 'Generate AI Remediation'}
                    </button>
                  ) : (
                    <div className="space-y-4 animate-in fade-in duration-500">
                      <div className="bg-slate-950 rounded-2xl border border-emerald-500/20 overflow-hidden shadow-inner">
                        <div className="bg-emerald-500/5 px-4 py-2 border-b border-emerald-500/10 text-[9px] font-black text-emerald-400 uppercase tracking-widest flex justify-between items-center">
                           <div className="flex items-center gap-2">
                             <Shield size={10} /> Remediation Strategy
                           </div>
                           <span className="opacity-50 font-mono">FIX_SUGGESTION_v1</span>
                        </div>
                        <pre className="p-5 text-[11px] text-emerald-100/80 font-mono overflow-x-auto whitespace-pre leading-relaxed">
                          {aiFix[finding.id].replace(/```(hcl|json|terraform)?\n?|\n?```/g, '')}
                        </pre>
                      </div>

                      <div className="grid grid-cols-1 gap-3">
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleCreatePR(finding); }}
                          disabled={committing === finding.id}
                          className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-black rounded-xl shadow-lg shadow-emerald-900/30 flex items-center justify-center gap-3 uppercase tracking-widest transition-all hover:-translate-y-0.5 active:translate-y-0"
                        >
                          {committing === finding.id ? <Loader2 className="animate-spin" size={16} /> : <GitPullRequest size={16} />}
                          {committing === finding.id ? 'Branching & Pushing...' : 'Apply Fix & Create PR'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

