import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity } from './types';
import { calculateSecurityScore } from './services/engine';
import { Play, CheckCircle, Sparkles, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [showTour, setShowTour] = useState(true);

  // Calcular score em tempo real baseado no estado atual
  const securityScore = useMemo(() => calculateSecurityScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    const auth = localStorage.getItem('cg_auth');
    if (auth === 'true') setIsAuthenticated(true);
  }, []);

  const addTimelineEvent = (event: Omit<TimelineEvent, 'id' | 'timestamp'>) => {
    const newEvent: TimelineEvent = {
      ...event,
      id: `ev-${Date.now()}`,
      timestamp: new Date().toISOString()
    };
    setTimelineEvents(prev => [newEvent, ...prev]);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    addTimelineEvent({
      type: 'SCAN',
      title: 'Sessão Iniciada',
      description: 'Administrador John Doe acessou o console de segurança.'
    });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
    setIsAuditorMode(false);
  };

  const updateVulnerabilities = (newVulns: Vulnerability[]) => {
    setVulnerabilities(newVulns);
    if (newVulns.length > 0) {
      addTimelineEvent({
        type: 'RISK',
        title: 'Vulnerabilidades Detectadas',
        description: `${newVulns.length} riscos encontrados no código Terraform.`,
        severity: Severity.HIGH
      });
    }
  };

  const applyRemediation = (vulnId: string, fixCode: string) => {
    // Simulação: se for o S3, corrigimos o acl. Se for o SG, corrigimos o cidr.
    let updatedCode = terraformCode;
    if (fixCode.includes('private')) {
      updatedCode = updatedCode.replace('public-read', 'private');
    }
    if (fixCode.includes('10.0.0.0/16')) {
      updatedCode = updatedCode.replace('0.0.0.0/0', '10.0.0.0/16');
    }

    setTerraformCode(updatedCode);
    setVulnerabilities(prev => prev.filter(v => v.id !== vulnId));
    addTimelineEvent({
      type: 'PR',
      title: 'Auto-PR Merged',
      description: `Vulnerabilidade resolvida via IA. Código atualizado para padrões de segurança.`,
      severity: Severity.LOW,
      metadata: { action: 'REMEDIATION_APPLIED' }
    });
  };

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard': 
        return <Dashboard 
          isAuditorMode={isAuditorMode} 
          vulnerabilities={vulnerabilities} 
          drifts={drifts}
          score={securityScore}
        />;
      case 'scanner': 
        return <Scanner 
          code={terraformCode} 
          onCodeChange={setTerraformCode} 
          onScanComplete={updateVulnerabilities}
          vulnerabilities={vulnerabilities}
          onApplyFix={applyRemediation}
        />;
      case 'drift': 
        return <Drift 
          isAuditorMode={isAuditorMode} 
          drifts={drifts}
          setDrifts={setDrifts}
          onSync={(item) => {
             addTimelineEvent({
               type: 'DRIFT',
               title: 'Drift Sincronizado',
               description: `Recurso ${item.resource} sincronizado com a nuvem.`,
               severity: Severity.LOW
             });
          }}
        />;
      case 'graph': return <Graph code={terraformCode} vulnerabilities={vulnerabilities} />;
      case 'compliance': return <Compliance vulnerabilities={vulnerabilities} />;
      case 'automation': return <AutomationHub />;
      case 'sales-playbook': return <SalesPlaybook />;
      case 'report': return <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />;
      case 'timeline': return <Timeline events={timelineEvents} />;
      case 'settings': return <Settings />;
      default: return <Dashboard score={securityScore} vulnerabilities={vulnerabilities} drifts={drifts} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-primary-500/30">
      <Sidebar currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout} isAuditorMode={isAuditorMode} />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col">
        {isAuditorMode && <AuditorBanner />}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-indigo-600 to-purple-600 z-10"></div>
        <div className="p-6 flex-1">{renderContent()}</div>

        {showTour && (
          <div className="fixed bottom-6 left-[280px] w-72 bg-slate-900/90 backdrop-blur-xl border border-primary-500/30 rounded-2xl shadow-2xl z-50 p-5 animate-in slide-in-from-bottom-10 duration-500">
            <button onClick={() => setShowTour(false)} className="absolute top-3 right-3 text-slate-500 hover:text-white"><X size={14}/></button>
            <div className="flex items-center gap-2 mb-4"><Sparkles className="text-primary-400" size={18} /><h4 className="font-bold text-sm text-white">CloudGuardian Interactive</h4></div>
            <div className="space-y-3">
              <TourItem done={currentView === 'scanner'} label="1. Rodar Scan de IA" onClick={() => setCurrentView('scanner')} />
              <TourItem done={vulnerabilities.length > 0 && currentView === 'dashboard'} label="2. Ver Impacto no Score" onClick={() => setCurrentView('dashboard')} />
              <TourItem done={currentView === 'compliance'} label="3. Validar SOC2" onClick={() => setCurrentView('compliance')} />
              <TourItem done={currentView === 'report'} label="4. Baixar Relatório" onClick={() => setCurrentView('report')} />
            </div>
          </div>
        )}
      </main>
      <div className="fixed bottom-4 right-4 z-50 flex items-center gap-2 bg-slate-900/50 backdrop-blur-md border border-slate-800 p-2 rounded-full px-4 shadow-2xl">
        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Demo Mode:</span>
        <button onClick={() => setIsAuditorMode(!isAuditorMode)} className={`px-3 py-1 rounded-full text-[9px] font-black uppercase transition-all ${isAuditorMode ? 'bg-amber-500 text-slate-950' : 'bg-primary-600 text-white'}`}>
            {isAuditorMode ? 'Auditor' : 'Admin'}
        </button>
      </div>
    </div>
  );
}

const TourItem = ({ label, done, onClick }: { label: string, done: boolean, onClick: () => void }) => (
  <button onClick={onClick} className={`w-full flex items-center justify-between p-2 rounded-lg text-left text-xs transition-all ${done ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-slate-950 border border-slate-800 text-slate-400 hover:bg-slate-800'}`}>
    <span>{label}</span>{done ? <CheckCircle size={14} /> : <Play size={14} className="opacity-50" />}
  </button>
);

export default App;

import React, { useState, useRef } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, Code2, AlertTriangle, Terminal, Info } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: void) => void;
  onScanComplete: (vulns: Vulnerability[]) => void;
  vulnerabilities: Vulnerability[];
  onApplyFix: (id: string, code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange, onScanComplete, vulnerabilities, onApplyFix }) => {
  const [scanning, setScanning] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const performScan = async () => {
    setScanning(true);
    await new Promise(resolve => setTimeout(resolve, 1500));

    const localFindings: Vulnerability[] = [];
    const secretFindings = scanForSecrets(code);
    localFindings.push(...secretFindings);

    if (code.includes('public-read')) {
      localFindings.push({
        id: `vuln-s3-public`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket: Acesso Público Ativo',
        description: 'O bucket possui ACL "public-read", o que expõe dados sensíveis à internet aberta.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        complianceMapping: ['SOC2_CC6.1', 'ISO27001_A.18']
      });
    }

    if (code.includes('0.0.0.0/0')) {
      localFindings.push({
        id: `vuln-sg-open`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group: Porta Exposta (0.0.0.0/0)',
        description: 'Regra de entrada permite tráfego de qualquer IP. Alto risco de força bruta.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6']
      });
    }

    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanJson);
        if (parsed.findings) {
          const aiFindings = parsed.findings.map((f: any, idx: number) => ({
            id: `ai-vuln-${idx}`,
            ruleId: f.ruleId || 'AI_SEC_RISK',
            title: f.title,
            description: f.description,
            severity: f.severity || Severity.MEDIUM,
            status: ScanStatus.OPEN,
            resource: f.resource || 'Terraform Module',
            complianceMapping: ['AI_ASSISTED_CHECK']
          }));
          localFindings.push(...aiFindings);
        }
      }
    } catch (e) { console.warn("Gemini limit reached or error."); }

    onScanComplete(localFindings);
    setScanning(false);
  };

  const renderHighlightedCode = (text: string) => {
    return text.split('\n').map((line, i) => {
      const highlighted = line
        .replace(/(resource|variable|output|module|provider|locals|terraform)/g, '<span class="text-indigo-400 font-bold">$1</span>')
        .replace(/("[^"]*")/g, '<span class="text-emerald-400">$1</span>')
        .replace(/(#.*)/g, '<span class="text-slate-500 italic">$1</span>')
        .replace(/([0-9.]+)/g, '<span class="text-amber-400">$1</span>')
        .replace(/(=|{|}|\[|\])/g, '<span class="text-slate-400">$1</span>');

      return (
        <div key={i} className="flex min-h-[1.5rem] group">
          <span className="w-10 text-right pr-4 text-slate-700 select-none font-mono text-xs pt-0.5">{i + 1}</span>
          <span className="flex-1 whitespace-pre-wrap font-mono text-sm leading-6" dangerouslySetInnerHTML={{ __html: highlighted || ' ' }} />
        </div>
      );
    });
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tight uppercase italic">Security Scanner</h2>
          <p className="text-slate-400 text-sm">Análise estática (SAST) e detecção de segredos em tempo real.</p>
        </div>
        <button onClick={performScan} disabled={scanning} className="bg-primary-600 hover:bg-primary-700 text-white px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all disabled:opacity-50 shadow-xl shadow-primary-900/30">
          {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
          {scanning ? 'Analisando...' : 'Executar Scan de Segurança'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 min-h-[600px]">
        <div className="lg:col-span-7 flex flex-col bg-slate-900 border border-slate-800 rounded-[32px] overflow-hidden shadow-2xl relative">
          <div className="bg-slate-850 px-6 py-4 border-b border-slate-800 flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-500">
            <span>infrastructure.tf</span>
            <span>HCL v2.0</span>
          </div>
          <div className="flex-1 relative bg-slate-950 overflow-hidden">
            <textarea value={code} onChange={(e) => onCodeChange(e.target.value)} className="absolute inset-0 w-full h-full p-6 pl-14 bg-transparent text-transparent caret-white font-mono text-sm leading-6 resize-none focus:outline-none z-10 selection:bg-primary-500/30" spellCheck={false} />
            <div className="absolute inset-0 p-6 pointer-events-none overflow-y-auto">{renderHighlightedCode(code)}</div>
          </div>
        </div>

        <div className="lg:col-span-5 space-y-4">
           {vulnerabilities.length > 0 || scanning ? (
             <ScanResults findings={vulnerabilities} codeContext={code} onApplyFix={onApplyFix} />
           ) : (
             <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-[32px] text-slate-600 p-12 text-center bg-slate-900/20">
                <AlertTriangle size={64} className="opacity-20 mb-4" />
                <h3 className="text-xl font-bold text-slate-400">Scan Necessário</h3>
                <p className="text-sm mt-3 text-slate-500">Rode o scanner para encontrar riscos e vulnerabilidades.</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2, Shield, Lock, Zap, Target, Globe, Layers } from 'lucide-react';
import { suggestFix } from '../services/geminiService';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
  onApplyFix: (id: string, code: string) => void;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext, onApplyFix }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committing, setCommitting] = useState<string | null>(null);

  const stats = useMemo(() => ({
    critical: findings.filter(f => f.severity === Severity.CRITICAL).length,
    high: findings.filter(f => f.severity === Severity.HIGH).length,
    total: findings.length
  }), [findings]);

  const handleGenerateFix = async (vuln: Vulnerability) => {
    setLoadingFix(vuln.id);
    try {
        const fix = await suggestFix(vuln.title, codeContext);
        setAiFix(prev => ({ ...prev, [vuln.id]: fix || "/* Error generating fix */" }));
    } catch (e) { setAiFix(prev => ({ ...prev, [vuln.id]: "/* AI Error */" })); }
    setLoadingFix(null);
  };

  const handleFixAndCommit = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    setTimeout(() => {
        onApplyFix(vuln.id, aiFix[vuln.id] || '');
        setCommitting(null);
        setExpandedId(null);
    }, 1500);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        <div className="flex justify-between items-center mb-4 text-[10px] font-black uppercase tracking-widest text-slate-500">
           <span>Resultados do Scan</span>
           <span className="text-primary-400">{stats.total} Achados</span>
        </div>
        <div className="grid grid-cols-2 gap-3">
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-red-500/10">
              <div className="text-xl font-black text-red-500">{stats.critical}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Críticos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-orange-500/10">
              <div className="text-xl font-black text-orange-500">{stats.high}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Altos</div>
           </div>
        </div>
      </div>

      <div className="space-y-3">
        {findings.map((f) => (
          <div key={f.id} className={`bg-slate-900 rounded-2xl border transition-all ${expandedId === f.id ? 'border-primary-500 shadow-2xl bg-slate-900' : 'border-slate-800 hover:border-slate-700 bg-slate-900/40'}`}>
            <div className="p-4 flex items-center justify-between cursor-pointer" onClick={() => setExpandedId(expandedId === f.id ? null : f.id)}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg border ${f.severity === Severity.CRITICAL ? 'text-red-500 bg-red-500/10 border-red-500/20' : 'text-orange-500 bg-orange-500/10 border-orange-500/20'}`}>
                  {f.title.includes('S3') ? <Shield size={16}/> : <Globe size={16}/>}
                </div>
                <div>
                   <h4 className="font-bold text-xs text-slate-200">{f.title}</h4>
                   <p className="text-[9px] text-slate-500 font-mono uppercase">{f.resource}</p>
