interface DriftProps {
  isAuditorMode?: boolean;
  drifts: DriftItem[];
  setDrifts: (drifts: DriftItem[]) => void;
  onSync: (item: DriftItem) => void;
}

export const Drift: React.FC<DriftProps> = ({ isAuditorMode, drifts, setDrifts, onSync }) => {
  const [scanning, setScanning] = useState(false);
  const [syncingId, setSyncingId] = useState<string | null>(null);

  const runDriftCheck = () => {
    setScanning(true);
    setTimeout(() => {
      setDrifts([
        { id: 'drift-1', resource: 'aws_s3_bucket.data', property: 'acl', terraformValue: 'private', cloudValue: 'public-read', severity: Severity.CRITICAL },
        { id: 'drift-2', resource: 'aws_security_group.web', property: 'ingress.cidr', terraformValue: '10.0.0.0/16', cloudValue: '0.0.0.0/0', severity: Severity.HIGH }
      ]);
      setScanning(false);
    }, 1500);
  };

  const handleSync = (item: DriftItem) => {
    setSyncingId(item.id);
    setTimeout(() => {
      setDrifts(drifts.filter(d => d.id !== item.id));
      onSync(item);
      setSyncingId(null);
    }, 2000);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold text-white flex items-center gap-3 italic uppercase tracking-tighter">Drift Detection</h2>
