        </div>
        <button onClick={runDriftCheck} disabled={scanning} className="bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest border border-slate-700 transition-all flex items-center gap-2">
          {scanning ? <Loader2 className="animate-spin" size={16} /> : <RefreshCw size={16} />}
          Atualizar Análise
        </button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {drifts.length === 0 && !scanning && (
            <div className="bg-slate-900/50 border border-slate-800 border-dashed p-12 flex flex-col items-center justify-center rounded-3xl animate-in zoom-in-95">
                <ShieldCheck className="text-emerald-500 mb-4" size={48} />
                <h3 className="text-lg font-bold text-white">Nenhum Drift Detectado</h3>
                <p className="text-slate-500 text-sm mt-1">Sua infraestrutura está 100% sincronizada com o Terraform.</p>
            </div>
        )}
        {drifts.map((item) => (
          <div key={item.id} className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden shadow-xl hover:border-slate-700 transition-all">
            <div className="p-4 bg-slate-800/50 border-b border-slate-800 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <AlertCircle className="text-red-500" size={16} />
                    <span className="font-mono text-xs text-white uppercase">{item.resource}</span>
                </div>
                <span className={`text-[9px] font-black px-2 py-0.5 rounded border ${item.severity === 'CRITICAL' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-orange-500/10 text-orange-500 border-orange-500/20'}`}>{item.severity}</span>
            </div>
            <div className="p-5 grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
                <div><span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Propriedade</span><code className="text-primary-400 text-xs">{item.property}</code></div>
                <div className="flex flex-col"><span className="text-[8px] font-black text-slate-500 uppercase block mb-1">HCL (Desejado)</span><div className="bg-slate-950 p-2 rounded text-xs text-slate-400 border border-slate-800 font-mono">{item.terraformValue}</div></div>
                <div className="flex flex-col relative"><ArrowRight className="absolute left-[-20px] top-1/2 -translate-y-1/2 text-slate-700 hidden md:block" /><span className="text-[8px] font-black text-red-500 uppercase block mb-1">Nuvem (Real)</span><div className="bg-red-500/5 p-2 rounded text-xs text-red-400 border border-red-500/20 font-mono">{item.cloudValue}</div></div>
            </div>
            <div className="px-5 py-3 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
                <button onClick={() => handleSync(item)} disabled={isAuditorMode || syncingId === item.id} className="text-[10px] font-black px-6 py-2 rounded-xl uppercase transition-all bg-primary-600 hover:bg-primary-700 text-white flex items-center gap-2 shadow-lg shadow-primary-900/20">
                    {syncingId === item.id ? <Loader2 className="animate-spin" size={12} /> : <CheckCircle size={12}/>}
