import React, { useMemo } from 'react';
import { parseHclToGraph } from '../services/engine';
import { Shield, Server, Database, Globe, Layers } from 'lucide-react';
import { Vulnerability } from '../types';

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities }) => {
  const { nodes, edges } = useMemo(() => {
    const graph = parseHclToGraph(code);
    // Cruzar dados com vulnerabilidades reais
    const enrichedNodes = graph.nodes.map(node => {
        const hasRisk = vulnerabilities.some(v => v.resource.includes(node.id) || node.id.includes(v.resource));
        return { ...node, status: hasRisk ? 'risk' : 'healthy' as any };
    });
    return { nodes: enrichedNodes, edges: graph.edges };
  }, [code, vulnerabilities]);

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-700">
       <div className="flex justify-between items-end">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Infrastructure Graph</h2>
          <p className="text-slate-500 text-sm font-medium">
              Representação visual de dependências e estado de segurança.
          </p>
        </div>
        <div className="flex items-center gap-3 bg-slate-900 p-2 px-4 rounded-xl border border-slate-800">
           <Layers className="text-primary-500" size={16} />
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{nodes.length} Recursos Mapeados</span>
        </div>
      </div>

      <div className="flex-1 bg-slate-950 border border-slate-800 rounded-[40px] relative overflow-hidden flex items-center justify-center shadow-2xl">
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ 
          backgroundImage: 'radial-gradient(circle, #3b82f6 1px, transparent 1px)', 
          backgroundSize: '40px 40px' 
        }}></div>

        {nodes.length === 0 ? (
          <div className="text-slate-500 flex flex-col items-center p-12 border-2 border-dashed border-slate-900 rounded-[32px] bg-slate-900/20 relative z-10">
             <Layers size={48} className="text-slate-800 mb-4" />
             <p className="font-bold text-white opacity-50 uppercase tracking-widest text-xs">Aguardando definição HCL</p>
          </div>
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 800 500" className="w-full h-full relative z-10">
              <defs>
                  <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="35" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="#1e293b" />
                  </marker>
                  <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                    <feGaussianBlur stdDeviation="3" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                  </filter>
                  <linearGradient id="linkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.1" />
                    <stop offset="100%" stopColor="#3b82f6" stopOpacity="0.4" />
                  </linearGradient>
              </defs>

              <g stroke="url(#linkGradient)" strokeWidth="1">
                  {edges.map(edge => {
                      const sourceNode = nodes.find(n => n.id === edge.source);
                      const targetNode = nodes.find(n => n.id === edge.target);
                      if (!sourceNode || !targetNode) return null;
                      return <line key={edge.id} x1={sourceNode.position.x} y1={sourceNode.position.y} x2={targetNode.position.x} y2={targetNode.position.y} />;
                  })}
              </g>

              {nodes.map(node => (
                  <Node 
                      key={node.id} 
                      x={node.position.x} 
                      y={node.position.y} 
                      label={node.data.label} 
                      type={node.data.category} 
                      status={node.status} 
                      subType={node.data.resource_type}
                  />
              ))}
          </svg>
        )}

        <div className="absolute bottom-8 left-8 bg-slate-900/90 backdrop-blur-xl p-4 rounded-2xl border border-slate-800 shadow-2xl flex flex-col gap-2">
            <LegendItem color="bg-blue-500" label="Rede" />
            <LegendItem color="bg-purple-500" label="Compute" />
            <LegendItem color="bg-yellow-500" label="Storage" />
            <LegendItem color="bg-emerald-500" label="Segurança" />
        </div>
      </div>
    </div>
  );
};

const Node = ({ x, y, label, type, status, subType }: any) => {
    let color = "#3b82f6";
    let Icon = Globe;
    if (type === 'compute') { color = "#a855f7"; Icon = Server; }
    if (type === 'storage') { color = "#eab308"; Icon = Database; }
    if (type === 'security') { color = "#10b981"; Icon = Shield; }

    const isRisk = status === 'risk';
    const stroke = isRisk ? '#ef4444' : color;

    return (
        <g className="transition-all duration-500 cursor-pointer">
            <circle cx={x} cy={y} r="28" fill="#020617" stroke={stroke} strokeWidth={isRisk ? "2" : "1"} className={isRisk ? 'animate-pulse' : ''} style={isRisk ? { filter: 'url(#glow)' } : {}} />
            <foreignObject x={x - 10} y={y - 10} width="20" height="20">
               <div className="flex items-center justify-center w-full h-full">
                  <Icon size={14} color={isRisk ? '#ef4444' : color} />
               </div>
            </foreignObject>
            <text x={x} y={y + 40} textAnchor="middle" fill="#f8fafc" fontSize="10" fontWeight="bold" className="tracking-tight">{label}</text>
            <text x={x} y={y + 52} textAnchor="middle" fill="#475569" fontSize="8" fontWeight="bold" className="uppercase tracking-widest">{subType}</text>
        </g>
    );
};

const LegendItem = ({ color, label }: any) => (
  <div className="flex items-center gap-2">
    <div className={`w-1.5 h-1.5 rounded-full ${color}`}></div>
    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
  </div>
);

import React, { useState, useRef } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, AlertTriangle } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
  onScanComplete: (vulns: Vulnerability[]) => void;
  vulnerabilities: Vulnerability[];
  onApplyFix: (id: string, code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange, onScanComplete, vulnerabilities, onApplyFix }) => {
  const [scanning, setScanning] = useState(false);

  const performScan = async () => {
    setScanning(true);
    await new Promise(resolve => setTimeout(resolve, 1500));

    const localFindings: Vulnerability[] = [];
    const secretFindings = scanForSecrets(code);
    localFindings.push(...secretFindings);

    if (code.includes('public-read')) {
      localFindings.push({
        id: `vuln-s3-public`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket: Acesso Público Ativo',
        description: 'O bucket possui ACL "public-read", o que expõe dados sensíveis à internet aberta.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        complianceMapping: ['SOC2_CC6.1', 'ISO27001_A.18']
      });
    }

    if (code.includes('0.0.0.0/0')) {
      localFindings.push({
        id: `vuln-sg-open`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group: Porta Exposta (0.0.0.0/0)',
        description: 'Regra de entrada permite tráfego de qualquer IP. Alto risco de força bruta.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6']
      });
    }

    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanJson);
        if (parsed.findings) {
          const aiFindings = parsed.findings.map((f: any, idx: number) => ({
            id: `ai-vuln-${idx}-${Date.now()}`,
            ruleId: f.ruleId || 'AI_SEC_RISK',
            title: f.title,
            description: f.description,
            severity: f.severity || Severity.MEDIUM,
            status: ScanStatus.OPEN,
            resource: f.resource || 'Terraform Module',
            complianceMapping: ['AI_ASSISTED_CHECK']
          }));
          localFindings.push(...aiFindings);
        }
      }
    } catch (e) { console.warn("Gemini limit reached or error."); }

    onScanComplete(localFindings);
    setScanning(false);
  };

  const renderHighlightedCode = (text: string) => {
    return text.split('\n').map((line, i) => {
      const highlighted = line
        .replace(/(resource|variable|output|module|provider|locals|terraform)/g, '<span class="text-indigo-400 font-bold">$1</span>')
        .replace(/("[^"]*")/g, '<span class="text-emerald-400">$1</span>')
        .replace(/(#.*)/g, '<span class="text-slate-500 italic">$1</span>')
        .replace(/([0-9.]+)/g, '<span class="text-amber-400">$1</span>')
