/**
 * Security Posture Score Calculation Engine
 */
export const calculateSecurityScore = (findings: Vulnerability[], drifts: DriftItem[]): SecurityScore => {
  // Base scores
  let infraBase = 100;
  let secretBase = 100;
  let driftBase = 100;
  let complianceBase = 100;

  // Deduction logic - infra e secrets
  findings.forEach(f => {
    const penalty = f.severity === Severity.CRITICAL ? 20 : f.severity === Severity.HIGH ? 10 : 5;
    if (f.ruleId.includes('SECRET') || f.ruleId.includes('AWS_ACCESS') || f.ruleId.includes('ENTROPY')) {
      secretBase -= penalty;
    } else {
      infraBase -= penalty;
    }
  });

  // Drift impact
  drifts.forEach(d => {
    const penalty = d.severity === Severity.CRITICAL ? 15 : 7;
    driftBase -= penalty;
  });

  // Ensure no negative scores
  infraBase = Math.max(0, infraBase);
  secretBase = Math.max(0, secretBase);
  driftBase = Math.max(0, driftBase);

  // Compliance is an average of the robustness of other categories
  complianceBase = Math.round((infraBase + secretBase + driftBase) / 3);

  // Weighted Average for Total Score
  const total = Math.round((infraBase * 0.35) + (secretBase * 0.35) + (driftBase * 0.20) + (complianceBase * 0.10));

  return {
    total,
    infrastructure: infraBase,
    secrets: secretBase,
    compliance: complianceBase,
    drift: driftBase,
    trend: +2.4 // Mock trend
  };
};

/**
 * SecretScannerService & Engine Simulation
 */
const calculateShannonEntropy = (str: string): number => {
  if (!str) return 0;
  const len = str.length;
  const frequencies = new Map<string, number>();
  for (const char of str) {
    frequencies.set(char, (frequencies.get(char) || 0) + 1);
  }
  let entropy = 0;
  for (const count of frequencies.values()) {
    const p = count / len;
    entropy -= p * Math.log2(p);
  }
  return entropy;
};

export const scanForSecrets = (content: string): Vulnerability[] => {
    const findings: Vulnerability[] = [];
    const lines = content.split('\n');
    const patterns = [
        { name: 'AWS Access Key', regex: /AKIA[0-9A-Z]{16}/, id: 'AWS_ACCESS_KEY', compliance: ['SOC2_CC6.1'] },
        { name: 'AWS Secret Key', regex: /(aws_secret_access_key|secret_key)\s*=\s*["']([a-zA-Z0-9/+]{40})["']/, id: 'AWS_SECRET_KEY', compliance: ['SOC2_CC6.1'] },
        { name: 'Generic Token', regex: /(api_key|access_token|secret)[\s=:"']+([a-zA-Z0-9-_]{20,})/i, id: 'GENERIC_TOKEN', compliance: ['SOC2_CC6.1'] }
    ];

    lines.forEach((line, index) => {
        patterns.forEach(p => {
            if (line.match(p.regex)) {
                 findings.push({
                    id: `secret-${index}-${p.id}`,
                    ruleId: p.id,
                    title: `Potential ${p.name} found`,
                    description: `A pattern matching ${p.name} was detected in line ${index + 1}.`,
                    severity: Severity.CRITICAL,
                    status: ScanStatus.OPEN,
                    resource: 'code_scan',
                    line: index + 1,
                    remediation: 'Move it to AWS Secrets Manager.',
                    complianceMapping: p.compliance
                 });
            }
        });
        const tokens = line.split(/[\s"'{}=,]+/);
        tokens.forEach(token => {
            if (token.length > 16 && !token.includes('/') && calculateShannonEntropy(token) > 4.5) {
                findings.push({
                    id: `entropy-${index}`,
                    ruleId: 'HIGH_ENTROPY_STRING',
                    title: 'High Entropy String Detected',
                    description: `Possible sensitive key detected via Shannon analysis (Entropy > 4.5).`,
                    severity: Severity.HIGH,
                    status: ScanStatus.OPEN,
                    resource: 'code_scan',
                    line: index + 1,
                    complianceMapping: ['SOC2_CC6.1']
                });
            }
        });
    });
    return findings;
};

