 */
export const CONTROL_REGISTRY: Record<string, Omit<ComplianceControl, 'score' | 'status'>> = {
    'SOC2_CC6.1': { id: 'SOC2_CC6.1', framework: 'SOC2', title: 'Logical Access Controls' },
    'SOC2_CC6.6': { id: 'SOC2_CC6.6', framework: 'SOC2', title: 'Network Security' },
    'ISO27001_A.10.1.1': { id: 'ISO27001_A.10.1.1', framework: 'ISO27001', title: 'Cryptographic Controls' },
    'PCI_DSS_3.4': { id: 'PCI_DSS_3.4', framework: 'PCI-DSS', title: 'Encryption of Cardholder Data' }
};

export const getComplianceReport = (findings: Vulnerability[]): ComplianceControl[] => {
    const report: Record<string, ComplianceControl> = {};
    Object.values(CONTROL_REGISTRY).forEach(ctrl => {
        report[ctrl.id] = { ...ctrl, status: 'PASS', score: 100 };
    });
    const map: Record<string, string[]> = {
        'S3_NO_ENCRYPTION': ['SOC2_CC6.1', 'ISO27001_A.10.1.1'],
        'SECURITY_GROUP_OPEN': ['SOC2_CC6.6'],
        'S3_PUBLIC_ACCESS': ['SOC2_CC6.6', 'ISO27001_A.10.1.1'],
        'AWS_ACCESS_KEY': ['SOC2_CC6.1', 'PCI_DSS_3.4'],
        'AWS_SECRET_KEY': ['SOC2_CC6.1', 'PCI_DSS_3.4']
    };
    findings.forEach(v => {
        (map[v.ruleId] || []).forEach(cid => {
            if (report[cid]) { report[cid].status = 'FAIL'; report[cid].score = 0; }
        });
    });
    return Object.values(report);
};

export const parseHclToGraph = (hcl: string): { nodes: GraphNode[]; edges: GraphEdge[] } => {
    const nodes: GraphNode[] = [];
    const edges: GraphEdge[] = [];
    const resourceRegex = /resource\s+"([\w_]+)"\s+"([\w_-]+)"/g;
    let match;
    let x = 150; let y = 100;
    while ((match = resourceRegex.exec(hcl)) !== null) {
        const [_, type, name] = match;
        const id = `${type}.${name}`;
        let category: GraphNode['data']['category'] = 'compute';
        if (type.includes('s3')) category = 'storage';
        else if (type.includes('vpc')) category = 'network';
        else if (type.includes('security')) category = 'security';
        nodes.push({ id, data: { label: name, category, resource_type: type }, position: { x, y }, status: 'healthy' });
        x += 200; if (x > 600) { x = 150; y += 150; }
    }
    return { nodes, edges };
};

