                          <div key={key} className="text-[9px] font-mono text-indigo-400 bg-indigo-500/5 px-2 py-1 rounded border border-indigo-500/10">
                            {key}: {String(val)}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const HistoryIcon = ({ className, size }: any) => <History size={size} className={className} />;

const getIcon = (type: string) => {
    switch (type) {
        case 'RISK': return <AlertTriangle size={20} />;
        case 'PR': return <GitPullRequest size={20} />;
        case 'COMPLIANCE': return <CheckCircle size={20} />;
        case 'DRIFT': return <Activity size={20} />;
        case 'SCAN': return <Shield size={20} />;
        default: return <Shield size={20} />;
    }
};

const getIconStyles = (event: TimelineEvent) => {
    if (event.severity === Severity.CRITICAL || event.type === 'RISK') return 'bg-red-500/10 border-red-500/30 text-red-500 shadow-red-900/20';
    if (event.type === 'PR') return 'bg-primary-500/10 border-primary-500/30 text-primary-500 shadow-primary-900/20';
    if (event.type === 'COMPLIANCE') return 'bg-emerald-500/10 border-emerald-500/30 text-emerald-500 shadow-emerald-900/20';
    if (event.type === 'DRIFT') return 'bg-amber-500/10 border-amber-500/30 text-amber-500 shadow-amber-900/20';
    return 'bg-slate-800 border-slate-700 text-slate-400';
};

const getBadgeStyles = (event: TimelineEvent) => {
    if (event.type === 'RISK') return 'bg-red-500/10 text-red-500 border border-red-500/20';
    if (event.type === 'PR') return 'bg-primary-500/10 text-primary-500 border border-primary-500/20';
    if (event.type === 'COMPLIANCE') return 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20';
    return 'bg-slate-800 text-slate-400 border border-slate-700';
};

import React, { useState } from 'react';
import { Clock, Shield, AlertTriangle, GitPullRequest, Activity, CheckCircle, Download, History, Loader2, CheckCircle2, X } from 'lucide-react';
import { TimelineEvent, Severity } from '../types';

interface TimelineProps {
  events: TimelineEvent[];
}

export const Timeline: React.FC<TimelineProps> = ({ events }) => {
  const [isExporting, setIsExporting] = useState(false);
  const [showToast, setShowToast] = useState(false);

  const handleExport = () => {
    // Definimos como true para dar feedback visual imediato
    setIsExporting(true);

    try {
      const logContent = `
==================================================
      CLOUD GUARDIAN - AUDIT TIMELINE LOG
==================================================
Gerado em: ${new Date().toLocaleString()}
Total de Eventos: ${events.length}
--------------------------------------------------

${events.map(event => `
[${new Date(event.timestamp).toLocaleString()}]
TIPO: ${event.type}
SEVERIDADE: ${event.severity || 'INFO'}
TÍTULO: ${event.title}
DESCRIÇÃO: ${event.description}
--------------------------------------------------`).join('\n')}

AUDIT TRAIL CERTIFICADO
Integridade: ${Math.random().toString(36).substring(2).toUpperCase()}
CloudGuardian Engine v2.4.0
==================================================
      `;

      const blob = new Blob([logContent], { type: 'text/plain;charset=utf-8' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `CloudGuardian_AuditLog_${new Date().toISOString().split('T')[0]}.txt`;

      // Essencial para navegadores como Firefox
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);

      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (error) {
      console.error("Erro ao exportar logs:", error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="p-8 max-w-5xl mx-auto space-y-8 pb-24 animate-in fade-in duration-500 text-slate-200">
      {showToast && (
        <div className="fixed top-24 right-8 z-[100] bg-emerald-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-right-10">
          <CheckCircle2 size={24} />
          <div>
            <p className="font-bold text-sm">Logs Exportados!</p>
            <p className="text-[10px] opacity-80 uppercase font-mono tracking-tighter">Download concluído com sucesso.</p>
          </div>
          <button onClick={() => setShowToast(false)}><X size={16} /></button>
        </div>
      )}

      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4 border-b border-slate-800 pb-8">
        <div>
          <h1 className="text-3xl font-black text-white tracking-tight italic uppercase">Security Timeline</h1>
          <p className="text-slate-400 text-sm mt-1 font-medium italic">Audit log completo das operações de segurança e remediações.</p>
        </div>
        <button 
          onClick={handleExport}
          disabled={isExporting || events.length === 0}
          className="flex items-center gap-3 px-6 py-3 bg-primary-600 hover:bg-primary-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 disabled:opacity-50 disabled:cursor-not-allowed group active:scale-95"
        >
          {isExporting ? <Loader2 className="animate-spin" size={16} /> : <Download size={16} className="group-hover:-translate-y-1 transition-transform" />}
          {isExporting ? 'Exportando...' : 'Exportar Logs de Auditoria'}
        </button>
      </header>

      <div className="relative">
        <div className="absolute left-[23.5px] top-0 bottom-0 w-1 bg-gradient-to-b from-slate-800 via-slate-800/50 to-transparent"></div>

        <div className="space-y-12 relative">
          {events.length === 0 ? (
            <div className="bg-slate-900/40 border-2 border-dashed border-slate-800 rounded-[32px] p-24 text-center">
               <History className="mx-auto text-slate-800 mb-4 opacity-20" size={64} />
               <h3 className="text-xl font-bold text-slate-600 uppercase tracking-widest">Nenhum evento registrado</h3>
               <p className="text-sm text-slate-700 mt-2 italic">Inicie um scan para começar a registrar atividades.</p>
            </div>
          ) : (
            events.map((event, index) => (
              <div key={event.id} className="flex gap-10 group animate-in slide-in-from-left-4" style={{ animationDelay: `${index * 50}ms` }}>
                <div className="relative z-10 shrink-0">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border shadow-2xl transition-all group-hover:scale-110 ${getIconStyles(event)}`}>
                    {getIcon(event.type)}
                  </div>
                </div>
                <div className="flex-1 space-y-4 pt-1">
                  <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-2">
                    <div className="flex items-center gap-3">
                      <h3 className="text-lg font-black text-white tracking-tight">{event.title}</h3>
                      <span className={`text-[8px] font-black px-2 py-0.5 rounded uppercase tracking-widest ${getBadgeStyles(event)}`}>
                        {event.type}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 text-slate-500 font-mono text-[10px] bg-slate-900/50 px-3 py-1 rounded-full border border-slate-800/50">
                      <Clock size={12} />
                      {new Date(event.timestamp).toLocaleString()}
                    </div>
                  </div>
                  <div className="bg-slate-900/60 backdrop-blur-xl border border-slate-800 p-6 rounded-3xl shadow-xl hover:border-slate-700 transition-colors relative overflow-hidden group-hover:bg-slate-900/80">
                    <div className="absolute top-0 right-0 p-4 opacity-[0.03]">
                       <Shield size={64} />
                    </div>
                    <p className="text-sm text-slate-400 font-medium leading-relaxed italic border-l-2 border-slate-800 pl-4">{event.description}</p>

                    {event.metadata && (
                      <div className="mt-4 flex flex-wrap gap-2">
                        {Object.entries(event.metadata).map(([key, val]) => (
                          <div key={key} className="text-[9px] font-mono text-indigo-400 bg-indigo-500/5 px-2 py-1 rounded border border-indigo-500/10">
                            {key}: {String(val)}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const getIcon = (type: string) => {
    switch (type) {
        case 'RISK': return <AlertTriangle size={20} />;
        case 'PR': return <GitPullRequest size={20} />;
        case 'COMPLIANCE': return <CheckCircle size={20} />;
        case 'DRIFT': return <Activity size={20} />;
        case 'SCAN': return <Shield size={20} />;
        default: return <Shield size={20} />;
    }
};

const getIconStyles = (event: TimelineEvent) => {
    if (event.severity === Severity.CRITICAL || event.type === 'RISK') return 'bg-red-500/10 border-red-500/30 text-red-500 shadow-red-900/20';
    if (event.type === 'PR') return 'bg-primary-500/10 border-primary-500/30 text-primary-500 shadow-primary-900/20';
    if (event.type === 'COMPLIANCE') return 'bg-emerald-500/10 border-emerald-500/30 text-emerald-500 shadow-emerald-900/20';
