export enum Severity {
  LOW = "LOW",
  MEDIUM = "MEDIUM",
  HIGH = "HIGH",
  CRITICAL = "CRITICAL"
}

export enum ScanStatus {
  OPEN = "OPEN",
  FIXED = "FIXED",
  IGNORED = "IGNORED",
  IN_PROGRESS = "IN_PROGRESS"
}

export interface Vulnerability {
  id: string;
  ruleId: string;
  title: string;
  description: string;
  severity: Severity;
