  remediation?: string;
  complianceMapping?: string[];
}

export interface SecurityScore {
  total: number;
  infrastructure: number;
  secrets: number;
  compliance: number;
  drift: number;
  trend: number;
}

export interface DriftItem {
  id: string;
  resource: string;
