import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity } from './types';
import { calculateSecurityScore } from './services/engine';
import { Play, CheckCircle, Sparkles, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [showTour, setShowTour] = useState(true);

  const securityScore = useMemo(() => calculateSecurityScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    const auth = localStorage.getItem('cg_auth');
    if (auth === 'true') setIsAuthenticated(true);
  }, []);

  const addTimelineEvent = (event: Omit<TimelineEvent, 'id' | 'timestamp'>) => {
    const newEvent: TimelineEvent = {
      ...event,
      id: `ev-${Date.now()}`,
      timestamp: new Date().toISOString()
    };
    setTimelineEvents(prev => [newEvent, ...prev]);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    addTimelineEvent({
      type: 'SCAN',
      title: 'Sessão Iniciada',
      description: 'Administrador John Doe acessou o console de segurança.'
    });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
    setIsAuditorMode(false);
  };

  const updateVulnerabilities = (newVulns: Vulnerability[]) => {
    setVulnerabilities(newVulns);
    if (newVulns.length > 0) {
      addTimelineEvent({
        type: 'RISK',
        title: 'Vulnerabilidades Detectadas',
        description: `${newVulns.length} riscos encontrados no código Terraform.`,
        severity: Severity.HIGH
      });
    }
  };

  const applyRemediation = (vulnId: string, fixCode: string) => {
    let updatedCode = terraformCode;
    if (fixCode.includes('private')) {
      updatedCode = updatedCode.replace('public-read', 'private');
    }
    if (fixCode.includes('10.0.0.0/16')) {
      updatedCode = updatedCode.replace('0.0.0.0/0', '10.0.0.0/16');
    }

    setTerraformCode(updatedCode);
    setVulnerabilities(prev => prev.filter(v => v.id !== vulnId));
    addTimelineEvent({
      type: 'PR',
      title: 'Auto-PR Merged',
      description: `Vulnerabilidade resolvida via IA. Código atualizado para padrões de segurança.`,
      severity: Severity.LOW,
      metadata: { action: 'REMEDIATION_APPLIED' }
    });
  };

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard': 
        return <Dashboard 
          isAuditorMode={isAuditorMode} 
          vulnerabilities={vulnerabilities} 
          drifts={drifts}
          score={securityScore}
          timeline={timelineEvents}
          onNavigate={setCurrentView}
        />;
      case 'scanner': 
        return <Scanner 
          code={terraformCode} 
          onCodeChange={setTerraformCode} 
          onScanComplete={updateVulnerabilities}
          vulnerabilities={vulnerabilities}
          onApplyFix={applyRemediation}
        />;
      case 'drift': 
        return <Drift 
          isAuditorMode={isAuditorMode} 
          drifts={drifts}
          setDrifts={setDrifts}
          onSync={(item) => {
             addTimelineEvent({
               type: 'DRIFT',
               title: 'Drift Sincronizado',
               description: `Recurso ${item.resource} sincronizado com a nuvem.`,
               severity: Severity.LOW
             });
          }}
        />;
      case 'graph': return <Graph code={terraformCode} vulnerabilities={vulnerabilities} />;
      case 'compliance': return <Compliance vulnerabilities={vulnerabilities} />;
      case 'automation': return <AutomationHub />;
      case 'sales-playbook': return <SalesPlaybook />;
      case 'policies': return <PolicyManager />;
      case 'cicd': return <PipelineInsights />;
      case 'report': return <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />;
      case 'timeline': return <Timeline events={timelineEvents} />;
      case 'settings': return <Settings />;
      default: return <Dashboard score={securityScore} vulnerabilities={vulnerabilities} drifts={drifts} timeline={timelineEvents} onNavigate={setCurrentView} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-primary-500/30">
      <Sidebar currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout} isAuditorMode={isAuditorMode} />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col">
        {isAuditorMode && <AuditorBanner />}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-indigo-600 to-purple-600 z-10"></div>
        <div className="p-6 flex-1">{renderContent()}</div>

        {showTour && (
          <div className="fixed bottom-6 left-[280px] w-72 bg-slate-900/90 backdrop-blur-xl border border-primary-500/30 rounded-2xl shadow-2xl z-50 p-5 animate-in slide-in-from-bottom-10 duration-500">
            <button onClick={() => setShowTour(false)} className="absolute top-3 right-3 text-slate-500 hover:text-white"><X size={14}/></button>
            <div className="flex items-center gap-2 mb-4"><Sparkles className="text-primary-400" size={18} /><h4 className="font-bold text-sm text-white">CloudGuardian Interactive</h4></div>
            <div className="space-y-3">
              <TourItem done={currentView === 'scanner'} label="1. Rodar Scan de IA" onClick={() => setCurrentView('scanner')} />
              <TourItem done={currentView === 'cicd'} label="2. Check Pipeline Insights" onClick={() => setCurrentView('cicd')} />
              <TourItem done={currentView === 'policies'} label="3. Definir Governança" onClick={() => setCurrentView('policies')} />
              <TourItem done={currentView === 'report'} label="4. Baixar Relatório" onClick={() => setCurrentView('report')} />
