import { GoogleGenAI } from "@google/genai";

// Always use the process.env.API_KEY directly as a named parameter.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTerraformCode = async (code: string) => {
  if (!process.env.API_KEY) {
    console.warn("Gemini API Key is missing. Skipping AI analysis.");
    return null;
  }

  try {
    // Using gemini-3-pro-preview for complex DevSecOps and coding analysis as per guidelines
    const model = 'gemini-3-pro-preview';
    const prompt = `
      You are a CloudGuardian AI Security Agent. Analyze the following Terraform HCL code for security vulnerabilities, 
      specifically looking for misconfigurations related to SOC2, ISO27001, and general best practices (AWS/Azure/GCP).

      Code:
      \`\`\`hcl
      ${code}
      \`\`\`

      Return a JSON response with the following structure:
      {
        "findings": [
          {
            "ruleId": "string",
            "title": "string",
            "severity": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
            "resource": "string",
            "description": "string",
            "remediation": "string"
          }
        ]
      }

      Only return the JSON object.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json"
      }
    });

    // Access the text property directly (do not call as a method).
    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    return null;
  }
};

export const suggestFix = async (vulnerability: string, codeContext: string) => {
  if (!process.env.API_KEY) return "AI Fix unavailable (No API Key)";

  try {
    // Using gemini-3-pro-preview for coding-related tasks
    const model = 'gemini-3-pro-preview';
    const prompt = `
      Provide a Terraform HCL code snippet to fix the following vulnerability: "${vulnerability}".
      Context: 
      \`\`\`hcl
      ${codeContext}
      \`\`\`
      Return only the corrected HCL code block.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    // Access the text property directly.
    return response.text;
  } catch (error) {
    console.error("Gemini Fix Failed:", error);
    return "Failed to generate fix.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun } from './types';
import { calculateSecurityScore } from './services/engine';
import { Play, CheckCircle, Sparkles, X, CheckCircle2 } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [showTour, setShowTour] = useState(true);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // Functional States
  const [policies, setPolicies] = useState<Policy[]>([
    { id: 'pol-01', name: 'S3 Encryption Enforced', description: 'Todos os buckets S3 devem ter criptografia AES-256 ativa.', framework: 'SOC2', severity: Severity.HIGH, status: 'active' },
    { id: 'pol-02', name: 'No Public Ingress 0.0.0.0/0', description: 'Bloquear entrada de tráfego vindo de qualquer lugar para portas sensíveis.', framework: 'ISO27001', severity: Severity.CRITICAL, status: 'active' },
    { id: 'pol-03', name: 'VPC Flow Logs Mandatory', description: 'Ativar flow logs em todas as VPCs para auditoria de tráfego.', framework: 'SOC2', severity: Severity.MEDIUM, status: 'active' }
  ]);

  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([
    { id: 'run-982', branch: 'main', status: 'success', vulns: 0, timestamp: new Date(Date.now() - 3600000).toISOString(), commit: 'feat: add encryption to rds' },
    { id: 'run-981', branch: 'feat/api', status: 'failed', vulns: 3, timestamp: new Date(Date.now() - 86400000).toISOString(), commit: 'fix: security group rules' },
  ]);

  const securityScore = useMemo(() => calculateSecurityScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const addTimelineEvent = (event: Omit<TimelineEvent, 'id' | 'timestamp'>) => {
    const newEvent: TimelineEvent = {
      ...event,
      id: `ev-${Date.now()}`,
      timestamp: new Date().toISOString()
    };
    setTimelineEvents(prev => [newEvent, ...prev]);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    addTimelineEvent({
      type: 'SCAN',
      title: 'Sessão Iniciada',
      description: 'Administrador John Doe acessou o console de segurança.'
    });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
    setIsAuditorMode(false);
  };

  const updateVulnerabilities = (newVulns: Vulnerability[]) => {
    setVulnerabilities(newVulns);
    if (newVulns.length > 0) {
      addTimelineEvent({
        type: 'RISK',
        title: 'Vulnerabilidades Detectadas',
        description: `${newVulns.length} riscos encontrados no código Terraform.`,
        severity: Severity.HIGH
      });
      showNotification(`${newVulns.length} riscos encontrados!`, 'error');
    } else {
      showNotification("Scan concluído: Nenhum risco!", "success");
    }
  };

  const applyRemediation = (vulnId: string, fixCode: string) => {
    let updatedCode = terraformCode;
    if (fixCode.includes('private')) updatedCode = updatedCode.replace('public-read', 'private');
    if (fixCode.includes('10.0.0.0/16')) updatedCode = updatedCode.replace('0.0.0.0/0', '10.0.0.0/16');

    setTerraformCode(updatedCode);
    setVulnerabilities(prev => prev.filter(v => v.id !== vulnId));
    addTimelineEvent({
      type: 'PR',
      title: 'Auto-PR Merged',
      description: `Vulnerabilidade resolvida via IA. Código atualizado para padrões de segurança.`,
      severity: Severity.LOW
    });
    showNotification("Remediação aplicada com sucesso!");
  };

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-primary-500/30">
      <Sidebar currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout} isAuditorMode={isAuditorMode} />

      <main className="flex-1 ml-64 min-h-screen relative flex flex-col">
        {isAuditorMode && <AuditorBanner />}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-indigo-600 to-purple-600 z-10"></div>

        {/* Toast System */}
        {toast && (
          <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 duration-300 ${
            toast.type === 'success' ? 'bg-emerald-600' : 'bg-red-600'
          }`}>
            <CheckCircle2 size={20} />
            <span className="text-sm font-bold uppercase tracking-tight">{toast.message}</span>
            <button onClick={() => setToast(null)}><X size={14} /></button>
          </div>
        )}

        <div className="p-6 flex-1 overflow-y-auto">
          {currentView === 'dashboard' && <Dashboard isAuditorMode={isAuditorMode} vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={updateVulnerabilities} vulnerabilities={vulnerabilities} onApplyFix={applyRemediation} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} drifts={drifts} setDrifts={setDrifts} onSync={(item) => {
             addTimelineEvent({ type: 'DRIFT', title: 'Drift Sincronizado', description: `Recurso ${item.resource} sincronizado.`, severity: Severity.LOW });
             showNotification("Recurso sincronizado com a nuvem!");
          }} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={addTimelineEvent} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={addTimelineEvent} />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
        </div>

        {showTour && (
          <div className="fixed bottom-6 left-[280px] w-72 bg-slate-900/90 backdrop-blur-xl border border-primary-500/30 rounded-2xl shadow-2xl z-50 p-5 animate-in slide-in-from-bottom-10 duration-500">
            <button onClick={() => setShowTour(false)} className="absolute top-3 right-3 text-slate-500 hover:text-white"><X size={14}/></button>
            <div className="flex items-center gap-2 mb-4"><Sparkles className="text-primary-400" size={18} /><h4 className="font-bold text-sm text-white">CloudGuardian Interactive</h4></div>
            <div className="space-y-3">
              <TourItem done={vulnerabilities.length > 0} label="1. Rodar Scan de IA" onClick={() => setCurrentView('scanner')} />
              <TourItem done={pipelineRuns.length > 2} label="2. Check Pipeline Insights" onClick={() => setCurrentView('cicd')} />
              <TourItem done={policies.length > 3} label="3. Definir Governança" onClick={() => setCurrentView('policies')} />
              <TourItem done={false} label="4. Baixar Relatório" onClick={() => setCurrentView('report')} />
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

const TourItem = ({ label, done, onClick }: { label: string, done: boolean, onClick: () => void }) => (
  <button onClick={onClick} className={`w-full flex items-center justify-between p-2 rounded-lg text-left text-xs transition-all ${done ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-slate-950 border border-slate-800 text-slate-400 hover:bg-slate-800'}`}>
    <span>{label}</span>{done ? <CheckCircle size={14} /> : <Play size={14} className="opacity-50" />}
  </button>
);

export default App;

import React, { useState } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, AlertCircle, ShieldCheck, Trash2, RotateCcw } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
  onScanComplete: (vulns: Vulnerability[]) => void;
  vulnerabilities: Vulnerability[];
  onApplyFix: (id: string, code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange, onScanComplete, vulnerabilities, onApplyFix }) => {
  const [scanning, setScanning] = useState(false);

  const performScan = async () => {
    setScanning(true);

    // Simular latência para feedback visual
    await new Promise(r => setTimeout(r, 800));

    // Local Analysis (Fast)
    const findings: Vulnerability[] = [];
    findings.push(...scanForSecrets(code));

    if (code.includes('public-read')) {
      findings.push({
        id: `v-s3-pub`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket: Exposure Detected',
        description: 'ACL definida como public-read permite acesso anônimo a dados sensíveis.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        complianceMapping: ['SOC2_CC6.6', 'ISO27001_A.10']
      });
    }

    if (code.includes('0.0.0.0/0')) {
      findings.push({
        id: `v-sg-all`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group: Universal Ingress',
        description: 'Abertura total (0.0.0.0/0) detectada. Recomendado restringir IPs.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6']
      });
    }

    // AI Analysis (Deep)
    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanedJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanedJson);
        if (parsed.findings) {
          findings.push(...parsed.findings.map((f: any, idx: number) => ({
            ...f,
            id: `ai-${idx}-${Date.now()}`,
            status: ScanStatus.OPEN,
            complianceMapping: ['AI_VALIDATED']
          })));
        }
      }
    } catch (e) { console.error("AI Error:", e); }

    onScanComplete(findings);
    setScanning(false);
  };

  const clearScan = () => {
    onScanComplete([]);
  };

  const renderCode = (text: string) => {
    return text.split('\n').map((line, i) => (
      <div key={i} className="flex min-h-[1.5rem] group hover:bg-slate-900/50">
        <span className="w-10 text-right pr-4 text-slate-700 font-mono text-xs pt-0.5 border-r border-slate-800/50 mr-4">{i + 1}</span>
        <span className="flex-1 whitespace-pre font-mono text-xs leading-6 text-slate-300">{line || ' '}</span>
      </div>
    ));
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Security Scanner</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1 flex items-center gap-2">
            <ShieldCheck size={14} className="text-primary-500" />
            Static Code Analysis (SAST) & IA Guard
          </p>
        </div>
        <div className="flex items-center gap-3">
          {vulnerabilities.length > 0 && (
            <button 
              onClick={clearScan}
              className="p-3 bg-slate-900 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all hover:bg-slate-800"
              title="Limpar Resultados"
            >
              <RotateCcw size={18} />
            </button>
          )}
          <button 
            onClick={performScan} 
            disabled={scanning} 
            className="flex items-center gap-3 px-8 py-3 bg-primary-600 hover:bg-primary-700 text-white text-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 disabled:opacity-50 active:scale-95"
          >
            {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {scanning ? 'Analisando...' : 'Iniciar Varredura'}
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-7 bg-slate-900/80 border border-slate-800 rounded-[32px] overflow-hidden shadow-2xl flex flex-col min-h-[600px] group/editor">
          <div className="bg-slate-850 px-6 py-4 border-b border-slate-800 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">main.tf</span>
              <span className="text-[8px] bg-emerald-500/10 text-emerald-500 px-1.5 py-0.5 rounded font-black uppercase">Pronto para Scan</span>
            </div>
            <div className="flex gap-1.5 opacity-40 group-hover/editor:opacity-100 transition-opacity">
               <div className="w-2.5 h-2.5 rounded-full bg-red-500/50"></div>
               <div className="w-2.5 h-2.5 rounded-full bg-amber-500/50"></div>
               <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/50"></div>
            </div>
          </div>
          <div className="flex-1 relative bg-slate-950 p-6 overflow-y-auto">
            <textarea 
              value={code} 
              onChange={(e) => onCodeChange(e.target.value)} 
              className="absolute inset-0 w-full h-full p-6 pl-14 bg-transparent text-transparent caret-white font-mono text-xs leading-6 resize-none focus:outline-none z-10"
              spellCheck={false}
              placeholder="Cole seu código Terraform HCL aqui..."
            />
