// Helpers para ícones e cores
const getCategoryIcon = (category: string, size: number, color?: string) => {
  switch (category) {
    case 'compute': return <Server size={size} color={color} />;
    case 'storage': return <Database size={size} color={color} />;
    case 'network': return <Globe size={size} color={color} />;
    case 'security': return <Shield size={size} color={color} />;
    default: return <Layers size={size} color={color} />;
  }
};

const getCategoryColor = (category: string, isLight: boolean) => {
  if (isLight) {
    switch (category) {
      case 'compute': return 'bg-purple-500/10 text-purple-500 border border-purple-500/20';
      case 'storage': return 'bg-yellow-500/10 text-yellow-500 border border-yellow-500/20';
      case 'network': return 'bg-blue-500/10 text-blue-500 border border-blue-500/20';
      case 'security': return 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20';
      default: return 'bg-slate-500/10 text-slate-500 border border-slate-500/20';
    }
  }
  return '';
};

const getCategoryHex = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7';
    case 'storage': return '#eab308';
    case 'network': return '#3b82f6';
    case 'security': return '#10b981';
    default: return '#475569';
  }
};

