export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  const { nodes, edges } = useMemo(() => {
    const graph = parseHclToGraph(code);
    const enrichedNodes = graph.nodes.map(node => {
        const nodeVulns = vulnerabilities.filter(v => 
          v.resource.includes(node.id) || 
          node.id.includes(v.resource) ||
          v.resource.includes(node.data.label)
        );
        return { 
          ...node, 
          status: nodeVulns.length > 0 ? 'risk' : 'healthy' as any,
          vulnerabilities: nodeVulns 
        };
    });
    return { nodes: enrichedNodes, edges: graph.edges };
  }, [code, vulnerabilities]);

  const selectedNode = nodes.find(n => n.id === selectedNodeId) as (GraphNode & { vulnerabilities: Vulnerability[] }) | undefined;

  // BLAST RADIUS LOGIC: Encontrar nós afetados (dependentes) do nó selecionado
  const affectedNodeIds = useMemo(() => {
    if (!selectedNodeId) return [];
    const affected = new Set<string>();

    // Função recursiva simples para encontrar dependentes (blast radius)
    const findDependents = (nodeId: string) => {
      edges.forEach(edge => {
        if (edge.source === nodeId && !affected.has(edge.target)) {
          affected.add(edge.target);
          findDependents(edge.target);
        }
      });
    };

    findDependents(selectedNodeId);
    return Array.from(affected);
  }, [selectedNodeId, edges]);

  const connectedEdgeIds = useMemo(() => {
    if (!selectedNodeId) return [];
    return edges
      .filter(e => e.source === selectedNodeId || e.target === selectedNodeId)
      .map(e => e.id);
  }, [selectedNodeId, edges]);

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-700 relative overflow-hidden">
       <div className="flex justify-between items-end relative z-10">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Infrastructure Graph</h2>
          <p className="text-slate-500 text-sm font-medium">
              Topologia ativa de segurança e dependências de recursos.
          </p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3 bg-slate-900/80 backdrop-blur px-4 py-2 rounded-xl border border-slate-800 shadow-xl">
             <Layers className="text-primary-500" size={16} />
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{nodes.length} Recursos Detectados</span>
          </div>
          <button 
            onClick={() => setSelectedNodeId(null)}
            className="p-2 bg-slate-900 border border-slate-800 rounded-xl text-slate-500 hover:text-white transition-colors"
          >
            <RefreshCw size={16} />
          </button>
        </div>
      </div>

      <div className="flex-1 bg-slate-950 border border-slate-800 rounded-[40px] relative overflow-hidden flex items-center justify-center shadow-inner group">
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ 
          backgroundImage: 'radial-gradient(circle, #3b82f6 1px, transparent 1px)', 
          backgroundSize: '40px 40px' 
        }}></div>

        {nodes.length === 0 ? (
          <div className="text-slate-500 flex flex-col items-center p-12 border-2 border-dashed border-slate-800 rounded-[32px] bg-slate-900/20 relative z-10">
             <Layers size={48} className="text-slate-800 mb-4" />
             <p className="font-bold text-white opacity-50 uppercase tracking-widest text-xs">Nenhum recurso mapeado no HCL</p>
          </div>
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 900 600" className="w-full h-full relative z-10 select-none">
              <defs>
                  <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="35" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="#1e293b" />
                  </marker>
                  <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation="4" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                  </filter>
                  <linearGradient id="activeLink" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.8" />
                    <stop offset="100%" stopColor="#818cf8" stopOpacity="0.8" />
                  </linearGradient>
                  <linearGradient id="affectedLink" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#f59e0b" stopOpacity="0.5" />
                    <stop offset="100%" stopColor="#fbbf24" stopOpacity="0.5" />
                  </linearGradient>
              </defs>

              <g>
                  {edges.map(edge => {
                      const sourceNode = nodes.find(n => n.id === edge.source);
                      const targetNode = nodes.find(n => n.id === edge.target);
                      if (!sourceNode || !targetNode) return null;

                      const isActive = connectedEdgeIds.includes(edge.id);
                      const isBlastRadius = affectedNodeIds.includes(edge.target) && edge.source === selectedNodeId;

                      return (
                        <line 
                          key={edge.id} 
                          x1={sourceNode.position.x} 
                          y1={sourceNode.position.y} 
                          x2={targetNode.position.x} 
                          y2={targetNode.position.y} 
                          stroke={isActive ? "url(#activeLink)" : (isBlastRadius ? "url(#affectedLink)" : "#1e293b")}
                          strokeWidth={isActive ? 2 : (isBlastRadius ? 1.5 : 1)}
                          strokeDasharray={isBlastRadius ? "4,2" : (edge.animated ? "5,5" : "0")}
                          className="transition-all duration-300"
                        />
                      );
                  })}
              </g>

              {nodes.map(node => (
                  <Node 
                      key={node.id} 
                      node={node as any}
                      isSelected={selectedNodeId === node.id}
                      isAffected={affectedNodeIds.includes(node.id)}
                      onClick={() => setSelectedNodeId(node.id)}
                  />
              ))}
          </svg>
        )}

        <div className="absolute bottom-8 left-8 bg-slate-900/90 backdrop-blur-xl p-5 rounded-3xl border border-slate-800 shadow-2xl flex flex-col gap-3">
            <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-tighter mb-1">Categories</h4>
            <LegendItem color="bg-blue-500" label="Network / VPC" />
            <LegendItem color="bg-purple-500" label="Compute / EC2" />
            <LegendItem color="bg-yellow-500" label="Storage / RDS" />
            <LegendItem color="bg-emerald-500" label="Security / IAM" />
            <div className="h-px bg-slate-800 my-1"></div>
            <LegendItem color="bg-amber-500" label="Blast Radius Impact" />
        </div>

        {selectedNode && (
          <div className="absolute top-0 right-0 h-full w-80 bg-slate-900/95 backdrop-blur-2xl border-l border-slate-800 shadow-[-10px_0_30px_rgba(0,0,0,0.5)] z-20 animate-in slide-in-from-right duration-300 flex flex-col">
            <div className="p-6 border-b border-slate-800 flex justify-between items-center">
               <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-lg ${getCategoryColor(selectedNode.data.category, true)}`}>
                    {getCategoryIcon(selectedNode.data.category, 18)}
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-white truncate max-w-[140px]">{selectedNode.data.label}</h3>
                    <p className="text-[10px] text-slate-500 font-mono">{selectedNode.data.resource_type}</p>
                  </div>
               </div>
               <button onClick={() => setSelectedNodeId(null)} className="p-1 hover:bg-slate-800 rounded-md text-slate-500 hover:text-white transition-colors">
                 <X size={18} />
               </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">
               <section className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Health & Context</h4>
                  <div className={`flex items-center gap-3 p-4 rounded-2xl border ${selectedNode.status === 'risk' ? 'bg-red-500/10 border-red-500/20 text-red-500' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500'}`}>
                    {selectedNode.status === 'risk' ? <AlertTriangle size={20} /> : <ShieldCheck size={20} />}
                    <div className="text-xs font-bold uppercase tracking-tight">
                       {selectedNode.status === 'risk' ? 'Security Risks Detected' : 'Resource Healthy'}
                    </div>
                  </div>
               </section>

               {affectedNodeIds.length > 0 && (
                 <section className="space-y-3">
                    <h4 className="text-[10px] font-black text-amber-500 uppercase tracking-widest flex items-center gap-2">
                        <Target size={14} /> Blast Radius
                    </h4>
                    <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl p-4">
                        <p className="text-[10px] text-amber-500 font-bold mb-2">Uma vulnerabilidade neste nó pode comprometer:</p>
                        <div className="space-y-1.5">
                            {affectedNodeIds.slice(0, 3).map(id => (
                                <div key={id} className="flex items-center gap-2 text-[9px] text-slate-400">
                                    <Zap size={10} className="text-amber-500" /> {id}
                                </div>
                            ))}
                            {affectedNodeIds.length > 3 && <div className="text-[9px] text-slate-500">+ {affectedNodeIds.length - 3} outros recursos</div>}
                        </div>
                    </div>
                 </section>
               )}

               {selectedNode.vulnerabilities.length > 0 && (
                 <section className="space-y-3">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Findings ({selectedNode.vulnerabilities.length})</h4>
                    <div className="space-y-2">
                      {selectedNode.vulnerabilities.map(v => (
                        <div key={v.id} className="bg-slate-950/60 p-3 rounded-xl border border-slate-800 space-y-2">
                           <div className="flex justify-between items-center">
                              <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase border ${v.severity === Severity.CRITICAL ? 'text-red-500 border-red-500/20 bg-red-500/10' : 'text-orange-500 border-orange-500/20 bg-orange-500/10'}`}>
                                {v.severity}
                              </span>
                              <span className="text-[9px] text-slate-600 font-mono">#{v.ruleId}</span>
                           </div>
                           <p className="text-[11px] font-bold text-slate-200 leading-tight">{v.title}</p>
                        </div>
                      ))}
                    </div>
                 </section>
               )}

               <section className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resource Info</h4>
                  <div className="bg-slate-950/40 p-4 rounded-2xl border border-slate-800 space-y-3">
                     <div className="flex justify-between items-center text-[10px]">
                        <span className="text-slate-500 uppercase font-black">Region</span>
                        <span className="text-white font-mono">us-east-1</span>
                     </div>
                     <div className="flex justify-between items-center text-[10px]">
                        <span className="text-slate-500 uppercase font-black">Provider</span>
                        <span className="text-white font-mono">AWS</span>
                     </div>
                     <div className="flex justify-between items-center text-[10px]">
                        <span className="text-slate-500 uppercase font-black">Encrypted</span>
                        <span className="text-emerald-500 font-bold">YES</span>
                     </div>
                  </div>
               </section>
            </div>

            <div className="p-6 border-t border-slate-800 bg-slate-900/50">
               <button className="w-full flex items-center justify-center gap-2 py-3 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all">
                  Inspect in Cloud Console <ExternalLink size={12} />
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ScanResults } from '../components/ScanResults';
import { analyzeTerraformCode } from '../services/geminiService';
import { scanForSecrets, scanForFinOps } from '../services/engine';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { Play, Loader2, AlertCircle, ShieldCheck, RotateCcw, TrendingDown } from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
  onScanComplete: (vulns: Vulnerability[]) => void;
  vulnerabilities: Vulnerability[];
  onApplyFix: (id: string, code: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange, onScanComplete, vulnerabilities, onApplyFix }) => {
  const [scanning, setScanning] = useState(false);

  const performScan = async () => {
    setScanning(true);
    await new Promise(r => setTimeout(r, 800));

    const findings: Vulnerability[] = [];
    findings.push(...scanForSecrets(code));
    findings.push(...scanForFinOps(code));

    if (code.includes('public-read')) {
      findings.push({
        id: `v-s3-pub`,
        ruleId: 'S3_PUBLIC_ACCESS',
        title: 'S3 Bucket: Exposure Detected',
        description: 'ACL definida como public-read permite acesso anônimo a dados sensíveis.',
        severity: Severity.CRITICAL,
        status: ScanStatus.OPEN,
        resource: 'aws_s3_bucket.data',
        complianceMapping: ['SOC2_CC6.6', 'ISO27001_A.10']
      });
    }

    if (code.includes('0.0.0.0/0')) {
      findings.push({
        id: `v-sg-all`,
        ruleId: 'SECURITY_GROUP_OPEN',
        title: 'Security Group: Universal Ingress',
        description: 'Abertura total (0.0.0.0/0) detectada. Recomendado restringir IPs.',
        severity: Severity.HIGH,
        status: ScanStatus.OPEN,
        resource: 'aws_security_group.web',
        complianceMapping: ['SOC2_CC6.6']
      });
    }

    try {
      const aiResultJson = await analyzeTerraformCode(code);
      if (aiResultJson) {
        const cleanedJson = aiResultJson.replace(/```json\n?|\n?```/g, '').trim();
        const parsed = JSON.parse(cleanedJson);
        if (parsed.findings) {
          findings.push(...parsed.findings.map((f: any, idx: number) => ({
            ...f,
            id: `ai-${idx}-${Date.now()}`,
            status: ScanStatus.OPEN,
            complianceMapping: ['AI_VALIDATED']
          })));
        }
      }
    } catch (e) { console.error("AI Error:", e); }

    onScanComplete(findings);
    setScanning(false);
  };

  const clearScan = () => onScanComplete([]);

  const renderCode = (text: string) => {
    return text.split('\n').map((line, i) => (
      <div key={i} className="flex min-h-[1.5rem] group hover:bg-slate-900/50">
        <span className="w-10 text-right pr-4 text-slate-700 font-mono text-xs pt-0.5 border-r border-slate-800/50 mr-4">{i + 1}</span>
        <span className="flex-1 whitespace-pre font-mono text-xs leading-6 text-slate-300">{line || ' '}</span>
      </div>
    ));
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Security & Cost Scanner</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1 flex items-center gap-2">
            <ShieldCheck size={14} className="text-primary-500" />
            Static Code Analysis & FinOps Guard
          </p>
        </div>
        <div className="flex items-center gap-3">
          {vulnerabilities.length > 0 && (
            <button 
              onClick={clearScan}
              className="p-3 bg-slate-900 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all hover:bg-slate-800"
              title="Limpar Resultados"
            >
              <RotateCcw size={18} />
            </button>
          )}
          <button 
            onClick={performScan} 
            disabled={scanning} 
            className="flex items-center gap-3 px-8 py-3 bg-primary-600 hover:bg-primary-700 text-white text-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 disabled:opacity-50 active:scale-95"
          >
            {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {scanning ? 'Analisando...' : 'Iniciar Varredura'}
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-7 bg-slate-900/80 border border-slate-800 rounded-[32px] overflow-hidden shadow-2xl flex flex-col min-h-[600px] group/editor">
          <div className="bg-slate-850 px-6 py-4 border-b border-slate-800 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">main.tf</span>
              <span className="text-[8px] bg-emerald-500/10 text-emerald-500 px-1.5 py-0.5 rounded font-black uppercase">Pronto para Scan</span>
            </div>
            <div className="flex gap-1.5 opacity-40 group-hover/editor:opacity-100 transition-opacity">
               <div className="w-2.5 h-2.5 rounded-full bg-red-500/50"></div>
               <div className="w-2.5 h-2.5 rounded-full bg-amber-500/50"></div>
               <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/50"></div>
            </div>
          </div>
          <div className="flex-1 relative bg-slate-950 p-6 overflow-y-auto">
            <textarea 
              value={code} 
              onChange={(e) => onCodeChange(e.target.value)} 
              className="absolute inset-0 w-full h-full p-6 pl-14 bg-transparent text-transparent caret-white font-mono text-xs leading-6 resize-none focus:outline-none z-10"
              spellCheck={false}
              placeholder="Cole seu código Terraform HCL aqui..."
            />
            <div className="pointer-events-none">{renderCode(code)}</div>
          </div>
        </div>

        <div className="lg:col-span-5 space-y-6">
           {vulnerabilities.length > 0 || scanning ? (
             <ScanResults findings={vulnerabilities} codeContext={code} onApplyFix={onApplyFix} />
           ) : (
             <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-[32px] bg-slate-900/20 p-12 text-center opacity-60">
                <AlertCircle size={48} className="text-slate-800 mb-4" />
                <h3 className="text-lg font-bold text-slate-500 uppercase">Aguardando Input</h3>
                <p className="text-xs text-slate-600 mt-2">IA analisará segurança, conformidade e custos.</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2, Shield, Lock, Zap, Target, Globe, Layers, DollarSign } from 'lucide-react';
import { suggestFix } from '../services/geminiService';
import { DiffViewer } from './DiffViewer';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
  onApplyFix: (id: string, code: string) => void;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext, onApplyFix }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committing, setCommitting] = useState<string | null>(null);

  const stats = useMemo(() => ({
    critical: findings.filter(f => f.severity === Severity.CRITICAL).length,
    high: findings.filter(f => f.severity === Severity.HIGH).length,
    finops: findings.filter(f => f.type === 'finops').length,
    total: findings.length
  }), [findings]);

  const handleGenerateFix = async (vuln: Vulnerability) => {
    setLoadingFix(vuln.id);
    try {
        const fix = await suggestFix(vuln.title, codeContext);
        setAiFix(prev => ({ ...prev, [vuln.id]: fix || "/* Error generating fix */" }));
    } catch (e) { setAiFix(prev => ({ ...prev, [vuln.id]: "/* AI Error */" })); }
    setLoadingFix(null);
  };

  const handleFixAndCommit = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    setTimeout(() => {
        onApplyFix(vuln.id, aiFix[vuln.id] || '');
        setCommitting(null);
        setExpandedId(null);
    }, 1500);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        <div className="flex justify-between items-center mb-4 text-[10px] font-black uppercase tracking-widest text-slate-500">
           <span>Resultados do Scan</span>
           <span className="text-primary-400">{stats.total} Achados</span>
        </div>
        <div className="grid grid-cols-3 gap-3">
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-red-500/10">
              <div className="text-xl font-black text-red-500">{stats.critical}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Críticos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-orange-500/10">
              <div className="text-xl font-black text-orange-500">{stats.high}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Altos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-emerald-500/10">
              <div className="text-xl font-black text-emerald-500">{stats.finops}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">FinOps</div>
           </div>
        </div>
      </div>

      <div className="space-y-3">
        {findings.map((f) => (
          <div key={f.id} className={`bg-slate-900 rounded-2xl border transition-all ${expandedId === f.id ? 'border-primary-500 shadow-2xl bg-slate-900' : 'border-slate-800 hover:border-slate-700 bg-slate-900/40'}`}>
            <div className="p-4 flex items-center justify-between cursor-pointer" onClick={() => setExpandedId(expandedId === f.id ? null : f.id)}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg border ${f.type === 'finops' ? 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20' : (f.severity === Severity.CRITICAL ? 'text-red-500 bg-red-500/10 border-red-500/20' : 'text-orange-500 bg-orange-500/10 border-orange-500/20')}`}>
                  {f.type === 'finops' ? <DollarSign size={16}/> : (f.title.includes('S3') ? <Shield size={16}/> : <Globe size={16}/>)}
                </div>
                <div>
                   <h4 className="font-bold text-xs text-slate-200">{f.title}</h4>
                   <p className="text-[9px] text-slate-500 font-mono uppercase">{f.resource}</p>
                </div>
              </div>
              {expandedId === f.id ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
            </div>
            {expandedId === f.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-800/50 space-y-4 bg-slate-950/20">
                <p className="text-xs text-slate-400 italic">"{f.description}"</p>
                <div className="flex flex-wrap gap-2">
                   {f.complianceMapping?.map(c => <span key={c} className="text-[8px] font-black text-emerald-400 bg-emerald-500/5 px-2 py-0.5 rounded border border-emerald-500/10">{c}</span>)}
                   {f.type === 'finops' && <span className="text-[8px] font-black text-primary-400 bg-primary-500/5 px-2 py-0.5 rounded border border-primary-500/10">COST_OPTIMIZATION</span>}
                </div>
                {!aiFix[f.id] ? (
                  <button onClick={() => handleGenerateFix(f)} disabled={loadingFix === f.id} className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest border border-slate-700">
                    {loadingFix === f.id ? <Loader2 className="animate-spin" size={14}/> : <Zap size={14} className="text-amber-400"/>}
                    {loadingFix === f.id ? 'Analisando...' : 'Gerar Remediação IA'}
                  </button>
                ) : (
                  <div className="space-y-3 animate-in fade-in">
                    <DiffViewer 
                      original={codeContext.split('\n').filter(l => l.includes(f.resource.split('.')[1])).join('\n') || '/* Resource logic */'} 
                      fixed={aiFix[f.id].replace(/```(hcl|terraform)?\n?|\n?```/g, '')} 
                    />
                    <button onClick={() => handleFixAndCommit(f)} disabled={committing === f.id} className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest shadow-lg shadow-emerald-900/30">
                      {committing === f.id ? <Loader2 className="animate-spin" size={16}/> : <GitPullRequest size={16}/>}
                      {committing === f.id ? 'Criando PR...' : 'Aplicar Correção'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

