import React, { useEffect, useRef, useState } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Mic, X, Waves, Loader2, Bot, Shield, AlertCircle } from 'lucide-react';

interface LiveAssistantProps {
  onClose: () => void;
  codeContext: string;
}

export const LiveAssistant: React.FC<LiveAssistantProps> = ({ onClose, codeContext }) => {
  const [status, setStatus] = useState<'connecting' | 'active' | 'error' | 'closed'>('connecting');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    let inputAudioContext: AudioContext;
    let outputAudioContext: AudioContext;
    let stream: MediaStream;

    const initializeLiveSession = async () => {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
        outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        audioContextRef.current = outputAudioContext;

        stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          callbacks: {
            onopen: () => {
              setStatus('active');
              const source = inputAudioContext.createMediaStreamSource(stream);
              const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

              scriptProcessor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmBlob = createPcmBlob(inputData);
                sessionPromise.then((session) => {
                  session.sendRealtimeInput({ media: pcmBlob });
                });
              };

              source.connect(scriptProcessor);
              scriptProcessor.connect(inputAudioContext.destination);
            },
            onmessage: async (message: LiveServerMessage) => {
              const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
              if (audioData) {
                setIsSpeaking(true);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContext.currentTime);
                const audioBuffer = await decodeAudioData(decodeBase64(audioData), outputAudioContext);
                const source = outputAudioContext.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(outputAudioContext.destination);
                source.onended = () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) setIsSpeaking(false);
                };
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              }

              if (message.serverContent?.interrupted) {
                sourcesRef.current.forEach(s => s.stop());
                sourcesRef.current.clear();
                nextStartTimeRef.current = 0;
                setIsSpeaking(false);
              }
            },
            onerror: (e) => {
              console.error('Live Assistant Error:', e);
              setStatus('error');
            },
            onclose: () => setStatus('closed'),
          },
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
            },
            systemInstruction: `Você é o CloudGuardian Live Agent. Sua missão é fornecer consultoria de segurança em tempo real via voz. Contexto atual do código Terraform: ${codeContext}. Seja técnico, direto e use um tom profissional de DevSecOps. Ajude o usuário a identificar riscos e sugerir melhores práticas.`,
          },
        });

        sessionRef.current = sessionPromise;
      } catch (err) {
        console.error('Failed to init Live Assistant:', err);
        setStatus('error');
      }
    };

    initializeLiveSession();

    return () => {
      if (inputAudioContext) inputAudioContext.close();
      if (outputAudioContext) outputAudioContext.close();
      if (stream) stream.getTracks().forEach(t => t.stop());
      sessionPromise.then(s => s.close());
    };
  }, [codeContext]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[48px] shadow-2xl p-12 relative overflow-hidden flex flex-col items-center text-center gap-8">
        <div className="absolute top-0 left-0 w-full h-2 bg-primary-500"></div>

        <button onClick={onClose} className="absolute top-8 right-8 text-slate-500 hover:text-white transition-colors">
          <X size={24} />
        </button>

        <div className="relative">
          <div className={`w-32 h-32 rounded-full bg-primary-500/10 border border-primary-500/20 flex items-center justify-center transition-all duration-500 ${isSpeaking ? 'scale-110 shadow-[0_0_50px_rgba(59,130,246,0.3)]' : ''}`}>
             <Bot size={64} className="text-primary-500" />
          </div>
          {status === 'active' && (
            <div className="absolute -bottom-2 -right-2 bg-emerald-500 w-8 h-8 rounded-full border-4 border-slate-900 flex items-center justify-center text-white">
              <Mic size={14} />
            </div>
          )}
        </div>

        <div className="space-y-2">
          <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Live Security Consult</h2>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-[0.2em]">
            {status === 'connecting' ? 'Iniciando Conexão Segura...' : 
             status === 'active' ? (isSpeaking ? 'CloudGuardian está falando...' : 'Ouvindo seus comandos...') : 
             status === 'error' ? 'Falha na conexão de voz' : 'Sessão Encerrada'}
          </p>
        </div>

        <div className="w-full h-24 flex items-center justify-center gap-1.5">
          {status === 'active' ? (
            Array.from({ length: 24 }).map((_, i) => (
              <div 
                key={i} 
                className={`w-1.5 bg-primary-500 rounded-full transition-all duration-150 ${isSpeaking ? 'animate-bounce' : 'opacity-20 h-2'}`}
                style={{ 
                  animationDelay: `${i * 0.05}s`, 
                  height: isSpeaking ? `${20 + Math.random() * 60}%` : '8px' 
                }}
              />
            ))
          ) : (
            <Loader2 className="animate-spin text-slate-700" size={32} />
          )}
        </div>

        <div className="bg-slate-950/60 p-6 rounded-3xl border border-slate-800 w-full text-left flex items-start gap-4">
          <Shield className="text-primary-500 shrink-0" size={24} />
          <div>
            <p className="text-xs font-bold text-white uppercase mb-1">Dica do Especialista:</p>
            <p className="text-[11px] text-slate-500 leading-relaxed italic">
              "Você pode perguntar: 'Quais os riscos do meu bucket S3?' ou 'Como reduzir custos na minha instância EC2?'. O agente analisará seu HCL em tempo real."
            </p>
          </div>
        </div>

        <button 
          onClick={onClose}
          className="px-12 py-4 bg-slate-800 hover:bg-red-600 text-white font-black uppercase tracking-widest rounded-2xl transition-all active:scale-95 flex items-center gap-3 group"
        >
          <X size={18} className="group-hover:rotate-90 transition-transform" />
          Encerrar Chamada
        </button>

        {status === 'error' && (
          <div className="mt-4 p-4 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 text-red-500 animate-bounce">
            <AlertCircle size={20} />
            <span className="text-xs font-bold">Por favor, verifique suas permissões de microfone e chave de API.</span>
          </div>
        )}
      </div>
    </div>
  );
};

// Audio Utilities
function createPcmBlob(data: Float32Array): any {
  const int16 = new Int16Array(data.length);
  for (let i = 0; i < data.length; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encodeBase64(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

function encodeBase64(bytes: Uint8Array) {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) {
    channelData[i] = dataInt16[i] / 32768.0;
  }
  return buffer;
}

import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { AIAssistant } from './components/AIAssistant';
import { LiveAssistant } from './components/LiveAssistant';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { FinOps } from './pages/FinOps';
import { Roadmap } from './pages/Roadmap';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun } from './types';
import { calculateSecurityScore } from './services/engine';
import { Play, CheckCircle, Sparkles, X, CheckCircle2 } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.large" # Triggering FinOps size alert
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>(() => {
    const saved = localStorage.getItem('cg_vulns');
    return saved ? JSON.parse(saved) : [];
  });
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>(() => {
    const saved = localStorage.getItem('cg_timeline');
    return saved ? JSON.parse(saved) : [];
  });
  const [showTour, setShowTour] = useState(true);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('cg_vulns', JSON.stringify(vulnerabilities));
  }, [vulnerabilities]);

  useEffect(() => {
    localStorage.setItem('cg_timeline', JSON.stringify(timelineEvents));
  }, [timelineEvents]);

  // Functional States
  const [policies, setPolicies] = useState<Policy[]>([
    { id: 'pol-01', name: 'S3 Encryption Enforced', description: 'Todos os buckets S3 devem ter criptografia AES-256 ativa.', framework: 'SOC2', severity: Severity.HIGH, status: 'active' },
    { id: 'pol-02', name: 'No Public Ingress 0.0.0.0/0', description: 'Bloquear entrada de tráfego vindo de qualquer lugar para portas sensíveis.', framework: 'ISO27001', severity: Severity.CRITICAL, status: 'active' },
    { id: 'pol-03', name: 'VPC Flow Logs Mandatory', description: 'Ativar flow logs em todas as VPCs para auditoria de tráfego.', framework: 'SOC2', severity: Severity.MEDIUM, status: 'active' }
  ]);

  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([
    { id: 'run-982', branch: 'main', status: 'success', vulns: 0, timestamp: new Date(Date.now() - 3600000).toISOString(), commit: 'feat: add encryption to rds' },
    { id: 'run-981', branch: 'feat/api', status: 'failed', vulns: 3, timestamp: new Date(Date.now() - 86400000).toISOString(), commit: 'fix: security group rules' },
  ]);

  const securityScore = useMemo(() => calculateSecurityScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const addTimelineEvent = (event: Omit<TimelineEvent, 'id' | 'timestamp'>) => {
    const newEvent: TimelineEvent = {
      ...event,
      id: `ev-${Date.now()}`,
      timestamp: new Date().toISOString()
    };
    setTimelineEvents(prev => [newEvent, ...prev]);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    addTimelineEvent({
      type: 'SCAN',
      title: 'Sessão Iniciada',
      description: 'Administrador John Doe acessou o console de segurança.'
    });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    localStorage.removeItem('cg_vulns');
    localStorage.removeItem('cg_timeline');
    setIsAuthenticated(false);
    setIsAuditorMode(false);
    setVulnerabilities([]);
    setTimelineEvents([]);
  };

  const updateVulnerabilities = (newVulns: Vulnerability[]) => {
    setVulnerabilities(newVulns);
    if (newVulns.length > 0) {
      addTimelineEvent({
        type: 'RISK',
        title: 'Vulnerabilidades Detectadas',
        description: `${newVulns.length} riscos encontrados no código Terraform.`,
        severity: Severity.HIGH
      });
      showNotification(`${newVulns.length} riscos encontrados!`, 'error');
    } else {
      showNotification("Scan concluído: Nenhum risco!", "success");
    }
  };

  const applyRemediation = (vulnId: string, fixCode: string) => {
    let updatedCode = terraformCode;
    if (fixCode.includes('private')) updatedCode = updatedCode.replace('public-read', 'private');
    if (fixCode.includes('10.0.0.0/16')) updatedCode = updatedCode.replace('0.0.0.0/0', '10.0.0.0/16');
    if (fixCode.includes('t3.medium')) updatedCode = updatedCode.replace('t2.large', 't3.medium');

    setTerraformCode(updatedCode);
    setVulnerabilities(prev => prev.filter(v => v.id !== vulnId));
    addTimelineEvent({
      type: 'PR',
      title: 'Auto-PR Merged',
      description: `Vulnerabilidade/Custo resolvido via IA. Código atualizado para padrões ideais.`,
      severity: Severity.LOW
    });
    showNotification("Remediação aplicada com sucesso!");
  };

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-primary-500/30 overflow-hidden">
      <Sidebar currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout} isAuditorMode={isAuditorMode} />

      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
        />

        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-indigo-600 to-purple-600 z-50"></div>

        {/* Toast System */}
        {toast && (
          <div className={`fixed top-20 right-8 z-[100] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 duration-300 ${
            toast.type === 'success' ? 'bg-emerald-600' : 'bg-red-600'
          }`}>
            <CheckCircle2 size={20} />
            <span className="text-sm font-bold uppercase tracking-tight">{toast.message}</span>
            <button onClick={() => setToast(null)}><X size={14} /></button>
          </div>
        )}

        <div className="flex-1 overflow-y-auto">
          {currentView === 'dashboard' && <Dashboard isAuditorMode={isAuditorMode} vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={updateVulnerabilities} vulnerabilities={vulnerabilities} onApplyFix={applyRemediation} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} drifts={drifts} setDrifts={setDrifts} onSync={(item) => {
             addTimelineEvent({ type: 'DRIFT', title: 'Drift Sincronizado', description: `Recurso ${item.resource} sincronizado.`, severity: Severity.LOW });
             showNotification("Recurso sincronizado com a nuvem!");
          }} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={addTimelineEvent} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={addTimelineEvent} />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
        </div>

        {isLiveAssistantOpen && (
          <LiveAssistant 
            codeContext={terraformCode} 
            onClose={() => setIsLiveAssistantOpen(false)} 
          />
        )}

        <AIAssistant code={terraformCode} />

        {showTour && (
          <div className="fixed bottom-6 left-[280px] w-72 bg-slate-900/90 backdrop-blur-xl border border-primary-500/30 rounded-2xl shadow-2xl z-50 p-5 animate-in slide-in-from-bottom-10 duration-500">
            <button onClick={() => setShowTour(false)} className="absolute top-3 right-3 text-slate-500 hover:text-white"><X size={14}/></button>
            <div className="flex items-center gap-2 mb-4"><Sparkles className="text-primary-400" size={18} /><h4 className="font-bold text-sm text-white">CloudGuardian Interactive</h4></div>
            <div className="space-y-3">
              <TourItem done={vulnerabilities.length > 0} label="1. Rodar Scan de IA" onClick={() => setCurrentView('scanner')} />
              <TourItem done={vulnerabilities.some(v => v.type === 'finops')} label="2. Otimizar Custos" onClick={() => setCurrentView('finops')} />
              <TourItem done={currentView === 'roadmap'} label="3. Ver Roadmap V1.0" onClick={() => setCurrentView('roadmap')} />
              <TourItem done={false} label="4. Baixar Relatório" onClick={() => setCurrentView('report')} />
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

const TourItem = ({ label, done, onClick }: { label: string, done: boolean, onClick: () => void }) => (
  <button onClick={onClick} className={`w-full flex items-center justify-between p-2 rounded-lg text-left text-xs transition-all ${done ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-slate-950 border border-slate-800 text-slate-400 hover:bg-slate-800'}`}>
    <span>{label}</span>{done ? <CheckCircle size={14} /> : <Play size={14} className="opacity-50" />}
  </button>
);

export default App;

