// Simula o delay de rede de um backend real
const API_DELAY = 800;

export const dbService = {
  async saveScan(vulnerabilities: Vulnerability[], code: string) {
    await new Promise(resolve => setTimeout(resolve, API_DELAY));
    const scanRecord = {
      id: `scan-${Date.now()}`,
      timestamp: new Date().toISOString(),
      vulnsCount: vulnerabilities.length,
      code: code.substring(0, 100) + "...",
      fullCode: code
    };

    const history = JSON.parse(localStorage.getItem('cg_scan_history') || '[]');
    localStorage.setItem('cg_scan_history', JSON.stringify([scanRecord, ...history].slice(0, 10)));
    return scanRecord;
  },

  async getScanHistory() {
    await new Promise(resolve => setTimeout(resolve, API_DELAY / 2));
    return JSON.parse(localStorage.getItem('cg_scan_history') || '[]');
  },

  async saveOrgSettings(settings: any) {
    await new Promise(resolve => setTimeout(resolve, API_DELAY));
    localStorage.setItem('cg_org_settings', JSON.stringify(settings));
  },

  async getOrgSettings() {
    return JSON.parse(localStorage.getItem('cg_org_settings') || '{"name": "CloudGuardian Dev", "tier": "Pro"}');
  }
};

