const API_DELAY = 600;

export const dbService = {
  async saveScan(vulnerabilities: Vulnerability[], code: string) {
    await new Promise(resolve => setTimeout(resolve, API_DELAY));
    const scanRecord = {
      id: `scan-${Date.now()}`,
      timestamp: new Date().toISOString(),
      vulnsCount: vulnerabilities.length,
      code: code.substring(0, 100) + "...",
      fullCode: code
    };

    const history = JSON.parse(localStorage.getItem('cg_scan_history') || '[]');
    localStorage.setItem('cg_scan_history', JSON.stringify([scanRecord, ...history].slice(0, 10)));
    return scanRecord;
  },

  async getScanHistory() {
    await new Promise(resolve => setTimeout(resolve, API_DELAY / 2));
    return JSON.parse(localStorage.getItem('cg_scan_history') || '[]');
  },

  // Project Management
  async getProjects(): Promise<Project[]> {
    await new Promise(resolve => setTimeout(resolve, API_DELAY));
    const saved = localStorage.getItem('cg_projects');
    if (!saved) {
      const initial: Project[] = [
        { id: 'proj-1', name: 'Infrastructure-Prod', cloud: 'AWS', status: 'active', lastScan: new Date().toISOString(), score: 85 },
        { id: 'proj-2', name: 'Legacy-Backend', cloud: 'Azure', status: 'active', lastScan: new Date().toISOString(), score: 42 }
      ];
      localStorage.setItem('cg_projects', JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(saved);
  },

  async saveProject(project: Project) {
    const projects = await this.getProjects();
    const index = projects.findIndex(p => p.id === project.id);
    if (index > -1) projects[index] = project;
    else projects.push(project);
    localStorage.setItem('cg_projects', JSON.stringify(projects));
  },

  // Member Management
  async getMembers(): Promise<OrgMember[]> {
    const saved = localStorage.getItem('cg_members');
    if (!saved) {
      const initial: OrgMember[] = [
        { id: 'mem-1', name: 'John Doe', email: 'admin@cloudguardian.ai', role: 'admin', lastActive: 'Online Agora' },
        { id: 'mem-2', name: 'Jane Smith', email: 'jane@cloudguardian.ai', role: 'editor', lastActive: '2h atrás' }
      ];
      localStorage.setItem('cg_members', JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(saved);
  },

  async addMember(member: OrgMember) {
    const members = await this.getMembers();
    members.push(member);
    localStorage.setItem('cg_members', JSON.stringify(members));
  }
};

