  id: string;
  source: string;
  target: string;
  animated?: boolean;
}

export type View = 'dashboard' | 'scanner' | 'graph' | 'compliance' | 'drift' | 'settings' | 'automation' | 'report' | 'timeline' | 'sales-playbook' | 'policies' | 'cicd' | 'finops' | 'roadmap' | 'organization';

import React, { useMemo, useState } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Server, Database, Globe, Layers, X, Info, 
  AlertTriangle, ShieldCheck, ArrowRight, ExternalLink, Activity, Target, Zap, Cpu
} from 'lucide-react';
import { Vulnerability, GraphNode, Severity, GraphEdge } from '../types';

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
}

const getCategoryIcon = (category: string, size: number, color?: string) => {
  switch (category) {
    case 'compute': return <Cpu size={size} color={color} />;
    case 'storage': return <Database size={size} color={color} />;
    case 'network': return <Globe size={size} color={color} />;
    case 'security': return <Shield size={size} color={color} />;
    default: return <Layers size={size} color={color} />;
  }
};

const getCategoryHex = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; // Purple
    case 'storage': return '#eab308'; // Yellow
    case 'network': return '#3b82f6'; // Blue
    case 'security': return '#10b981'; // Emerald
    default: return '#64748b'; // Slate
  }
};

interface NodeComponentProps {
  node: GraphNode & { vulnerabilities: Vulnerability[] };
  isSelected: boolean;
  isAffected: boolean;
  onClick: () => void;
}

const Node: React.FC<NodeComponentProps> = ({ node, isSelected, isAffected, onClick }) => {
    const isRisk = node.status === 'risk';
    const category = node.data.category;
    const baseColor = isRisk ? '#ef4444' : (isAffected ? '#f59e0b' : getCategoryHex(category));

    return (
        <g 
          className="transition-all duration-300 cursor-pointer" 
          onClick={(e) => { e.stopPropagation(); onClick(); }}
          transform={`translate(${node.position.x}, ${node.position.y})`}
        >
            {/* Pulsing ring for risk nodes */}
            {isRisk && (
              <circle r="35" fill="none" stroke="#ef4444" strokeWidth="2" className="animate-ping opacity-20" />
            )}

            {/* Selection/Affected Highlights */}
            {isSelected && (
              <circle r="42" fill="none" stroke="#3b82f6" strokeWidth="2" strokeDasharray="4 4" className="animate-[spin_12s_linear_infinite]" />
            )}

            <circle 
              r="32" 
              fill={isSelected ? "#1e293b" : "#020617"} 
              stroke={baseColor} 
              strokeWidth={isSelected || isRisk || isAffected ? "3" : "1.5"} 
              className="transition-all duration-300 hover:stroke-white shadow-2xl"
              style={{ filter: isRisk ? 'url(#glow-red)' : (isAffected ? 'url(#glow-orange)' : 'none') }}
            />

            <g transform="translate(-10, -10)">
              {getCategoryIcon(category, 20, isRisk ? '#ef4444' : (isAffected ? '#f59e0b' : baseColor))}
            </g>

            {/* Labeling */}
            <g transform="translate(0, 48)">
              <text textAnchor="middle" fill="white" fontSize="10" fontWeight="900" className="uppercase tracking-tighter shadow-sm">{node.data.label}</text>
              <text y="12" textAnchor="middle" fill="#475569" fontSize="7" fontWeight="bold" className="uppercase tracking-[0.2em]">{node.data.resource_type}</text>
            </g>

            {/* Status Overlays */}
            {isRisk && (
              <g transform="translate(22, -22)">
                <circle r="9" fill="#ef4444" stroke="#020617" strokeWidth="2" />
                <path d="M0 -3 L0 1 M0 3 L0 3" transform="translate(0, 0)" stroke="white" strokeWidth="2" strokeLinecap="round" />
              </g>
            )}
        </g>
    );
};

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  const { nodes, edges } = useMemo(() => {
    const graph = parseHclToGraph(code);
    const enrichedNodes = graph.nodes.map(node => {
        const nodeVulns = vulnerabilities.filter(v => 
          v.resource.includes(node.id) || 
          node.id.includes(v.resource) ||
          v.resource.includes(node.data.label)
        );
        return { 
          ...node, 
          status: nodeVulns.length > 0 ? 'risk' : 'healthy' as any,
          vulnerabilities: nodeVulns 
        };
    });
    return { nodes: enrichedNodes, edges: graph.edges };
  }, [code, vulnerabilities]);

  const affectedNodeIds = useMemo(() => {
    if (!selectedNodeId) return [];
    const affected = new Set<string>();
    const findDependents = (nodeId: string) => {
      edges.forEach(edge => {
        if (edge.source === nodeId && !affected.has(edge.target)) {
          affected.add(edge.target);
          findDependents(edge.target);
        }
      });
    };
    findDependents(selectedNodeId);
    return Array.from(affected);
  }, [selectedNodeId, edges]);

  const selectedNode = nodes.find(n => n.id === selectedNodeId) as (GraphNode & { vulnerabilities: Vulnerability[] }) | undefined;

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-700 relative overflow-hidden">
       <div className="flex justify-between items-end relative z-10">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Infrastructure Topology</h2>
          <p className="text-slate-500 text-sm font-bold flex items-center gap-2">
              <Activity size={14} className="text-primary-500" />
              Visualização ativa de dependências e Blast Radius.
          </p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3 bg-slate-900/80 backdrop-blur px-4 py-2 rounded-2xl border border-slate-800 shadow-xl">
             <Target className="text-amber-500" size={16} />
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{nodes.length} Recursos Monitorados</span>
          </div>
        </div>
      </div>

      <div className="flex-1 bg-slate-950 border border-slate-800 rounded-[48px] relative overflow-hidden flex items-center justify-center shadow-inner group" onClick={() => setSelectedNodeId(null)}>
        <div className="absolute inset-0 opacity-[0.05] pointer-events-none" style={{ 
          backgroundImage: 'radial-gradient(circle, #3b82f6 1.5px, transparent 1.5px)', 
          backgroundSize: '48px 48px' 
        }}></div>

        {nodes.length === 0 ? (
          <div className="text-slate-500 flex flex-col items-center p-12 border-2 border-dashed border-slate-800 rounded-[32px] bg-slate-900/20 relative z-10">
             <Layers size={48} className="text-slate-800 mb-4" />
             <p className="font-bold text-white opacity-50 uppercase tracking-widest text-xs">Aguardando definição de recursos...</p>
          </div>
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 900 600" className="w-full h-full relative z-10 select-none">
              <defs>
                  <filter id="glow-red" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation="5" result="blur" />
                    <feFlood floodColor="#ef4444" floodOpacity="0.4" result="flood" />
                    <feComposite in="flood" in2="blur" operator="in" result="glow" />
                    <feMerge>
                      <feMergeNode in="glow" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                  <filter id="glow-orange" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation="5" result="blur" />
                    <feFlood floodColor="#f59e0b" floodOpacity="0.4" result="flood" />
                    <feComposite in="flood" in2="blur" operator="in" result="glow" />
                    <feMerge>
                      <feMergeNode in="glow" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                  <marker id="arrowhead" markerWidth="8" markerHeight="6" refX="32" refY="3" orient="auto">
                    <polygon points="0 0, 8 3, 0 6" fill="#1e293b" />
                  </marker>
              </defs>

              <g>
                  {edges.map(edge => {
                      const sourceNode = nodes.find(n => n.id === edge.source);
                      const targetNode = nodes.find(n => n.id === edge.target);
                      if (!sourceNode || !targetNode) return null;

                      const isAffectedLink = (edge.source === selectedNodeId || affectedNodeIds.includes(edge.source)) && affectedNodeIds.includes(edge.target);
                      const isSelectedLink = edge.source === selectedNodeId || edge.target === selectedNodeId;

                      return (
                        <path 
                          key={edge.id} 
                          d={`M ${sourceNode.position.x} ${sourceNode.position.y} L ${targetNode.position.x} ${targetNode.position.y}`}
                          stroke={isSelectedLink ? "#3b82f6" : (isAffectedLink ? "#f59e0b" : "#1e293b")}
                          strokeWidth={isSelectedLink || isAffectedLink ? 2 : 1}
                          strokeOpacity={isSelectedLink || isAffectedLink ? 0.8 : 0.4}
                          fill="none"
                          markerEnd="url(#arrowhead)"
                          className="transition-all duration-300"
                        />
                      );
                  })}
              </g>

              {nodes.map(node => (
                  <Node 
                      key={node.id} 
                      node={node as any}
                      isSelected={selectedNodeId === node.id}
                      isAffected={affectedNodeIds.includes(node.id)}
                      onClick={() => setSelectedNodeId(node.id)}
                  />
              ))}
          </svg>
        )}

        <div className="absolute bottom-10 left-10 bg-slate-900/90 backdrop-blur-xl p-6 rounded-[32px] border border-slate-800 shadow-2xl space-y-4">
            <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Legenda de Topologia</h4>
            <div className="space-y-2.5">
                <LegendItem color="bg-blue-500" label="Rede / Conectividade" />
                <LegendItem color="bg-purple-500" label="Processamento / Compute" />
                <LegendItem color="bg-yellow-500" label="Dados / Storage" />
                <div className="h-px bg-slate-800/50 my-2"></div>
                <LegendItem color="bg-red-500 animate-pulse" label="Risco Crítico Ativo" />
                <LegendItem color="bg-amber-500" label="Recurso Afetado (Blast)" />
            </div>
        </div>

        {selectedNode && (
          <div className="absolute top-0 right-0 h-full w-80 bg-slate-900/95 backdrop-blur-3xl border-l border-slate-800 shadow-[-20px_0_40px_rgba(0,0,0,0.5)] z-20 animate-in slide-in-from-right duration-500 flex flex-col" onClick={(e) => e.stopPropagation()}>
            <div className="p-8 border-b border-slate-800 space-y-4">
               <div className="flex justify-between items-start">
                  <div className={`p-3 rounded-2xl ${selectedNode.status === 'risk' ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                    {getCategoryIcon(selectedNode.data.category, 24)}
                  </div>
                  <button onClick={() => setSelectedNodeId(null)} className="p-2 hover:bg-slate-800 rounded-xl text-slate-500 transition-colors">
                    <X size={20} />
                  </button>
               </div>
               <div>
                  <h3 className="text-xl font-black text-white italic tracking-tighter uppercase">{selectedNode.data.label}</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{selectedNode.data.resource_type}</p>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
               <section className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Health Status</h4>
                  <div className={`p-4 rounded-2xl border flex items-center gap-3 ${selectedNode.status === 'risk' ? 'bg-red-500/5 border-red-500/20 text-red-500' : 'bg-emerald-500/5 border-emerald-500/20 text-emerald-500'}`}>
                    {selectedNode.status === 'risk' ? <AlertTriangle size={18} /> : <ShieldCheck size={18} />}
                    <span className="text-xs font-black uppercase">{selectedNode.status === 'risk' ? 'Crítico: Ação Requerida' : 'Infraestrutura Segura'}</span>
                  </div>
               </section>

               {affectedNodeIds.length > 0 && (
                 <section className="space-y-3">
                    <h4 className="text-[10px] font-black text-amber-500 uppercase tracking-widest flex items-center gap-2">
                        <Target size={14} /> Análise de Blast Radius
                    </h4>
                    <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl p-4 space-y-3">
                        <p className="text-[10px] text-amber-500/80 font-bold leading-relaxed uppercase">
                          Uma falha neste nó compromete a disponibilidade de {affectedNodeIds.length} recursos dependentes.
                        </p>
                        <div className="space-y-1.5 border-t border-amber-500/10 pt-3">
                            {affectedNodeIds.map(id => (
                                <div key={id} className="flex items-center gap-2 text-[9px] text-slate-400 font-mono">
                                    <Zap size={10} className="text-amber-500" /> {id}
                                </div>
                            ))}
                        </div>
                    </div>
                 </section>
               )}

               {selectedNode.vulnerabilities.length > 0 && (
                 <section className="space-y-3">
                    <h4 className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Findings ({selectedNode.vulnerabilities.length})</h4>
                    <div className="space-y-3">
                      {selectedNode.vulnerabilities.map(v => (
                        <div key={v.id} className="bg-slate-950/80 p-4 rounded-2xl border border-slate-800 space-y-3">
                           <div className="flex justify-between items-center">
                              <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase ${v.severity === Severity.CRITICAL ? 'bg-red-500/20 text-red-500' : 'bg-orange-500/20 text-orange-500'}`}>
                                {v.severity}
                              </span>
                              <span className="text-[8px] text-slate-600 font-mono">ID: {v.ruleId}</span>
                           </div>
                           <p className="text-xs font-bold text-slate-200 leading-tight">{v.title}</p>
                        </div>
                      ))}
                    </div>
                 </section>
               )}
            </div>

            <div className="p-8 border-t border-slate-800">
               <button className="w-full py-4 bg-primary-600 hover:bg-primary-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 flex items-center justify-center gap-2">
                  Ver no Cloud Console <ExternalLink size={14} />
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const LegendItem = ({ color, label }: any) => (
  <div className="flex items-center gap-3">
    <div className={`w-2.5 h-2.5 rounded-full ${color} shadow-lg`}></div>
    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
  </div>
);

export enum Severity {
  LOW = "LOW",
  MEDIUM = "MEDIUM",
  HIGH = "HIGH",
  CRITICAL = "CRITICAL"
}

export enum ScanStatus {
  OPEN = "OPEN",
  FIXED = "FIXED",
  IGNORED = "IGNORED",
  IN_PROGRESS = "IN_PROGRESS"
}

export interface Vulnerability {
  id: string;
  ruleId: string;
  title: string;
  description: string;
  severity: Severity;
  status: ScanStatus;
  resource: string;
  line?: number;
  remediation?: string;
  complianceMapping?: string[];
  type?: 'security' | 'finops' | 'best_practice';
}

export interface SecurityScore {
  total: number;
  infrastructure: number;
  secrets: number;
  compliance: number;
  drift: number;
  finops: number;
  trend: number;
}

export interface DriftItem {
  id: string;
  resource: string;
  property: string;
  terraformValue: string;
  cloudValue: string;
  severity: Severity;
}

export interface ComplianceControl {
  id: string;
  framework: 'SOC2' | 'ISO27001' | 'HIPAA' | 'PCI-DSS' | 'GDPR';
  title: string;
  description?: string;
  status: 'PASS' | 'FAIL' | 'WARNING';
  score: number;
}

export interface TimelineEvent {
  id: string;
  type: 'SCAN' | 'RISK' | 'PR' | 'COMPLIANCE' | 'DRIFT' | 'PIPELINE' | 'POLICY' | 'FINOPS' | 'ORG';
  title: string;
  description: string;
  severity?: Severity;
  timestamp: string;
  metadata?: any;
}

export interface Policy {
  id: string;
  name: string;
  description: string;
  framework: string;
  severity: Severity;
  status: 'active' | 'draft';
}

export interface PipelineRun {
  id: string;
  branch: string;
  status: 'success' | 'failed' | 'running' | 'pending';
  vulns: number;
  timestamp: string;
  commit: string;
  prNumber?: number;
}

export interface Project {
  id: string;
  name: string;
  cloud: 'AWS' | 'Azure' | 'GCP';
  status: 'active' | 'archived';
  lastScan: string;
  score: number;
}

export interface OrgMember {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'editor' | 'auditor';
  lastActive: string;
}

export interface GraphNode {
  id: string;
  data: {
    label: string;
    category: 'compute' | 'storage' | 'network' | 'security' | 'unspecified';
    resource_type: string;
  };
  position: { x: number; y: number };
  status: 'healthy' | 'risk';
}

export interface GraphEdge {
  id: string;
  source: string;
  target: string;
  animated?: boolean;
}

export type View = 'dashboard' | 'scanner' | 'graph' | 'compliance' | 'drift' | 'settings' | 'automation' | 'report' | 'timeline' | 'sales-playbook' | 'policies' | 'cicd' | 'finops' | 'roadmap' | 'organization';

import React, { useState, useEffect, useRef } from 'react';
import { Terminal, Github, GitBranch, ShieldCheck, CheckCircle2, XCircle, Clock, Play, ArrowUpRight, GitCommit, Loader2, ChevronRight, Copy, Check, FileCode, Zap, AlertTriangle, ShieldAlert } from 'lucide-react';
import { PipelineRun, Severity } from '../types';

interface PipelineInsightsProps {
  runs: PipelineRun[];
  setRuns: React.Dispatch<React.SetStateAction<PipelineRun[]>>;
  onNotify: (msg: string) => void;
  onTimeline: (event: any) => void;
}

export const PipelineInsights: React.FC<PipelineInsightsProps> = ({ runs, setRuns, onNotify, onTimeline }) => {
  const [isTriggering, setIsTriggering] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'workflow' | 'pr-simulator'>('history');
  const [logs, setLogs] = useState<string[]>([]);
  const [copied, setCopied] = useState(false);
  const [simulatingPR, setSimulatingPR] = useState(false);
  const logEndRef = useRef<HTMLDivElement>(null);

  const workflowYaml = `name: CloudGuardian Security Scan

on:
  pull_request:
    branches: [ main, develop ]
    paths:
      - '**.tf'
      - '**.tfvars'

jobs:
  security_scan:
    name: CloudGuardian IaC Analysis
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v3

      - name: Run CloudGuardian Engine
        uses: cloudguardian/scanner-action@v1
        with:
          api_key: \${{ secrets.CG_API_KEY }}
          fail_on_critical: true
          output_format: github-pr-comment

      - name: AI Auto-Remediation Suggestion
        if: failure()
        run: echo "CloudGuardian detectou vulnerabilidades. Verifique os comentários no PR."`;

  const addLog = (msg: string) => setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);

  useEffect(() => {
    if (logEndRef.current) logEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(workflowYaml);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    onNotify("Workflow copiado para o clipboard!");
  };

  const triggerManualScan = () => {
    setIsTriggering(true);
    setLogs([]);
    addLog("Initializing CloudGuardian CI/CD Runner v2.4...");

    setTimeout(() => {
      addLog("Fetching Terraform HCL context...");
      setTimeout(() => {
        addLog("Running SAST analysis with Gemini Engine...");
        setTimeout(() => {
          addLog("Policy validation: SOC2 CC6.6 - PASS");
          setTimeout(() => {
            addLog("Policy validation: ISO27001 A.10 - PASS");
            setTimeout(() => {
              addLog("Finalizing results and reporting to central dashboard...");

              const newRun: PipelineRun = {
                id: `run-${Math.floor(Math.random() * 1000)}`,
                branch: 'main',
                status: 'success',
                vulns: 0,
                timestamp: new Date().toISOString(),
                commit: 'manual: security baseline scan'
              };

              setRuns(prev => [newRun, ...prev]);
              setIsTriggering(false);
              onNotify("Pipeline executado com sucesso!");
              onTimeline({
                type: 'PIPELINE',
                title: 'Pipeline Ad-Hoc Concluído',
                description: 'Scan manual de infraestrutura validado. Status: Clean.',
                severity: Severity.LOW
              });
            }, 500);
          }, 400);
        }, 600);
      }, 500);
    }, 500);
  };

  const runPRSimulation = () => {
    setSimulatingPR(true);
    setTimeout(() => {
      const newRun: PipelineRun = {
        id: `run-${Math.floor(Math.random() * 1000)}`,
        branch: 'feat/new-s3-bucket',
        status: 'failed',
        vulns: 2,
        timestamp: new Date().toISOString(),
        commit: 'chore: add logs bucket',
        prNumber: Math.floor(Math.random() * 100) + 50
      };
      setRuns(prev => [newRun, ...prev]);
      setSimulatingPR(false);
      onNotify("PR Scan concluído: Riscos detectados!");
      onTimeline({
        type: 'PIPELINE',
        title: 'PR Guard: Bloqueio de Segurança',
        description: `O PR #${newRun.prNumber} foi sinalizado com riscos críticos.`,
        severity: Severity.HIGH
      });
    }, 3000);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500 text-slate-200">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Pipeline Insights</h2>
          <p className="text-slate-400 text-sm">Integração nativa de segurança no fluxo de CI/CD (Shift-Left).</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={triggerManualScan}
            disabled={isTriggering}
            className="flex items-center gap-2 px-6 py-3 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl border border-slate-700 transition-all shadow-xl disabled:opacity-50 active:scale-95"
          >
            {isTriggering ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {isTriggering ? 'Executing...' : 'Manual Scan'}
          </button>
          <button 
            onClick={runPRSimulation}
            disabled={simulatingPR}
            className="flex items-center gap-2 px-6 py-3 bg-primary-600 hover:bg-primary-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 disabled:opacity-50 active:scale-95"
          >
            {simulatingPR ? <Loader2 className="animate-spin" size={16} /> : <Zap size={16} />}
            Simular PR Guard
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex gap-2 p-1 bg-slate-900 rounded-2xl w-fit border border-slate-800">
        <TabButton active={activeTab === 'history'} onClick={() => setActiveTab('history')} label="Run History" icon={<Clock size={14}/>} />
        <TabButton active={activeTab === 'workflow'} onClick={() => setActiveTab('workflow')} label="Setup Workflow" icon={<FileCode size={14}/>} />
        <TabButton active={activeTab === 'pr-simulator'} onClick={() => setActiveTab('pr-simulator')} label="PR Guard Simulator" icon={<Github size={14}/>} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 space-y-6">
          {activeTab === 'history' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-8 shadow-2xl relative overflow-hidden flex flex-col">
               <div className="absolute top-0 right-0 p-8 opacity-5">
                  <Github size={120} />
               </div>

               <div className="flex items-center justify-between relative z-10">
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-500">
                        <ShieldCheck size={24} />
                     </div>
                     <div>
                        <h3 className="text-lg font-bold text-white tracking-tight">CI/CD Execution Logs</h3>
                        <p className="text-xs text-slate-500 font-mono uppercase tracking-widest">Global Monitoring active</p>
                     </div>
                  </div>
               </div>

               {isTriggering && (
                 <div className="bg-black/80 rounded-2xl p-6 border border-slate-800 font-mono text-[10px] text-emerald-500 min-h-[160px] max-h-[160px] overflow-y-auto space-y-1 custom-scrollbar animate-in zoom-in-95">
                    {logs.map((log, i) => (
                      <div key={i} className="flex gap-3">
                        <ChevronRight size={10} className="mt-0.5 opacity-50" />
                        <span>{log}</span>
                      </div>
                    ))}
                    <div ref={logEndRef} />
                 </div>
               )}

               <div className="space-y-4 relative z-10 flex-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Histórico de Pipeline</h4>
                  <div className="space-y-3">
                    {runs.map(run => (
                      <PipelineRunRow key={run.id} {...run} />
                    ))}
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'workflow' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-6 shadow-2xl animate-in fade-in duration-300">
               <div className="flex justify-between items-center">
                  <div>
                    <h3 className="text-lg font-bold text-white flex items-center gap-2 italic uppercase tracking-tight">
                      <FileCode className="text-primary-500" /> GitHub Actions Setup
                    </h3>
                    <p className="text-[10px] text-slate-500 uppercase font-black mt-1">Implemente o CloudGuardian em seu pipeline em segundos.</p>
                  </div>
                  <button 
                    onClick={copyToClipboard}
                    className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase rounded-xl transition-all"
                  >
                    {copied ? <Check size={14} /> : <Copy size={14} />}
                    {copied ? 'Copiado' : 'Copiar YAML'}
                  </button>
               </div>

               <div className="bg-slate-950 border border-slate-800 rounded-2xl p-6 font-mono text-[11px] text-slate-400 overflow-x-auto custom-scrollbar shadow-inner leading-relaxed">
                  <pre>{workflowYaml}</pre>
               </div>

               <div className="p-4 bg-primary-500/5 border border-primary-500/20 rounded-2xl flex items-start gap-4">
                  <Zap className="text-primary-500 mt-1" size={20} />
                  <div>
                    <p className="text-xs font-bold text-white uppercase tracking-tight">Como instalar:</p>
                    <p className="text-[11px] text-slate-500 leading-relaxed mt-1">
                      1. Crie o arquivo <code className="text-primary-400">.github/workflows/cloudguardian.yml</code><br/>
                      2. Cole o código acima.<br/>
                      3. Adicione sua chave de API nos Secrets do repositório como <code className="text-primary-400">CG_API_KEY</code>.
                    </p>
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'pr-simulator' && (
            <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
               <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-6 shadow-2xl">
                  <div className="flex justify-between items-start">
                    <div className="flex gap-4">
                      <div className="w-12 h-12 bg-slate-950 border border-slate-800 rounded-2xl flex items-center justify-center text-primary-500">
                        <Github size={24} />
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-white tracking-tighter uppercase italic">Pull Request Guard Simulator</h3>
