import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, Project, OrgMember, SecurityScore, Severity, ScanStatus } from '../types';

// O "Backend" utiliza o Gemini como motor de inteligência
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const LATENCY = 600; //ms

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val))
  };

  // --- API: Infra & Scans ---
  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));

    // Análise via IA (Motor Gemini)
    const model = 'gemini-3-pro-preview';
    const prompt = `
      Analyze this Terraform code for vulnerabilities:
      ${code}
      Return a JSON with "findings" array following the Vulnerability interface.
    `;

    let aiFindings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });
      const data = JSON.parse(response.text || '{}');
      aiFindings = data.findings || [];
    } catch (e) {
      console.error("Backend AI Error", e);
    }

    const vulns: Vulnerability[] = aiFindings.map((f, i) => ({
      ...f,
      id: `vuln-${Date.now()}-${i}`,
      status: ScanStatus.OPEN,
      type: f.type || 'security'
    }));

    // Persistir Scan no Histórico
    const history = this.db.get('scan_history');
    this.db.set('scan_history', [{ id: Date.now(), timestamp: new Date(), count: vulns.length }, ...history]);

    return { vulns, score: this.calculateScore(vulns) };
  }

  private calculateScore(vulns: Vulnerability[]): SecurityScore {
    // Lógica simplificada de pontuação
    const total = Math.max(0, 100 - (vulns.length * 5));
    return {
      total,
      infrastructure: total,
      secrets: 100,
      compliance: total - 5,
      drift: 100,
      finops: 100,
      trend: 0
    };
  }

  // --- API: Organization & Projects ---
  async getProjects(): Promise<Project[]> {
    await new Promise(r => setTimeout(r, LATENCY));
    let projects = this.db.get('projects');
    if (projects.length === 0) {
      projects = [
        { id: 'proj-1', name: 'Production-VPC', cloud: 'AWS', status: 'active', lastScan: new Date().toISOString(), score: 88 },
        { id: 'proj-2', name: 'Staging-K8s', cloud: 'AWS', status: 'active', lastScan: new Date().toISOString(), score: 95 }
      ];
      this.db.set('projects', projects);
    }
    return projects;
  }

  async getMembers(): Promise<OrgMember[]> {
    await new Promise(r => setTimeout(r, LATENCY / 2));
    let members = this.db.get('members');
    if (members.length === 0) {
      members = [
        { id: 'u-1', name: 'John Doe', email: 'admin@cloudguardian.ai', role: 'admin', lastActive: 'Ativo Agora' }
      ];
      this.db.set('members', members);
    }
    return members;
  }

  // --- API: Audit & Timeline ---
  async getTimeline(): Promise<TimelineEvent[]> {
    return this.db.get('timeline');
  }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline]);
    return newEvent;
  }
}

export const API = new CloudGuardianBackend();

