const DEFAULT_CODE = `resource "aws_s3_bucket" "data" {
  bucket = "my-public-bucket"
  acl    = "public-read"
}

resource "aws_security_group" "web" {
  name = "allow_all"
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-12345678"
  instance_type = "t2.large"
  vpc_security_group_ids = [aws_security_group.web.id]
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);

  // States gerenciados pelo Backend
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [securityScore, setSecurityScore] = useState({ total: 100, infrastructure: 100, secrets: 100, compliance: 100, drift: 100, finops: 100, trend: 0 });

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  // Inicialização de Dados via API
  useEffect(() => {
    if (isAuthenticated) {
      const loadInitialData = async () => {
        const [timeline, vulns] = await Promise.all([
          API.getTimeline(),
          Promise.resolve(JSON.parse(localStorage.getItem('cg_vulns') || '[]'))
        ]);
        setTimelineEvents(timeline);
        setVulnerabilities(vulns);
        setIsInitializing(false);
      };
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    API.logEvent({
      type: 'SCAN',
      title: 'Sessão Iniciada',
      description: 'Administrador John Doe acessou o console de segurança.'
    }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
  };

  const handleScanRequest = async () => {
    showNotification("Iniciando análise de backend...", "success");
    const result = await API.scanInfrastructure(terraformCode);
    setVulnerabilities(result.vulns);
    setSecurityScore(result.score);

    const log = await API.logEvent({
      type: 'RISK',
      title: 'Scan de Infraestrutura Concluído',
      description: `${result.vulns.length} vulnerabilidades processadas pelo motor de IA.`,
      severity: result.vulns.length > 0 ? Severity.HIGH : Severity.LOW
    });
    setTimelineEvents(prev => [log, ...prev]);
    showNotification("Scan completo!");
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
        <Loader2 className="text-primary-500 animate-spin" size={48} />
        <span className="text-slate-500 font-black uppercase text-[10px] tracking-widest">Iniciando CloudGuardian Backend...</span>
      </div>
    );
  }

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

