import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, Project, OrgMember, SecurityScore, Severity, ScanStatus, Policy, PipelineRun } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  // --- Sistema de Assinatura (Monetização) ---
  async getSubscriptionStatus() {
    return this.db.getSingle('subscription', { tier: 'free', expires: null, founderDeal: false });
  }

  async upgradeToPro(founder = false) {
    const sub = { tier: 'pro', expires: '2026-01-01', founderDeal: founder };
    this.db.set('subscription', sub);
    return sub;
  }

  // --- Core Engine: Análise DevSecOps ---
  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));

    const model = 'gemini-3-pro-preview';
    const systemPrompt = `Analyze Terraform HCL for security. Return JSON with 'findings' array. Findings must include ruleId, title, severity (CRITICAL/HIGH/MEDIUM/LOW), resource, description, remediation, type (security/finops), and complianceMapping (SOC2/ISO).`;

    let findings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: `${systemPrompt}\n\nCode:\n${code}`,
        config: { responseMimeType: "application/json" }
      });
      const data = JSON.parse(response.text || '{}');
      findings = data.findings || [];
    } catch (e) {
      console.error("AI Analysis Failed", e);
    }

    const vulns: Vulnerability[] = findings.map((f, i) => ({
      ...f,
      id: `vuln-${Date.now()}-${i}`,
      status: ScanStatus.OPEN
    }));

    // Lógica de Score Realista
    const score = this.calculateScore(vulns);

    // Persistência
    const history = this.db.get('scan_history');
    this.db.set('scan_history', [{ id: Date.now(), timestamp: new Date(), vulnsCount: vulns.length, score: score.total }, ...history]);

    return { vulns, score };
  }

  private calculateScore(vulns: Vulnerability[]): SecurityScore {
    const criticals = vulns.filter(v => v.severity === Severity.CRITICAL).length;
    const highs = vulns.filter(v => v.severity === Severity.HIGH).length;
    const total = Math.max(0, 100 - (criticals * 20) - (highs * 10));

    return {
      total,
      infrastructure: Math.max(0, total + 5),
      secrets: 100, // Simulado
      compliance: Math.max(0, total - 10),
      drift: 100,
      finops: 100,
      trend: total > 80 ? 1.5 : -0.5
    };
  }

  // --- Gestão de Políticas (Governance-as-Code) ---
  async getPolicies(): Promise<Policy[]> {
    const pols = this.db.get('policies');
    if (pols.length === 0) {
      const initial: Policy[] = [
        { id: 'p1', name: 'No Public S3 Buckets', description: 'Enforce private ACLs on all S3 resources.', framework: 'SOC2', severity: Severity.CRITICAL, status: 'active' },
        { id: 'p2', name: 'Restrict SSH Access', description: 'Port 22 must not be open to 0.0.0.0/0.', framework: 'ISO27001', severity: Severity.HIGH, status: 'active' }
      ];
      this.db.set('policies', initial);
      return initial;
    }
    return pols;
  }

  async savePolicy(policy: Policy) {
    const pols = await this.getPolicies();
    this.db.set('policies', [policy, ...pols]);
  }

  // --- Timeline & Auditoria ---
  async getTimeline(): Promise<TimelineEvent[]> {
    return this.db.get('timeline');
  }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline]);
    return newEvent;
  }
}

