import React, { useMemo, useState, useEffect } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Server, Database, Globe, Layers, X, Info, 
  AlertTriangle, ShieldCheck, ArrowRight, ExternalLink, Activity, Target, Zap, Cpu,
  Maximize2, MousePointer2, Filter, Share2
} from 'lucide-react';
import { Vulnerability, GraphNode, Severity, GraphEdge } from '../types';

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
}

const getCategoryIcon = (category: string, size: number, color?: string) => {
  switch (category) {
    case 'compute': return <Cpu size={size} color={color} />;
    case 'storage': return <Database size={size} color={color} />;
    case 'network': return <Globe size={size} color={color} />;
    case 'security': return <Shield size={size} color={color} />;
    default: return <Layers size={size} color={color} />;
  }
};

const getCategoryHex = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; 
    case 'storage': return '#eab308'; 
    case 'network': return '#3b82f6'; 
    case 'security': return '#10b981'; 
    default: return '#64748b'; 
  }
};

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [hoveredNodeId, setHoveredNodeId] = useState<string | null>(null);
  const [activeLayer, setActiveLayer] = useState<string | 'all'>('all');

  const { nodes, edges } = useMemo(() => {
    const graph = parseHclToGraph(code);
    const enrichedNodes = graph.nodes.map(node => {
        const nodeVulns = vulnerabilities.filter(v => 
          v.resource.includes(node.id) || 
          node.id.includes(v.resource) ||
          v.resource.includes(node.data.label)
        );
        return { 
          ...node, 
          status: nodeVulns.length > 0 ? 'risk' : 'healthy' as any,
          vulnerabilities: nodeVulns 
        };
    });
    return { nodes: enrichedNodes, edges: graph.edges };
  }, [code, vulnerabilities]);

  const affectedNodeIds = useMemo(() => {
    if (!selectedNodeId) return [];
    const affected = new Set<string>();
    const findDependents = (nodeId: string) => {
      edges.forEach(edge => {
        if (edge.source === nodeId && !affected.has(edge.target)) {
          affected.add(edge.target);
          findDependents(edge.target);
        }
      });
    };
    findDependents(selectedNodeId);
    return Array.from(affected);
  }, [selectedNodeId, edges]);

  const selectedNode = nodes.find(n => n.id === selectedNodeId) as (GraphNode & { vulnerabilities: Vulnerability[] }) | undefined;

  // Filtragem de nós baseada na camada ativa
  const visibleNodes = nodes.filter(n => activeLayer === 'all' || n.data.category === activeLayer);

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-1000 relative overflow-hidden">

      {/* 1. Glass Header with Actions */}
      <div className="flex justify-between items-center relative z-20">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-primary-500 shadow-[0_0_8px_#3b82f6]"></span>
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.25em]">Topology Reactor 2.0</span>
          </div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic text-glow">
            Infra <span className="text-primary-500">Universe</span>
          </h2>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl flex p-1 shadow-2xl">
            <LayerToggle active={activeLayer === 'all'} onClick={() => setActiveLayer('all')} icon={<Layers size={14}/>} label="Full" />
            <LayerToggle active={activeLayer === 'compute'} onClick={() => setActiveLayer('compute')} icon={<Cpu size={14}/>} label="Compute" />
            <LayerToggle active={activeLayer === 'network'} onClick={() => setActiveLayer('network')} icon={<Globe size={14}/>} label="Net" />
            <LayerToggle active={activeLayer === 'storage'} onClick={() => setActiveLayer('storage')} icon={<Database size={14}/>} label="Data" />
          </div>
          <button className="p-3 bg-white/5 hover:bg-white/10 rounded-xl text-slate-500 transition-all border border-white/5">
            <Share2 size={18} />
          </button>
        </div>
      </div>

      {/* 2. MAIN GRAPH CANVAS */}
      <div 
        className="flex-1 bg-[#020617] border border-white/5 rounded-[64px] relative overflow-hidden flex items-center justify-center shadow-inner cursor-grab active:cursor-grabbing"
        onClick={() => setSelectedNodeId(null)}
      >
        {/* Animated Background Grid */}
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute inset-0 opacity-[0.03]" style={{ 
            backgroundImage: 'linear-gradient(#fff 1px, transparent 1px), linear-gradient(90deg, #fff 1px, transparent 1px)', 
            backgroundSize: '40px 40px' 
          }}></div>
          <div className="absolute inset-0 bg-radial-at-c from-primary-900/10 via-transparent to-transparent"></div>
        </div>

        {visibleNodes.length === 0 ? (
          <div className="text-slate-500 flex flex-col items-center animate-pulse">
             <Layers size={64} className="text-slate-800 mb-4" />
             <p className="font-black text-slate-700 uppercase tracking-[0.3em] text-[10px]">No resources in this layer</p>
          </div>
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 1000 650" className="w-full h-full relative z-10 select-none">
            <defs>
              <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="6" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
              <linearGradient id="conn-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.1" />
                <stop offset="100%" stopColor="#3b82f6" stopOpacity="0.8" />
              </linearGradient>
              <marker id="arrowhead-mod" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                <polygon points="0 0, 10 3.5, 0 7" fill="#334155" />
              </marker>
            </defs>

            {/* Edges Layer */}
            <g>
              {edges.map(edge => {
                const sourceNode = nodes.find(n => n.id === edge.source);
                const targetNode = nodes.find(n => n.id === edge.target);
                if (!sourceNode || !targetNode) return null;

                const isSelectedPath = selectedNodeId === edge.source || selectedNodeId === edge.target;
                const isBlastRadiusPath = affectedNodeIds.includes(edge.target) && (selectedNodeId === edge.source || affectedNodeIds.includes(edge.source));

                return (
                  <g key={edge.id} className="transition-all duration-700">
                    <path 
                      d={`M ${sourceNode.position.x} ${sourceNode.position.y} L ${targetNode.position.x} ${targetNode.position.y}`}
                      stroke={isSelectedPath ? "#3b82f6" : isBlastRadiusPath ? "#ef4444" : "#1e293b"}
                      strokeWidth={isSelectedPath || isBlastRadiusPath ? 3 : 1.5}
                      strokeOpacity={isSelectedPath || isBlastRadiusPath ? 1 : 0.4}
                      fill="none"
                      markerEnd="url(#arrowhead-mod)"
                    />
                    {(isSelectedPath || isBlastRadiusPath) && (
                      <circle r="2" fill={isBlastRadiusPath ? "#ef4444" : "#60a5fa"}>
                        <animateMotion 
                          dur="1.5s" 
                          repeatCount="indefinite" 
                          path={`M ${sourceNode.position.x} ${sourceNode.position.y} L ${targetNode.position.x} ${targetNode.position.y}`} 
                        />
                      </circle>
                    )}
                  </g>
                );
              })}
            </g>

            {/* Nodes Layer */}
            {visibleNodes.map(node => {
              const isSelected = selectedNodeId === node.id;
              const isAffected = affectedNodeIds.includes(node.id);
              const isDimmed = selectedNodeId && !isSelected && !isAffected;
              const category = node.data.category;
              const baseColor = node.status === 'risk' ? '#ef4444' : getCategoryHex(category);

              return (
                <g 
                  key={node.id} 
                  transform={`translate(${node.position.x}, ${node.position.y})`}
                  className={`transition-all duration-500 cursor-pointer ${isDimmed ? 'opacity-20 scale-90' : 'opacity-100 scale-100'}`}
                  onClick={(e) => { e.stopPropagation(); setSelectedNodeId(node.id); }}
                  onMouseEnter={() => setHoveredNodeId(node.id)}
                  onMouseLeave={() => setHoveredNodeId(null)}
                >
                  {/* Outer Rings */}
                  {node.status === 'risk' && (
                    <circle r="45" fill="none" stroke="#ef4444" strokeWidth="1.5" strokeDasharray="4 8" className="animate-[spin_10s_linear_infinite]" />
                  )}
                  {isSelected && (
                    <circle r="50" fill="none" stroke="#3b82f6" strokeWidth="2" strokeDasharray="2 4" className="animate-[spin_4s_linear_infinite]" />
                  )}

                  {/* Node Body */}
                  <rect 
                    x="-32" y="-32" width="64" height="64" rx="16"
                    fill={isSelected ? "#1e293b" : "#0f172a"}
                    stroke={isSelected ? "#3b82f6" : isAffected ? "#f59e0b" : baseColor}
                    strokeWidth={isSelected || isAffected ? 3 : 2}
                    className="transition-all hover:stroke-white shadow-2xl"
                  />

                  {/* Icon Area */}
                  <g transform="translate(-10, -10)">
                    {getCategoryIcon(category, 20, isSelected ? '#fff' : baseColor)}
                  </g>

                  {/* Labels */}
                  <g transform="translate(0, 52)">
                    <text textAnchor="middle" fill="white" fontSize="10" fontWeight="900" className="uppercase tracking-widest text-glow">{node.data.label}</text>
                    <text y="14" textAnchor="middle" fill="#475569" fontSize="7" fontWeight="black" className="uppercase tracking-[0.2em]">{node.data.resource_type}</text>
                  </g>

                  {/* Severity Badge */}
                  {node.status === 'risk' && (
                    <g transform="translate(25, -25)">
                      <circle r="10" fill="#ef4444" />
                      <path d="M0 -4 L0 1 M0 3 L0 3" stroke="white" strokeWidth="2" strokeLinecap="round" />
                    </g>
                  )}
                </g>
              );
            })}
          </svg>
        )}

        {/* Floating Legends */}
        <div className="absolute top-10 left-10 bg-slate-900/60 backdrop-blur-xl p-6 rounded-[32px] border border-white/5 shadow-2xl space-y-4">
            <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
              <Info size={12}/> Reactor Intelligence
            </h4>
            <div className="space-y-3">
                <LegendRow color="#a855f7" label="Compute Core" />
                <LegendRow color="#3b82f6" label="Network Fabric" />
                <LegendRow color="#eab308" label="Data Persistence" />
                <div className="h-px bg-white/5 my-2"></div>
                <div className="flex items-center gap-3">
                  <div className="w-2.5 h-2.5 rounded-full bg-red-500 animate-pulse"></div>
                  <span className="text-[9px] font-black text-white uppercase tracking-widest">Active Risk Engine</span>
                </div>
            </div>
        </div>

        {/* BLAST RADIUS PANEL */}
        {selectedNode && (
          <aside 
            className="absolute top-0 right-0 h-full w-96 bg-slate-950/80 backdrop-blur-3xl border-l border-white/5 shadow-[-40px_0_60px_rgba(0,0,0,0.5)] z-30 animate-in slide-in-from-right duration-700 flex flex-col" 
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-10 border-b border-white/5 space-y-6">
              <div className="flex justify-between items-start">
                <div className={`p-4 rounded-3xl ${selectedNode.status === 'risk' ? 'bg-red-500/10 text-red-500 border border-red-500/20' : 'bg-primary-500/10 text-primary-500 border border-primary-500/10'}`}>
                  {getCategoryIcon(selectedNode.data.category, 32)}
                </div>
                <button onClick={() => setSelectedNodeId(null)} className="p-3 hover:bg-white/5 rounded-2xl text-slate-600 hover:text-white transition-all">
                  <X size={24} />
                </button>
              </div>
              <div className="space-y-1">
                <h3 className="text-3xl font-black text-white tracking-tighter uppercase italic">{selectedNode.data.label}</h3>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-primary-500 font-black uppercase tracking-widest">{selectedNode.data.resource_type}</span>
                  <span className="text-slate-700">•</span>
                  <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Production Subnet</span>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
              {/* Health Score Component */}
              <section className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resource Health</h4>
                <div className="flex items-end gap-3">
                  <span className={`text-5xl font-black ${selectedNode.status === 'risk' ? 'text-red-500' : 'text-emerald-500'}`}>
                    {selectedNode.status === 'risk' ? '35' : '100'}
                  </span>
                  <span className="text-slate-600 font-bold mb-1">/100</span>
                </div>
              </section>

              {/* Blast Radius Impact Analysis */}
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Target size={14} className="text-red-500" /> Blast Radius Analysis
                  </h4>
                  <span className="text-[10px] font-black text-white bg-red-500/20 px-2 py-0.5 rounded border border-red-500/20">Impact Level: High</span>
                </div>
                <div className="bg-slate-900/50 border border-white/5 rounded-[32px] p-6 space-y-5">
                  <p className="text-xs text-slate-400 leading-relaxed font-medium italic">
                    "Uma falha crítica neste nó comprometerá a integridade de <span className="text-white font-black underline">{affectedNodeIds.length} recursos dependentes</span>."
                  </p>
                  <div className="space-y-2">
                    {affectedNodeIds.slice(0, 3).map(id => (
                      <div key={id} className="flex items-center justify-between text-[10px] text-slate-400 group/item">
                        <div className="flex items-center gap-2">
                          <Activity size={12} className="text-red-500/50" />
                          <span className="font-mono">{id}</span>
                        </div>
                        <ArrowUpRight size={12} className="opacity-0 group-hover/item:opacity-100 transition-opacity" />
                      </div>
                    ))}
                    {affectedNodeIds.length > 3 && (
                      <button className="text-[9px] font-black text-primary-500 uppercase mt-2 tracking-widest">+ {affectedNodeIds.length - 3} mais recursos afetados</button>
                    )}
                  </div>
                </div>
              </section>

              {/* Security Findings */}
              {selectedNode.vulnerabilities.length > 0 && (
                <section className="space-y-4">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Findings</h4>
                  <div className="space-y-3">
                    {selectedNode.vulnerabilities.map(v => (
                      <div key={v.id} className="neo-card rounded-3xl p-5 border border-red-500/10 group hover:border-red-500/40 transition-all">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-[9px] font-black text-red-500 uppercase tracking-widest">{v.severity}</span>
                          <span className="text-[9px] text-slate-600 font-mono">#{v.ruleId}</span>
                        </div>
                        <p className="text-xs font-bold text-white leading-tight mb-2">{v.title}</p>
                        <p className="text-[10px] text-slate-500 line-clamp-2">{v.description}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}
            </div>

            <div className="p-10 border-t border-white/5 flex gap-3 bg-slate-900/40">
              <button className="flex-1 py-4 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 flex items-center justify-center gap-2">
                Isolation Plan <Shield size={14} />
              </button>
              <button className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5 text-slate-400">
                <Maximize2 size={16} />
              </button>
            </div>
          </aside>
        )}
      </div>
    </div>
  );
};

