    <div className="w-64 h-[calc(100vh-2rem)] m-4 bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-[32px] flex flex-col fixed left-0 top-0 z-50 shadow-2xl">
      <div className="p-8 flex items-center gap-3">
        <div className="p-2 bg-primary-600 rounded-xl shadow-[0_0_15px_rgba(37,99,235,0.4)]">
          <Shield className="text-white" size={20} />
        </div>
        <h1 className="text-lg font-black text-white tracking-tighter uppercase italic">Guardian</h1>
      </div>

      <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
        {filteredItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`w-full flex items-center justify-between group px-4 py-3 rounded-2xl transition-all duration-300 ${
                isActive
                  ? 'bg-white/5 text-white border border-white/10 shadow-lg'
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/[0.02]'
              }`}
            >
              <div className="flex items-center gap-3">
                <Icon size={18} className={isActive ? 'text-primary-400' : 'text-slate-600 group-hover:text-slate-400'} />
                <span className="font-bold text-[11px] uppercase tracking-widest">{item.label}</span>
              </div>
              {isActive && <div className="w-1 h-1 rounded-full bg-primary-500 shadow-[0_0_8px_#3b82f6]"></div>}
            </button>
          );
        })}
      </nav>

      <div className="p-6 mt-auto border-t border-white/5 space-y-4">
        <div className="flex items-center gap-3 px-2">
          <div className="relative">
            <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-primary-600 to-indigo-700 flex items-center justify-center text-xs font-black shadow-xl">
              {isAuditorMode ? 'AU' : 'JD'}
            </div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-4 border-slate-900 rounded-full"></div>
          </div>
          <div className="flex flex-col min-w-0">
            <span className="text-[11px] font-black text-white truncate uppercase tracking-tight">
