      const initial: Project[] = [
        { id: 'proj-1', name: 'Infrastructure-Prod', cloud: 'AWS', region: 'us-east-1', status: 'active', lastScan: new Date().toISOString(), score: 85 },
        { id: 'proj-2', name: 'Legacy-Backend', cloud: 'Azure', region: 'us-east-1', status: 'active', lastScan: new Date().toISOString(), score: 42 }
      ];
      localStorage.setItem('cg_projects', JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(saved);
  },

  async saveProject(project: Project) {
    const projects = await this.getProjects();
    const index = projects.findIndex(p => p.id === project.id);
    if (index > -1) projects[index] = project;
    else projects.push(project);
    localStorage.setItem('cg_projects', JSON.stringify(projects));
  },

  // Member Management
  async getMembers(): Promise<OrgMember[]> {
    const saved = localStorage.getItem('cg_members');
    if (!saved) {
      const initial: OrgMember[] = [
        { id: 'mem-1', name: 'John Doe', email: 'admin@cloudguardian.ai', role: 'admin', lastActive: 'Online Agora' },
        { id: 'mem-2', name: 'Jane Smith', email: 'jane@cloudguardian.ai', role: 'editor', lastActive: '2h atrás' }
      ];
      localStorage.setItem('cg_members', JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(saved);
  },

  async addMember(member: OrgMember) {
    const members = await this.getMembers();
    members.push(member);
    localStorage.setItem('cg_members', JSON.stringify(members));
  }
};

