import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, Project, OrgMember, SecurityScore, Severity, ScanStatus, Policy, PipelineRun, DriftItem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  // --- Subscription & Billing ---
  async getSubscriptionStatus() {
    return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' });
  }

  async upgradeToPro(isPro: boolean) {
    await new Promise(r => setTimeout(r, 1000));
    const tier = isPro ? 'pro' : 'team';
    const newSub = { tier, expires: '2026-12-31', currency: 'USD' };
    this.db.set('subscription', newSub);

    await this.logEvent({
      type: 'ORG',
      title: 'Global Plan Updated',
      description: `The workspace was successfully upgraded to ${tier.toUpperCase()} plan.`,
      severity: Severity.LOW
    });

    return newSub;
  }

  // --- Drift Management ---
  async fetchCloudDrifts(): Promise<DriftItem[]> {
    await new Promise(r => setTimeout(r, LATENCY));
    const current = this.db.get('drifts');
    if (current.length === 0) {
      const initial: DriftItem[] = [
        { id: 'drift-1', resource: 'aws_s3_bucket.prod_assets', property: 'acl', terraformValue: 'private', cloudValue: 'public-read', severity: Severity.CRITICAL },
        { id: 'drift-2', resource: 'aws_security_group.db_sg', property: 'ingress', terraformValue: 'port 5432: 10.0.0.0/16', cloudValue: 'port 5432: 0.0.0.0/0', severity: Severity.HIGH }
      ];
      this.db.set('drifts', initial);
      return initial;
    }
    return current;
  }

  async resolveDrift(id: string) {
    await new Promise(r => setTimeout(r, 1500));
    const current = this.db.get('drifts');
    const filtered = current.filter((d: DriftItem) => d.id !== id);
    this.db.set('drifts', filtered);

    await this.logEvent({
      type: 'DRIFT',
      title: 'Cloud Drift Resolved',
      description: `Resource sync completed. Infrastructure is now consistent globally.`,
      severity: Severity.LOW
    });
    return true;
  }

  // --- Security Engine ---
  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));

    const model = 'gemini-3-pro-preview';
    const systemPrompt = `Analyze Terraform HCL for security. Return JSON with 'findings' array. 
    Findings must include:
    - ruleId, title, severity (CRITICAL/HIGH/MEDIUM/LOW), resource, description, remediation
    - type: 'security' or 'finops'
    - complianceMapping: Array (SOC2, ISO, CIS_BENCHMARK, GDPR, HIPAA)
    Always prioritize CIS Benchmarks.`;

    let findings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: `${systemPrompt}\n\nCode:\n${code}`,
        config: { 
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 4000 } // Enable reasoning for complex security analysis
        }
      });
      const data = JSON.parse(response.text || '{}');
      findings = data.findings || [];
    } catch (e) {
      console.error("AI Analysis Failed", e);
      // Fallback for demo if API fails
      findings = [{
        ruleId: 'SEC-001',
        title: 'Public S3 Bucket Detected',
        severity: Severity.CRITICAL,
        resource: 'aws_s3_bucket.data',
        description: 'Bucket allows public-read access.',
        remediation: 'Change acl to private.',
        complianceMapping: ['SOC2_CC6.6']
      }];
    }

    const vulns: Vulnerability[] = findings.map((f, i) => ({
      ...f,
      id: `vuln-${Date.now()}-${i}`,
      status: ScanStatus.OPEN
    }));

    const score = this.calculateScore(vulns, this.db.get('drifts'));

    // Persist scan history
    const history = this.db.get('scan_history');
    this.db.set('scan_history', [{ id: Date.now(), timestamp: new Date(), vulnsCount: vulns.length, score: score.total }, ...history].slice(0, 20));
    this.db.set('vulnerabilities', vulns);

    return { vulns, score };
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const criticals = vulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = vulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;

    const infraBase = Math.max(0, 100 - (criticals * 15) - (highs * 8));
    const complianceBase = Math.max(0, infraBase - 5);

    return {
      total: infraBase,
      infrastructure: infraBase,
      secrets: 100,
      compliance: complianceBase,
      drift: drifts.length === 0 ? 100 : 70,
      finops: 100,
      trend: infraBase > 80 ? 1.5 : -0.5
    };
  }

  async getVulnerabilities(): Promise<Vulnerability[]> {
    return this.db.get('vulnerabilities');
  }

  async setVulnerabilities(vulns: Vulnerability[]) {
    this.db.set('vulnerabilities', vulns);
  }

  async getScanHistory() {
    return this.db.get('scan_history');
  }

  async getPolicies(): Promise<Policy[]> {
    const saved = this.db.get('policies');
    if (saved.length === 0) {
      const initial: Policy[] = [
        { id: 'p1', name: 'Encryption at Rest', description: 'All S3 buckets must have AES256 encryption.', framework: 'SOC2', severity: Severity.HIGH, status: 'active' },
        { id: 'p2', name: 'No Default VPC', description: 'Default VPCs are prohibited in production.', framework: 'CIS', severity: Severity.MEDIUM, status: 'active' }
      ];
      this.db.set('policies', initial);
      return initial;
    }
    return saved;
  }

  async getTimeline(): Promise<TimelineEvent[]> {
    return this.db.get('timeline');
  }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }

  async getSystemSettings() {
    return this.db.getSingle('settings', {
      accessKeyId: 'AKIA****************42',
      region: 'us-east-1',
      notifications: { autoFix: true, driftSync: false, soc2Logging: true },
      webhooks: { slack: 'https://hooks.slack.com/services/...' }
    });
  }

  async saveSystemSettings(settings: any) {
    this.db.set('settings', settings);
    return true;
  }
}

