export const AIAssistant: React.FC<{ code: string }> = ({ code }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: 'Hello! I am the CloudGuardian Copilot. How can I assist with your infrastructure security today?' }
  ]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Terraform HCL Context:\n${code}\n\nUser Question: ${userMsg}`,
        config: {
          systemInstruction: "You are the CloudGuardian AI Copilot, an expert in DevSecOps and cloud security (AWS/Azure/GCP). Provide concise, technical, and actionable security advice. Use markdown for code blocks.",
        }
      });

      const text = response.text || "I encountered an issue processing that request. Please try again.";
      setMessages(prev => [...prev, { role: 'assistant', content: text }]);
    } catch (error) {
      console.error("AI Assistant Error:", error);
      setMessages(prev => [...prev, { role: 'assistant', content: "Unable to reach the AI reasoning engine. Check your connection." }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 w-14 h-14 bg-primary-600 hover:bg-primary-700 text-white rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-110 active:scale-95 z-[90] border border-primary-400/30"
      >
        <Sparkles size={24} className="animate-pulse" />
      </button>

      {isOpen && (
        <div className="fixed bottom-24 right-6 w-96 h-[520px] bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-[32px] shadow-[0_20px_80px_rgba(0,0,0,0.7)] flex flex-col z-[95] animate-in slide-in-from-bottom-10 duration-300 overflow-hidden">
          <header className="p-4 bg-slate-800/80 border-b border-white/5 flex justify-between items-center">
            <div className="flex items-center gap-2">
              <Bot className="text-primary-400" size={20} />
              <span className="font-black text-[10px] text-white uppercase tracking-widest">Security Copilot</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white transition-colors p-1"><X size={18} /></button>
          </header>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-xs leading-relaxed ${
                  msg.role === 'user' 
                  ? 'bg-primary-600 text-white rounded-tr-none shadow-lg' 
                  : 'bg-slate-800/60 text-slate-300 rounded-tl-none border border-white/5'
                }`}>
                  {msg.content}
                </div>
              </div>
            ))}
            {loading && (
              <div className="flex justify-start">
                <div className="bg-slate-800 p-4 rounded-2xl rounded-tl-none border border-white/5 flex items-center gap-2">
                  <Loader2 className="animate-spin text-primary-500" size={14} />
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Reasoning...</span>
                </div>
              </div>
            )}
          </div>

          <form onSubmit={handleSendMessage} className="p-4 bg-slate-900/80 border-t border-white/5">
            <div className="relative">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask about your infrastructure security..."
                className="w-full bg-slate-950/80 border border-white/10 rounded-2xl py-3 px-5 pr-12 text-xs text-white placeholder:text-slate-600 focus:outline-none focus:border-primary-500 transition-all shadow-inner"
              />
              <button type="submit" disabled={!input.trim()} className="absolute right-3 top-1/2 -translate-y-1/2 text-primary-500 hover:text-primary-400 disabled:opacity-30 p-1 transition-colors">
                <Send size={18} />
              </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getSubscriptionStatus() {
    return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' });
  }

  async fetchCloudDrifts(): Promise<DriftItem[]> {
    await new Promise(r => setTimeout(r, LATENCY));
    const current = this.db.get('drifts');
    if (!current || current.length === 0) {
      const initial: DriftItem[] = [
        { id: 'drift-1', resource: 'aws_s3_bucket.prod_assets', property: 'acl', terraformValue: 'private', cloudValue: 'public-read', severity: Severity.CRITICAL },
        { id: 'drift-2', resource: 'aws_security_group.db_sg', property: 'ingress', terraformValue: 'port 5432: 10.0.0.0/16', cloudValue: 'port 5432: 0.0.0.0/0', severity: Severity.HIGH }
      ];
      this.db.set('drifts', initial);
      return initial;
    }
    return current;
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));
    const model = 'gemini-3-pro-preview';
    const systemPrompt = `You are a DevSecOps Expert. Analyze Terraform HCL. Return JSON { "findings": [...] }. 
    Each finding: ruleId, title, severity (CRITICAL/HIGH/MEDIUM/LOW), resource, description, remediation, type: "security"|"finops", complianceMapping: [SOC2, ISO].`;

    let findings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: `${systemPrompt}\n\nCode:\n${code}`,
        config: { 
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 2000 } 
        }
      });
      findings = JSON.parse(response.text || '{}').findings || [];
    } catch (e) {
      findings = [{
        ruleId: 'SEC-001', title: 'Public S3 Bucket', severity: Severity.CRITICAL,
        resource: 'aws_s3_bucket.data', description: 'Bucket is public.',
        remediation: 'Set acl to private.', type: 'security', complianceMapping: ['SOC2_CC6.1']
      }];
    }

    const vulns: Vulnerability[] = findings.map((f, i) => ({
      ...f, id: f.id || `v-${Date.now()}-${i}`, status: ScanStatus.OPEN
    }));

    const score = this.calculateScore(vulns, this.db.get('drifts'));
    this.db.set('vulnerabilities', vulns);
    return { vulns, score };
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const criticals = (vulns?.filter(v => v.severity === Severity.CRITICAL).length || 0) + 
                     (drifts?.filter(d => d.severity === Severity.CRITICAL).length || 0);
    const highs = (vulns?.filter(v => v.severity === Severity.HIGH).length || 0) + 
                  (drifts?.filter(d => d.severity === Severity.HIGH).length || 0);

    const infraBase = Math.max(0, 100 - (criticals * 15) - (highs * 8));
    return {
      total: infraBase,
      infrastructure: infraBase,
      secrets: 100,
      compliance: Math.max(0, infraBase - 5),
      drift: (!drifts || drifts.length === 0) ? 100 : 70,
      finops: 100,
      trend: infraBase > 80 ? 1.5 : -0.5
    };
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getScanHistory() { return this.db.get('scan_history'); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }

  async getSystemSettings() {
    return this.db.getSingle('settings', {
      accessKeyId: 'AKIA****************42', region: 'us-east-1',
      notifications: { autoFix: true, driftSync: false, soc2Logging: true }
    });
  }

  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async upgradeToPro(isPro: boolean) {
    const tier = isPro ? 'pro' : 'team';
    const sub = { tier, expires: '2026-12-31', currency: 'USD' };
    this.db.set('subscription', sub);
    return sub;
  }
}

