                  {f.type === 'finops' ? <DollarSign size={16}/> : (f.title.includes('S3') ? <Shield size={16}/> : <Globe size={16}/>)}
                </div>
                <div>
                   <h4 className="font-bold text-xs text-slate-200">{f.title}</h4>
                   <p className="text-[9px] text-slate-500 font-mono uppercase">{f.resource}</p>
                </div>
              </div>
              {expandedId === f.id ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
            </div>
            {expandedId === f.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-800/50 space-y-4 bg-slate-950/20">
                <p className="text-xs text-slate-400 italic">"{f.description}"</p>
                <div className="flex flex-wrap gap-2">
                   {f.complianceMapping?.map(c => <span key={c} className="text-[8px] font-black text-emerald-400 bg-emerald-500/5 px-2 py-0.5 rounded border border-emerald-500/10">{c}</span>)}
                   {f.type === 'finops' && <span className="text-[8px] font-black text-primary-400 bg-primary-500/5 px-2 py-0.5 rounded border border-primary-500/10">COST_OPTIMIZATION</span>}
                </div>
                {!aiFix[f.id] ? (
                  <button onClick={() => handleGenerateFix(f)} disabled={loadingFix === f.id} className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest border border-slate-700 transition-all active:scale-95">
                    {loadingFix === f.id ? <Loader2 className="animate-spin" size={14}/> : <Zap size={14} className="text-amber-400"/>}
                    {loadingFix === f.id ? 'Analisando...' : 'Gerar Remediação IA'}
                  </button>
                ) : (
                  <div className="space-y-3 animate-in fade-in">
                    <DiffViewer 
                      original={codeContext.split('\n').filter(l => l.includes(f.resource.split('.')[1])).join('\n') || '/* Lógica do Recurso Original */'} 
                      fixed={aiFix[f.id].replace(/```(hcl|terraform)?\n?|\n?```/g, '')} 
                    />
                    <button onClick={() => handleFixAndCommit(f)} disabled={committing === f.id} className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest shadow-lg shadow-emerald-900/30 transition-all active:scale-95">
                      {committing === f.id ? <Loader2 className="animate-spin" size={16}/> : <GitPullRequest size={16}/>}
                      {committing === f.id ? 'Criando Pull Request...' : 'Aplicar Correção IA'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { AIAssistant } from './components/AIAssistant';
import { LiveAssistant } from './components/LiveAssistant';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { FinOps } from './pages/FinOps';
import { Roadmap } from './pages/Roadmap';
import { Organization } from './pages/Organization';
import { SecurityTesting } from './pages/SecurityTesting';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun } from './types';
import { API } from './services/backend';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read" # ALERTA: Bucket Público!
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # ALERTA: SSH aberto para o mundo!
  }
}

resource "aws_db_instance" "mysql_db" {
  allocated_storage    = 20
  engine               = "mysql"
  instance_class       = "db.t2.micro"
  name                 = "production_db"
  username             = "admin"
  password             = "P@ssword123!" # ALERTA: Senha em texto plano!
  publicly_accessible  = true           # ALERTA: DB acessível via Internet!
  skip_final_snapshot  = true
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);

  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([]);

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    if (isAuthenticated) {
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  const loadInitialData = async () => {
    try {
      const [timeline, initialPolicies, initialVulns, initialDrifts] = await Promise.all([
        API.getTimeline(), API.getPolicies(), API.getVulnerabilities(), API.fetchCloudDrifts()
      ]);
      setTimelineEvents(timeline || []);
      setPolicies(initialPolicies || []);
      setVulnerabilities(initialVulns || []);
      setDrifts(initialDrifts || []);
      setIsInitializing(false);
    } catch (e) { 
      setIsInitializing(false); 
    }
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    API.logEvent({ type: 'SCAN', title: 'Sessão Iniciada', description: 'Usuário logado no Global Console.' });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
    setShowLogin(false);
    setCurrentView('dashboard');
  };

  const onScanFinished = (vulns: Vulnerability[]) => {
    setVulnerabilities(vulns);
    showNotification(`Scan concluído: ${vulns.length} riscos encontrados.`);
    API.logEvent({
      type: 'RISK', title: 'Scan Realizado',
      description: `Motor de IA analisou main.tf e encontrou ${vulns.length} problemas críticos de conformidade.`,
      severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW
    }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
  };

  const handleApplyFix = async (id: string, newSnippet: string) => {
    const updatedVulns = vulnerabilities.filter(v => v.id !== id);
    setVulnerabilities(updatedVulns);
    await API.setVulnerabilities(updatedVulns);

    showNotification("Remediação aplicada com sucesso!", "success");
    const evt = await API.logEvent({
      type: 'PR', title: 'Risco Mitigado',
      description: `A vulnerabilidade ${id} foi corrigida via Patch Automático CloudGuardian.`
    });
    setTimelineEvents(prev => [evt, ...prev]);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
        <Loader2 className="text-primary-500 animate-spin" size={64} />
        <span className="text-slate-500 font-black uppercase text-[10px] tracking-[0.4em] animate-pulse">Iniciando CloudGuardian Core...</span>
      </div>
    );
  }

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <Sidebar currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout} isAuditorMode={isAuditorMode} />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
        />
        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 duration-300 border backdrop-blur-md bg-slate-900 border-slate-700">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-sm font-bold uppercase tracking-tight">{toast.message}</span>
            <button onClick={() => setToast(null)}><X size={14} /></button>
          </div>
        )}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={onScanFinished} vulnerabilities={vulnerabilities} onApplyFix={handleApplyFix} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'security-tests' && <SecurityTesting />}
        </div>
        {isLiveAssistantOpen && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveAssistantOpen(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getSubscriptionStatus() {
    return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' });
  }

  async fetchCloudDrifts(): Promise<DriftItem[]> {
    await new Promise(r => setTimeout(r, LATENCY));
    const current = this.db.get('drifts');
    if (!current || current.length === 0) {
      const initial: DriftItem[] = [
        { id: 'drift-1', resource: 'aws_s3_bucket.prod_assets', property: 'acl', terraformValue: 'private', cloudValue: 'public-read', severity: Severity.CRITICAL },
        { id: 'drift-2', resource: 'aws_security_group.db_sg', property: 'ingress', terraformValue: 'port 5432: 10.0.0.0/16', cloudValue: 'port 5432: 0.0.0.0/0', severity: Severity.HIGH }
      ];
      this.db.set('drifts', initial);
      return initial;
    }
    return current;
  }

  async resolveDrift(id: string) {
    await new Promise(r => setTimeout(r, LATENCY));
    const drifts = this.db.get('drifts');
    const updated = drifts.filter((d: DriftItem) => d.id !== id);
    this.db.set('drifts', updated);

    await this.logEvent({
      type: 'DRIFT',
      title: 'Recurso Sincronizado',
      description: `O drift no recurso ${id} foi mitigado via aplicação de estado desejado.`,
      severity: Severity.LOW
    });
    return true;
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));
    const model = 'gemini-3-pro-preview';
    const systemPrompt = `You are an elite DevSecOps Security Architect.
    Analyze the provided Terraform HCL for security vulnerabilities, secret exposures, and compliance (SOC2, ISO27001, CIS).

    Return a strictly valid JSON response: { "findings": [...] }.
    Each finding: 
    - ruleId: e.g., CIS-AWS-1.2
    - title: brief and descriptive
    - severity: CRITICAL, HIGH, MEDIUM, or LOW
    - resource: the terraform resource name
    - description: clear risk explanation
    - remediation: actionable fix
    - type: "security" or "finops"
    - complianceMapping: string array of frameworks (e.g., ["SOC2_CC6.6", "ISO27001_A.10"])`;

    let findings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: `${systemPrompt}\n\nTerraform Code:\n${code}`,
        config: { 
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 2000 } 
        }
      });
      findings = JSON.parse(response.text || '{}').findings || [];
    } catch (e) {
      // Robust fallback for the test if AI service fails
      findings = [
        {
          ruleId: 'SEC-001', title: 'Bucket S3 Público Detectado', severity: Severity.CRITICAL,
          resource: 'aws_s3_bucket.prod_assets', description: 'O bucket permite leitura pública de dados sensíveis.',
          remediation: 'Mude acl para "private" e ative block_public_access.', type: 'security', complianceMapping: ['SOC2_CC6.1']
        },
        {
          ruleId: 'SEC-002', title: 'Porta SSH Aberta Globalmente', severity: Severity.HIGH,
          resource: 'aws_security_group.ssh_access', description: 'Porta 22 aberta para 0.0.0.0/0 facilita ataques de força bruta.',
          remediation: 'Restrinja o acesso SSH a IPs conhecidos da VPN corporativa.', type: 'security', complianceMapping: ['SOC2_CC6.6']
        },
        {
          ruleId: 'SEC-003', title: 'Credenciais Expostas no Código', severity: Severity.CRITICAL,
          resource: 'aws_db_instance.mysql_db', description: 'Senhas em texto plano no Terraform podem ser vazadas via Git history.',
          remediation: 'Utilize AWS Secrets Manager ou variáveis de ambiente seguras.', type: 'security', complianceMapping: ['ISO27001_A.10']
        }
      ];
    }

    const vulns: Vulnerability[] = findings.map((f, i) => ({
      ...f, id: f.id || `v-${Date.now()}-${i}`, status: ScanStatus.OPEN
    }));

    const score = this.calculateScore(vulns, this.db.get('drifts'));
    this.db.set('vulnerabilities', vulns);

    const history = this.db.get('scan_history');
    this.db.set('scan_history', [{ id: Date.now(), timestamp: new Date(), score: score.total }, ...history].slice(0, 10));

    return { vulns, score };
  }

  async suggestFix(vulnerability: string, codeContext: string) {
    const model = 'gemini-3-pro-preview';
    const prompt = `
      You are a specialized Terraform security refactoring engine.
      Provide the corrected Terraform HCL code snippet to fix: "${vulnerability}".
      Context: 
      \`\`\`hcl
      ${codeContext}
      \`\`\`
      Return ONLY the plain HCL code. No markdown blocks, no explanations. 
      Ensure the fix uses current best practices (e.g., using variables for passwords or restricting access).
    `;
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
      });
      return response.text;
    } catch (e) {
      return "/* Erro ao gerar correção via IA. Tente novamente em instantes. */";
    }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const criticals = (vulns?.filter(v => v.severity === Severity.CRITICAL).length || 0) + 
                     (drifts?.filter(d => d.severity === Severity.CRITICAL).length || 0);
    const highs = (vulns?.filter(v => v.severity === Severity.HIGH).length || 0) + 
                  (drifts?.filter(d => d.severity === Severity.HIGH).length || 0);

    const infraBase = Math.max(0, 100 - (criticals * 15) - (highs * 8));
    return {
      total: infraBase,
      infrastructure: infraBase,
      secrets: vulns?.some(v => v.ruleId.includes('SEC-003') || v.title.toLowerCase().includes('secret')) ? 30 : 100,
      compliance: Math.max(0, infraBase - 5),
      drift: (!drifts || drifts.length === 0) ? 100 : 70,
      finops: 100,
      trend: infraBase > 80 ? 1.5 : -0.5
    };
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getScanHistory() { return this.db.get('scan_history'); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }

  async getSystemSettings() {
    return this.db.getSingle('settings', {
      accessKeyId: 'AKIA****************42', region: 'us-east-1',
      notifications: { autoFix: true, driftSync: false, soc2Logging: true }
    });
  }

  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async upgradeToPro(isPro: boolean) {
    const tier = isPro ? 'pro' : 'team';
    const sub = { tier, expires: '2026-12-31', currency: 'USD' };
    this.db.set('subscription', sub);
    return sub;
  }
}

export const API = new CloudGuardianBackend();

import React, { useState, useMemo } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2, Shield, Lock, Zap, Target, Globe, Layers, DollarSign, ArrowRight } from 'lucide-react';
import { API } from '../services/backend';
import { DiffViewer } from './DiffViewer';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
  onApplyFix: (id: string, code: string) => void;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext, onApplyFix }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committing, setCommitting] = useState<string | null>(null);

  const stats = useMemo(() => ({
    critical: findings.filter(f => f.severity === Severity.CRITICAL).length,
    high: findings.filter(f => f.severity === Severity.HIGH).length,
    finops: findings.filter(f => f.type === 'finops').length,
    total: findings.length
  }), [findings]);

  const handleGenerateFix = async (vuln: Vulnerability) => {
    setLoadingFix(vuln.id);
    try {
        const fix = await API.suggestFix(vuln.title, codeContext);
        // Clean markdown backticks if AI returns them
        const cleanFix = fix ? fix.replace(/```(hcl|terraform)?\n?|\n?```/g, '').trim() : "/* Erro ao gerar sugestão */";
        setAiFix(prev => ({ ...prev, [vuln.id]: cleanFix }));
    } catch (e) { 
        setAiFix(prev => ({ ...prev, [vuln.id]: "/* Erro crítico na comunicação com o motor de IA */" })); 
    }
    setLoadingFix(null);
  };

  const handleFixAndCommit = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    // Simulate commit and PR creation latency
    setTimeout(() => {
        onApplyFix(vuln.id, aiFix[vuln.id] || '');
        setCommitting(null);
        setExpandedId(null);
    }, 1800);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        <div className="flex justify-between items-center mb-4 text-[10px] font-black uppercase tracking-widest text-slate-500">
           <span>Resultados do Scan</span>
           <span className="text-primary-400">{stats.total} Achados</span>
        </div>
        <div className="grid grid-cols-3 gap-3">
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-red-500/10">
              <div className="text-xl font-black text-red-500">{stats.critical}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Críticos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-orange-500/10">
              <div className="text-xl font-black text-orange-500">{stats.high}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Altos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-emerald-500/10">
              <div className="text-xl font-black text-emerald-500">{stats.finops}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">FinOps</div>
           </div>
        </div>
      </div>

      <div className="space-y-3">
        {findings.map((f) => (
          <div key={f.id} className={`bg-slate-900 rounded-2xl border transition-all ${expandedId === f.id ? 'border-primary-500 shadow-2xl bg-slate-900' : 'border-slate-800 hover:border-slate-700 bg-slate-900/40'}`}>
            <div className="p-4 flex items-center justify-between cursor-pointer" onClick={() => setExpandedId(expandedId === f.id ? null : f.id)}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg border ${f.type === 'finops' ? 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20' : (f.severity === Severity.CRITICAL ? 'text-red-500 bg-red-500/10 border-red-500/20' : 'text-orange-500 bg-orange-500/10 border-orange-500/20')}`}>
                  {f.type === 'finops' ? <DollarSign size={16}/> : (f.severity === Severity.CRITICAL ? <Shield size={16}/> : <Target size={16}/>)}
                </div>
                <div>
                   <h4 className="font-bold text-xs text-slate-200">{f.title}</h4>
                   <p className="text-[9px] text-slate-500 font-mono uppercase">{f.resource}</p>
                </div>
              </div>
              {expandedId === f.id ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
            </div>
            {expandedId === f.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-800/50 space-y-4 bg-slate-950/20">
                <p className="text-xs text-slate-400 italic">"{f.description}"</p>
                <div className="flex flex-wrap gap-2">
                   {f.complianceMapping?.map(c => <span key={c} className="text-[8px] font-black text-emerald-400 bg-emerald-500/5 px-2 py-0.5 rounded border border-emerald-500/10">{c}</span>)}
                   {f.type === 'finops' && <span className="text-[8px] font-black text-primary-400 bg-primary-500/5 px-2 py-0.5 rounded border border-primary-500/10">FINOPS_SAVING</span>}
                </div>
                {!aiFix[f.id] ? (
                  <button onClick={() => handleGenerateFix(f)} disabled={loadingFix === f.id} className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest border border-slate-700 transition-all active:scale-95">
                    {loadingFix === f.id ? <Loader2 className="animate-spin" size={14}/> : <Zap size={14} className="text-amber-400"/>}
                    {loadingFix === f.id ? 'Analisando...' : 'Gerar Remediação IA'}
                  </button>
                ) : (
                  <div className="space-y-3 animate-in fade-in">
                    <DiffViewer 
                      original={codeContext.split('\n').filter(l => l.includes(f.resource.split('.')[1])).join('\n') || '/* Código Original */'} 
                      fixed={aiFix[f.id]} 
                    />
                    <button onClick={() => handleFixAndCommit(f)} disabled={committing === f.id} className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest shadow-lg shadow-emerald-900/30 transition-all active:scale-95">
                      {committing === f.id ? <Loader2 className="animate-spin" size={16}/> : <GitPullRequest size={16}/>}
                      {committing === f.id ? 'Sincronizando...' : 'Aplicar Correção IA'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

