import React, { useState, useMemo } from 'react';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, ChevronDown, ChevronUp, Cpu, GitPullRequest, Loader2, Shield, Lock, Zap, Target, Globe, Layers, DollarSign, ArrowRight, Radar } from 'lucide-react';
import { API } from '../services/backend';
import { DiffViewer } from './DiffViewer';

interface ScanResultsProps {
  findings: Vulnerability[];
  codeContext: string;
  onApplyFix: (id: string, code: string) => void;
  onSimulateBlast?: (resourceId: string) => void;
}

export const ScanResults: React.FC<ScanResultsProps> = ({ findings, codeContext, onApplyFix, onSimulateBlast }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [aiFix, setAiFix] = useState<Record<string, string>>({});
  const [loadingFix, setLoadingFix] = useState<string | null>(null);
  const [committing, setCommitting] = useState<string | null>(null);

  const stats = useMemo(() => ({
    critical: findings.filter(f => f.severity === Severity.CRITICAL).length,
    high: findings.filter(f => f.severity === Severity.HIGH).length,
    finops: findings.filter(f => f.type === 'finops').length,
    total: findings.length
  }), [findings]);

  const handleGenerateFix = async (vuln: Vulnerability) => {
    setLoadingFix(vuln.id);
    try {
        const fix = await API.suggestFix(vuln.title, codeContext);
        const cleanFix = fix ? fix.replace(/```(hcl|terraform)?\n?|\n?```/g, '').trim() : "/* Erro ao gerar sugestão */";
        setAiFix(prev => ({ ...prev, [vuln.id]: cleanFix }));
    } catch (e) { 
        setAiFix(prev => ({ ...prev, [vuln.id]: "/* Erro crítico na comunicação com o motor de IA */" })); 
    }
    setLoadingFix(null);
  };

  const handleFixAndCommit = (vuln: Vulnerability) => {
    setCommitting(vuln.id);
    setTimeout(() => {
        onApplyFix(vuln.id, aiFix[vuln.id] || '');
        setCommitting(null);
        setExpandedId(null);
    }, 1800);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        <div className="flex justify-between items-center mb-4 text-[10px] font-black uppercase tracking-widest text-slate-500">
           <span>Resultados do Scan</span>
           <span className="text-primary-400">{stats.total} Achados</span>
        </div>
        <div className="grid grid-cols-3 gap-3">
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-red-500/10">
              <div className="text-xl font-black text-red-500">{stats.critical}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Críticos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-orange-500/10">
              <div className="text-xl font-black text-orange-500">{stats.high}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">Altos</div>
           </div>
           <div className="bg-slate-950 p-3 rounded-2xl text-center border border-emerald-500/10">
              <div className="text-xl font-black text-emerald-500">{stats.finops}</div>
              <div className="text-[8px] font-black text-slate-600 uppercase">FinOps</div>
           </div>
        </div>
      </div>

      <div className="space-y-3">
        {findings.map((f) => (
          <div key={f.id} className={`bg-slate-900 rounded-2xl border transition-all ${expandedId === f.id ? 'border-primary-500 shadow-2xl bg-slate-900' : 'border-slate-800 hover:border-slate-700 bg-slate-900/40'}`}>
            <div className="p-4 flex items-center justify-between cursor-pointer" onClick={() => setExpandedId(expandedId === f.id ? null : f.id)}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg border ${f.type === 'finops' ? 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20' : (f.severity === Severity.CRITICAL ? 'text-red-500 bg-red-500/10 border-red-500/20' : 'text-orange-500 bg-orange-500/10 border-orange-500/20')}`}>
                  {f.type === 'finops' ? <DollarSign size={16}/> : (f.severity === Severity.CRITICAL ? <Shield size={16}/> : <Target size={16}/>)}
                </div>
                <div>
                   <h4 className="font-bold text-xs text-slate-200">{f.title}</h4>
                   <p className="text-[9px] text-slate-500 font-mono uppercase">{f.resource}</p>
                </div>
              </div>
              {expandedId === f.id ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
            </div>
            {expandedId === f.id && (
              <div className="px-5 pb-5 pt-2 border-t border-slate-800/50 space-y-4 bg-slate-950/20">
                <p className="text-xs text-slate-400 italic">"{f.description}"</p>

                {onSimulateBlast && (
                  <button 
                    onClick={() => onSimulateBlast(f.resource)}
                    className="w-full py-2 bg-red-600/10 hover:bg-red-600/20 text-red-500 text-[9px] font-black rounded-lg border border-red-500/20 flex items-center justify-center gap-2 uppercase tracking-widest transition-all"
                  >
                    <Radar size={12} className="animate-pulse" /> Simular Raio de Explosão
                  </button>
                )}

                <div className="flex flex-wrap gap-2">
                   {f.complianceMapping?.map(c => <span key={c} className="text-[8px] font-black text-emerald-400 bg-emerald-500/5 px-2 py-0.5 rounded border border-emerald-500/10">{c}</span>)}
                   {f.type === 'finops' && <span className="text-[8px] font-black text-primary-400 bg-primary-500/5 px-2 py-0.5 rounded border border-primary-500/10">FINOPS_SAVING</span>}
                </div>

                {!aiFix[f.id] ? (
                  <button onClick={() => handleGenerateFix(f)} disabled={loadingFix === f.id} className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest border border-slate-700 transition-all active:scale-95">
                    {loadingFix === f.id ? <Loader2 className="animate-spin" size={14}/> : <Zap size={14} className="text-amber-400"/>}
                    {loadingFix === f.id ? 'Analisando...' : 'Gerar Remediação IA'}
                  </button>
                ) : (
                  <div className="space-y-3 animate-in fade-in">
                    <DiffViewer 
                      original={codeContext.split('\n').filter(l => l.includes(f.resource.split('.')[1])).join('\n') || '/* Código Original */'} 
                      fixed={aiFix[f.id]} 
                    />
                    <button onClick={() => handleFixAndCommit(f)} disabled={committing === f.id} className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-black rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest shadow-lg shadow-emerald-900/30 transition-all active:scale-95">
                      {committing === f.id ? <Loader2 className="animate-spin" size={16}/> : <GitPullRequest size={16}/>}
                      {committing === f.id ? 'Sincronizando...' : 'Aplicar Correção IA'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Server, Database, Globe, Layers, X, Info, 
  AlertTriangle, ShieldCheck, ArrowRight, ArrowUpRight, ExternalLink, Activity, Target, Zap, Cpu,
  Maximize2, MousePointer2, Filter, Share2, Radar, Skull, Ghost
} from 'lucide-react';
import { Vulnerability, GraphNode, Severity, GraphEdge } from '../types';

const getCategoryIcon = (category: string, size: number, color?: string) => {
  switch (category) {
    case 'compute': return <Cpu size={size} color={color} />;
    case 'storage': return <Database size={size} color={color} />;
    case 'network': return <Globe size={size} color={color} />;
    case 'security': return <Shield size={size} color={color} />;
    default: return <Layers size={size} color={color} />;
  }
};

const getCategoryHex = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; 
    case 'storage': return '#eab308'; 
    case 'network': return '#3b82f6'; 
    case 'security': return '#10b981'; 
    default: return '#64748b'; 
  }
};

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
  focusedResourceId?: string | null;
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities, focusedResourceId }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(focusedResourceId || null);
  const [hoveredNodeId, setHoveredNodeId] = useState<string | null>(null);
  const [activeLayer, setActiveLayer] = useState<string | 'all'>('all');

  useEffect(() => {
    if (focusedResourceId) setSelectedNodeId(focusedResourceId);
  }, [focusedResourceId]);

  const { nodes, edges } = useMemo(() => {
    const graph = parseHclToGraph(code);
    const enrichedNodes = graph.nodes.map(node => {
        const nodeVulns = vulnerabilities.filter(v => 
          v.resource.includes(node.id) || 
          node.id.includes(v.resource) ||
          v.resource.includes(node.data.label)
        );
        return { 
          ...node, 
          status: nodeVulns.length > 0 ? 'risk' : 'healthy' as any,
          vulnerabilities: nodeVulns 
        };
    });
    return { nodes: enrichedNodes, edges: graph.edges };
  }, [code, vulnerabilities]);

  const affectedNodeIds = useMemo(() => {
    if (!selectedNodeId) return [];
    const affected = new Set<string>();
    const findDependents = (nodeId: string) => {
      edges.forEach(edge => {
        if (edge.source === nodeId && !affected.has(edge.target)) {
          affected.add(edge.target);
          findDependents(edge.target);
        }
      });
    };
    findDependents(selectedNodeId);
    return Array.from(affected);
  }, [selectedNodeId, edges]);

  const selectedNode = nodes.find(n => n.id === selectedNodeId) as (GraphNode & { vulnerabilities: Vulnerability[] }) | undefined;
  const visibleNodes = nodes.filter(n => activeLayer === 'all' || n.data.category === activeLayer);

  return (
    <div className="p-8 h-[calc(100vh-100px)] max-w-7xl mx-auto flex flex-col space-y-6 animate-in fade-in duration-1000 relative overflow-hidden">

      <div className="flex justify-between items-center relative z-20">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-primary-500 shadow-[0_0_8px_#3b82f6]"></span>
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.25em]">Topology Reactor 2.0</span>
          </div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic text-glow">
            Infra <span className="text-primary-500">Universe</span>
          </h2>
        </div>

        <div className="flex items-center gap-3">
          {selectedNodeId && focusedResourceId === selectedNodeId && (
            <div className="flex items-center gap-3 px-4 py-2 bg-red-600/10 border border-red-600/30 rounded-xl text-red-500 animate-pulse">
               <Radar size={16} />
               <span className="text-[10px] font-black uppercase tracking-widest">Blast Radius Simulation Active</span>
            </div>
          )}
          <div className="bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl flex p-1 shadow-2xl">
            <LayerToggle active={activeLayer === 'all'} onClick={() => setActiveLayer('all')} icon={<Layers size={14}/>} label="Full" />
            <LayerToggle active={activeLayer === 'compute'} onClick={() => setActiveLayer('compute')} icon={<Cpu size={14}/>} label="Compute" />
            <LayerToggle active={activeLayer === 'network'} onClick={() => setActiveLayer('network')} icon={<Globe size={14}/>} label="Net" />
            <LayerToggle active={activeLayer === 'storage'} onClick={() => setActiveLayer('storage')} icon={<Database size={14}/>} label="Data" />
          </div>
        </div>
      </div>

      <div 
        className="flex-1 bg-[#020617] border border-white/5 rounded-[64px] relative overflow-hidden flex items-center justify-center shadow-inner cursor-grab active:cursor-grabbing"
        onClick={() => setSelectedNodeId(null)}
      >
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute inset-0 opacity-[0.03]" style={{ 
            backgroundImage: 'linear-gradient(#fff 1px, transparent 1px), linear-gradient(90deg, #fff 1px, transparent 1px)', 
            backgroundSize: '40px 40px' 
          }}></div>
        </div>

        <svg width="100%" height="100%" viewBox="0 0 1000 650" className="w-full h-full relative z-10 select-none">
          <defs>
            <marker id="arrowhead-mod" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#334155" />
            </marker>
          </defs>

          <g>
            {edges.map(edge => {
              const sourceNode = nodes.find(n => n.id === edge.source);
              const targetNode = nodes.find(n => n.id === edge.target);
              if (!sourceNode || !targetNode) return null;

              const isSelectedPath = selectedNodeId === edge.source || selectedNodeId === edge.target;
              const isBlastRadiusPath = affectedNodeIds.includes(edge.target) && (selectedNodeId === edge.source || affectedNodeIds.includes(edge.source));

              return (
                <g key={edge.id} className="transition-all duration-700">
                  <path 
                    d={`M ${sourceNode.position.x} ${sourceNode.position.y} L ${targetNode.position.x} ${targetNode.position.y}`}
                    stroke={isBlastRadiusPath ? "#ef4444" : isSelectedPath ? "#3b82f6" : "#1e293b"}
                    strokeWidth={isBlastRadiusPath || isSelectedPath ? 3 : 1.5}
                    strokeOpacity={isBlastRadiusPath || isSelectedPath ? 1 : 0.4}
                    fill="none"
                    markerEnd="url(#arrowhead-mod)"
                  />
                  {(isSelectedPath || isBlastRadiusPath) && (
                    <circle r="2" fill={isBlastRadiusPath ? "#ef4444" : "#60a5fa"}>
                      <animateMotion 
                        dur="1.5s" 
                        repeatCount="indefinite" 
                        path={`M ${sourceNode.position.x} ${sourceNode.position.y} L ${targetNode.position.x} ${targetNode.position.y}`} 
                      />
                    </circle>
                  )}
                </g>
              );
            })}
          </g>

          {visibleNodes.map(node => {
            const isSelected = selectedNodeId === node.id;
            const isAffected = affectedNodeIds.includes(node.id);
            const isDimmed = selectedNodeId && !isSelected && !isAffected;
            const category = node.data.category;
            const baseColor = node.status === 'risk' ? '#ef4444' : getCategoryHex(category);

            return (
              <g 
                key={node.id} 
                transform={`translate(${node.position.x}, ${node.position.y})`}
                className={`transition-all duration-500 cursor-pointer ${isDimmed ? 'opacity-20 scale-90' : 'opacity-100 scale-100'}`}
                onClick={(e) => { e.stopPropagation(); setSelectedNodeId(node.id); }}
              >
                {node.status === 'risk' && (
                  <circle r="45" fill="none" stroke="#ef4444" strokeWidth="1.5" strokeDasharray="4 8" className="animate-[spin_10s_linear_infinite]" />
                )}
                {isSelected && (
                  <circle r="50" fill="none" stroke={isAffected ? "#ef4444" : "#3b82f6"} strokeWidth="2" strokeDasharray="2 4" className="animate-[spin_4s_linear_infinite]" />
                )}

                <rect 
                  x="-32" y="-32" width="64" height="64" rx="16"
                  fill={isSelected ? "#1e293b" : "#0f172a"}
                  stroke={isSelected ? (isAffected ? "#ef4444" : "#3b82f6") : isAffected ? "#f59e0b" : baseColor}
                  strokeWidth={isSelected || isAffected ? 3 : 2}
                  className="transition-all hover:stroke-white shadow-2xl"
                />

                <g transform="translate(-10, -10)">
                  {getCategoryIcon(category, 20, isSelected ? '#fff' : baseColor)}
                </g>

                <g transform="translate(0, 52)">
                  <text textAnchor="middle" fill="white" fontSize="10" fontWeight="900" className="uppercase tracking-widest text-glow">{node.data.label}</text>
                  <text y="14" textAnchor="middle" fill="#475569" fontSize="7" fontWeight="black" className="uppercase tracking-[0.2em]">{node.data.resource_type}</text>
                </g>
              </g>
            );
          })}
        </svg>

        {selectedNode && (
          <aside 
            className="absolute top-0 right-0 h-full w-96 bg-slate-950/80 backdrop-blur-3xl border-l border-white/5 shadow-[-40px_0_60px_rgba(0,0,0,0.5)] z-30 animate-in slide-in-from-right duration-700 flex flex-col" 
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-10 border-b border-white/5 space-y-6">
              <div className="flex justify-between items-start">
