             <button 
               onClick={handleSealReport}
               className="bg-primary-600 hover:bg-primary-700 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-primary-900/40 transition-all"
             >
               Selar Relatório
