import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem, Guardrail } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getGuardrails(): Promise<Guardrail[]> {
    const current = this.db.get('guardrails');
    if (!current || current.length === 0) {
      const initial: Guardrail[] = [
        { id: 'gr-1', name: 'Encryption at Rest', description: 'Todos os buckets S3 devem ter criptografia ativada.', resourceType: 'aws_s3_bucket', logic: 'encryption_enabled == true', severity: Severity.HIGH, status: 'enabled' },
        { id: 'gr-2', name: 'SSH Global Block', description: 'Impedir porta 22 aberta para 0.0.0.0/0.', resourceType: 'aws_security_group', logic: 'ingress.port_22.cidr != "0.0.0.0/0"', severity: Severity.CRITICAL, status: 'enabled' }
      ];
      this.db.set('guardrails', initial);
      return initial;
    }
    return current;
  }

  async saveGuardrail(gr: Guardrail) {
    const current = this.db.get('guardrails');
    this.db.set('guardrails', [gr, ...current]);
    return true;
  }

  async getSubscriptionStatus() {
    return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' });
  }

  async fetchCloudDrifts(): Promise<DriftItem[]> {
    await new Promise(r => setTimeout(r, LATENCY));
    const current = this.db.get('drifts');
    if (!current || current.length === 0) {
      const initial: DriftItem[] = [
        { id: 'drift-1', resource: 'aws_s3_bucket.prod_assets', property: 'acl', terraformValue: 'private', cloudValue: 'public-read', severity: Severity.CRITICAL },
        { id: 'drift-2', resource: 'aws_security_group.db_sg', property: 'ingress', terraformValue: 'port 5432: 10.0.0.0/16', cloudValue: 'port 5432: 0.0.0.0/0', severity: Severity.HIGH }
      ];
      this.db.set('drifts', initial);
      return initial;
    }
    return current;
  }

  async resolveDrift(id: string) {
    await new Promise(r => setTimeout(r, LATENCY));
    const drifts = this.db.get('drifts');
    const updated = drifts.filter((d: DriftItem) => d.id !== id);
    this.db.set('drifts', updated);

    await this.logEvent({
      type: 'DRIFT',
      title: 'Recurso Sincronizado',
      description: `O drift no recurso ${id} foi mitigado via aplicação de estado desejado.`,
      severity: Severity.LOW
    });
    return true;
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY * 2));
    const guardrails = await this.getGuardrails();
    const model = 'gemini-3-pro-preview';
    const systemPrompt = `You are an elite DevSecOps Security Architect.
    Analyze the provided Terraform HCL for security vulnerabilities.

    CUSTOM GUARDRAILS TO ENFORCE:
    ${JSON.stringify(guardrails.filter(g => g.status === 'enabled'))}

    Return a strictly valid JSON response: { "findings": [...] }.
    Each finding MUST include: 
    - ruleId, title, severity (CRITICAL/HIGH/MEDIUM/LOW), resource, description, remediation, type ("security"|"finops"), complianceMapping (array).
    - impactScore: a number from 0 to 100.
    - explorationSteps: array of 3 strings.`;

    let findings: any[] = [];
    try {
      const response = await ai.models.generateContent({
        model,
        contents: `${systemPrompt}\n\nTerraform Code:\n${code}`,
        config: { 
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 2000 } 
        }
      });
      findings = JSON.parse(response.text || '{}').findings || [];
    } catch (e) {
      findings = [
        {
          ruleId: 'SEC-001', title: 'Bucket S3 Público Detectado', severity: Severity.CRITICAL,
          resource: 'aws_s3_bucket.prod_assets', description: 'O bucket permite leitura pública de dados sensíveis.',
          remediation: 'Mude acl para "private" e ative block_public_access.', type: 'security', complianceMapping: ['SOC2_CC6.1'],
          impactScore: 85, explorationSteps: ["Identificar nome do bucket", "Acessar via CLI", "Exfiltrar dados"]
        }
      ];
    }

    const vulns: Vulnerability[] = findings.map((f, i) => ({
      ...f, id: f.id || `v-${Date.now()}-${i}`, status: ScanStatus.OPEN
    }));

    const score = this.calculateScore(vulns, this.db.get('drifts'));
    this.db.set('vulnerabilities', vulns);

    const history = this.db.get('scan_history');
    this.db.set('scan_history', [{ id: Date.now(), timestamp: new Date(), score: score.total }, ...history].slice(0, 10));

    return { vulns, score };
  }

  async generateRootCauseAnalysis(incident: Vulnerability) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Provide a detailed Post-Mortem RCA for: ${incident.title}. Format as JSON.`;
    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return { summary: "Falha crítica.", rootCause: "Configuração insegura.", prevention: ["Policies"], auditEvidenceHash: "8821" };
    }
  }

  async suggestFix(vulnerability: string, codeContext: string) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Provide the corrected Terraform HCL code snippet for: "${vulnerability}". Return ONLY the plain HCL code.\nContext: ${codeContext}`;
    try {
      const response = await ai.models.generateContent({ model, contents: prompt });
      return response.text;
    } catch (e) {
      return "/* Erro ao gerar correção via IA. */";
    }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const criticals = (vulns?.filter(v => v.severity === Severity.CRITICAL && v.status !== ScanStatus.RESOLVED).length || 0) + 
                     (drifts?.filter(d => d.severity === Severity.CRITICAL).length || 0);
    const highs = (vulns?.filter(v => v.severity === Severity.HIGH && v.status !== ScanStatus.RESOLVED).length || 0) + 
                  (drifts?.filter(d => d.severity === Severity.HIGH).length || 0);

    const infraBase = Math.max(0, 100 - (criticals * 15) - (highs * 8));
    return {
      total: infraBase, infrastructure: infraBase,
      secrets: vulns?.some(v => v.ruleId.includes('SEC-003') && v.status !== ScanStatus.RESOLVED) ? 30 : 100,
      compliance: Math.max(0, infraBase - 5),
      drift: (!drifts || drifts.length === 0) ? 100 : 70,
      finops: 100, trend: infraBase > 80 ? 1.5 : -0.5
    };
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getScanHistory() { return this.db.get('scan_history'); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }

  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }

  async getSystemSettings() {
    return this.db.getSingle('settings', {
      accessKeyId: 'AKIA****************42', region: 'us-east-1',
      notifications: { autoFix: true, driftSync: false, soc2Logging: true }
    });
  }

  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async upgradeToPro(isPro: boolean) {
    const tier = isPro ? 'pro' : 'team';
    const sub = { tier, expires: '2026-12-31', currency: 'USD' };
    this.db.set('subscription', sub);
    return sub;
  }
}

