import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { AIAssistant } from './components/AIAssistant';
import { LiveAssistant } from './components/LiveAssistant';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { FinOps } from './pages/FinOps';
import { Roadmap } from './pages/Roadmap';
import { Organization } from './pages/Organization';
import { SecurityTesting } from './pages/SecurityTesting';
import { WarRoom } from './pages/WarRoom';
import { PostMortem } from './pages/PostMortem';
import { PolicyForge } from './pages/PolicyForge';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun, ScanStatus } from './types';
import { API } from './services/backend';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read"
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "mysql_db" {
  allocated_storage    = 20
  engine               = "mysql"
  instance_class       = "db.t2.micro"
  name                 = "production_db"
  username             = "admin"
  password             = "P@ssword123!"
  publicly_accessible  = true
  skip_final_snapshot  = true
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);

  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([]);

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    if (isAuthenticated) {
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  const loadInitialData = async () => {
    try {
      const [timeline, initialPolicies, initialVulns, initialDrifts] = await Promise.all([
        API.getTimeline(), API.getPolicies(), API.getVulnerabilities(), API.fetchCloudDrifts()
      ]);
      setTimelineEvents(timeline || []);
      setPolicies(initialPolicies || []);
      setVulnerabilities(initialVulns || []);
      setDrifts(initialDrifts || []);
      setIsInitializing(false);
    } catch (e) { 
      setIsInitializing(false); 
    }
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleLogin = () => {
    localStorage.setItem('cg_auth', 'true');
    setIsAuthenticated(true);
    setShowLogin(false);
    API.logEvent({ type: 'SCAN', title: 'Sessão Iniciada', description: 'Usuário logado no Global Console.' });
  };

  const handleLogout = () => {
    localStorage.removeItem('cg_auth');
    setIsAuthenticated(false);
    setShowLogin(false);
    setCurrentView('dashboard');
  };

  const onScanFinished = (vulns: Vulnerability[]) => {
    setVulnerabilities(vulns);
    showNotification(`Scan concluído: ${vulns.length} riscos encontrados.`);
    API.logEvent({
      type: 'RISK', title: 'Scan Realizado',
      description: `Motor de IA analisou IaC e encontrou ${vulns.length} problemas de conformidade.`,
      severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW
    }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
  };

  // REMEDIAÇÃO REAL: Esta função agora altera o código de verdade no editor
  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    const targetVuln = vulnerabilities.find(v => v.id === vulnId);
    if (!targetVuln) return;

    const resourceParts = targetVuln.resource.split('.');
    const type = resourceParts[0];
    const name = resourceParts[1];

    // Regex robusta para capturar o bloco HCL inteiro do recurso alvo
    const regex = new RegExp(`resource\\s+"${type}"\\s+"${name}"\\s*{[\\s\\S]*?}`, 'g');

    if (regex.test(terraformCode)) {
      const updatedCode = terraformCode.replace(regex, newSnippet);
      setTerraformCode(updatedCode);

      const updatedVulns = vulnerabilities.filter(v => v.id !== vulnId);
      setVulnerabilities(updatedVulns);
      await API.setVulnerabilities(updatedVulns);

      showNotification("Código corrigido com sucesso!");
      API.logEvent({
        type: 'PR', title: 'Remediação Aplicada',
        description: `O recurso ${targetVuln.resource} foi refatorado automaticamente.`
      }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
    } else {
      showNotification("Erro ao localizar recurso no editor.", "error");
    }
  };

  const handleLaunchWarRoom = (incident: Vulnerability) => {
    setActiveIncident(incident);
    setCurrentView('war-room');
  };

  const handleResolveIncident = (incident: Vulnerability, logs: string[]) => {
    const resolvedIncident = { 
      ...incident, 
      status: ScanStatus.RESOLVED, 
      resolvedAt: new Date().toISOString(),
      containmentLog: logs
    };

    setVulnerabilities(prev => prev.map(v => v.id === incident.id ? resolvedIncident : v));
    setActiveIncident(resolvedIncident);
    setCurrentView('post-mortem');
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
        <Loader2 className="text-primary-500 animate-spin" size={64} />
        <span className="text-slate-500 font-black uppercase text-[10px] tracking-[0.4em]">Iniciando Core...</span>
      </div>
    );
  }

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={handleLogin} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        onNavigate={(view) => { setCurrentView(view); }} 
        onLogout={handleLogout} 
        isAuditorMode={isAuditorMode}
        hasActiveIncident={!!activeIncident && activeIncident.status !== ScanStatus.RESOLVED}
      />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.filter(v => v.status !== ScanStatus.RESOLVED).length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
        />
        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 duration-300 border backdrop-blur-md bg-slate-900 border-slate-700">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-sm font-bold uppercase tracking-tight">{toast.message}</span>
          </div>
        )}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={onScanFinished} vulnerabilities={vulnerabilities.filter(v => v.status !== ScanStatus.RESOLVED)} onApplyFix={handleApplyFix} onSimulateBlast={handleLaunchWarRoom} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'policy-forge' && <PolicyForge onNotify={showNotification} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'security-tests' && <SecurityTesting />}
          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={handleResolveIncident} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
        </div>
        {isLiveAssistantOpen && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveAssistantOpen(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Hammer, Plus, ShieldCheck, Zap, Terminal, Code, 
  Trash2, Play, Loader2, Save, Search, Filter,
