import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem, Guardrail } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const model = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. 
    Provide 3 hypothetical but realistic global cloud security news items for today. 
    Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) {
      return [{ title: "Credential Leak Pattern", description: "Increase in AWS IAM abuse detected globally.", severity: Severity.HIGH }];
    }
  }

  async getScanHistory() { return this.db.get('scan_history'); }
  async getGuardrails() {
    const current = this.db.get('guardrails');
    if (!current || current.length === 0) {
      const initial: Guardrail[] = [
        { id: 'gr-1', name: 'S3 Public Block', description: 'Impedir buckets públicos.', resourceType: 'aws_s3_bucket', logic: 'acl != "public-read"', severity: Severity.CRITICAL, status: 'enabled' }
      ];
      this.db.set('guardrails', initial);
      return initial;
    }
    return current;
  }

  async saveGuardrail(gr: Guardrail) {
    const current = this.db.get('guardrails');
    this.db.set('guardrails', [gr, ...current]);
    return true;
  }

  async fetchCloudDrifts() { return this.db.get('drifts'); }
  async resolveDrift(id: string) {
    const drifts = this.db.get('drifts');
    this.db.set('drifts', drifts.filter((d: DriftItem) => d.id !== id));
    return true;
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY));
    const activeGuardrails = (await this.getGuardrails()).filter(g => g.status === 'enabled');
    const model = 'gemini-3-pro-preview';
    const prompt = `Audit the HCL for flaws and violations of:
    ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}: ${g.logic}`).join('\n')}
    Return JSON: { "findings": [...] }`;

    try {
      const response = await ai.models.generateContent({
        model, contents: prompt + "\n\nCode:\n" + code,
        config: { responseMimeType: "application/json" }
      });
      const findings = JSON.parse(response.text || '{}').findings || [];
      const vulns = findings.map((f: any, i: number) => ({ ...f, id: `v-${Date.now()}-${i}`, status: ScanStatus.OPEN }));
      const score = this.calculateScore(vulns, this.db.get('drifts'));
      this.db.set('vulnerabilities', vulns);
      return { vulns, score };
    } catch (e) { return { vulns: [], score: this.calculateScore([], []) }; }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;
    const infraBase = Math.max(0, 100 - (criticals * 20) - (highs * 10));
    return {
      total: infraBase, infrastructure: infraBase, secrets: 100, compliance: Math.max(0, infraBase - 5),
      drift: drifts.length === 0 ? 100 : 70, finops: 100, trend: 0
    };
  }

  async generateDefensiveTactics(title: string, resource: string) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Generate 4 defensive actions for "${title}" on "${resource}". Return JSON array of {id, title, desc}.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async generateRootCauseAnalysis(incident: Vulnerability) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Root Cause for "${incident.title}". Logs: ${JSON.stringify(incident.containmentLog)}. Return JSON: { summary, rootCause, prevention (array), auditEvidenceHash }.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '{}');
    } catch (e) { return {}; }
  }

  async suggestFix(title: string, codeContext: string) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Corrected HCL for "${title}". Return ONLY HCL.`;
    try {
      const response = await ai.models.generateContent({ model, contents: prompt + "\nContext:\n" + codeContext });
      return response.text?.replace(/```hcl|```/g, '').trim();
    } catch (e) { return ""; }
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }
  async logEvent(event: any) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }
  async getSystemSettings() { return this.db.getSingle('settings', { accessKeyId: 'AKIA...', region: 'us-east-1', notifications: { autoFix: true, driftSync: false, soc2Logging: true } }); }
  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async getSubscriptionStatus() { return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' }); }
  async upgradeToPro(isPro: boolean) { 
    const sub = { tier: isPro ? 'pro' : 'team', expires: '2026-12-31', currency: 'USD' };
    this.db.set('subscription', sub);
    return sub; 
  }
}

