import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem, Guardrail, Asset, ThreatData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getGlobalThreats(): Promise<ThreatData[]> {
    return [
      { id: 't-1', type: 'Exploit', region: 'us-east-1', intensity: 85, targets: ['S3', 'IAM'], timestamp: new Date().toISOString() },
      { id: 't-2', type: 'Botnet', region: 'eu-west-1', intensity: 45, targets: ['EC2'], timestamp: new Date().toISOString() },
      { id: 't-3', type: 'Leak', region: 'sa-east-1', intensity: 92, targets: ['RDS'], timestamp: new Date().toISOString() },
      { id: 't-4', type: 'DDoS', region: 'ap-southeast-1', intensity: 20, targets: ['CloudFront'], timestamp: new Date().toISOString() }
    ];
  }

  async getAssets(): Promise<Asset[]> {
    const current = this.db.get('assets');
    if (!current || current.length === 0) {
      const initial: Asset[] = [
        { id: 'as-1', name: 'prod-api-server', type: 'aws_instance', category: 'compute', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 12, cost: 45.5, tags: { env: 'prod' } },
        { id: 'as-2', name: 'customer-data-bucket', type: 'aws_s3_bucket', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 85, cost: 120.0, tags: { env: 'prod', data: 'sensitive' } },
        { id: 'as-3', name: 'auth-db-primary', type: 'aws_db_instance', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 45, cost: 240.0, tags: { env: 'prod' } },
        { id: 'as-4', name: 'edge-gateway-main', type: 'aws_api_gateway', category: 'network', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 5, cost: 15.2, tags: { env: 'prod' } }
      ];
      this.db.set('assets', initial);
      return initial;
    }
    return current;
  }

  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const model = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. 
    Provide 3 hypothetical but realistic global cloud security news items for today. 
    Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) {
      return [{ title: "Credential Leak Pattern", description: "Increase in AWS IAM abuse detected globally.", severity: Severity.HIGH }];
    }
  }

  async suggestFix(vulnerability: string, codeContext: string): Promise<string> {
    const model = 'gemini-3-pro-preview';
    const prompt = `Provide a Terraform HCL code snippet to fix the following vulnerability: "${vulnerability}". Context: \`\`\`hcl\n${codeContext}\n\`\`\` Return only the corrected HCL code block.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt });
      return resp.text || "/* AI Fix unavailable */";
    } catch (e) { return "/* Error generating fix suggestion */"; }
  }

  async generateDefensiveTactics(title: string, resource: string): Promise<any[]> {
    const model = 'gemini-3-pro-preview';
    const prompt = `You are a DevSecOps Security Responder. An incident has occurred: "${title}" on resource "${resource}". Generate 4 immediate tactical containment actions. Return JSON array: { id, title, desc }.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async generateRootCauseAnalysis(incident: Vulnerability): Promise<any> {
    const model = 'gemini-3-pro-preview';
    const prompt = `Perform a forensic Root Cause Analysis for this incident: ${JSON.stringify(incident)}. Return JSON: { summary, rootCause, prevention (array), auditEvidenceHash }.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '{}');
    } catch (e) { return {}; }
  }

  async getGuardrails() {
    const current = this.db.get('guardrails');
    if (!current || current.length === 0) {
      const initial: Guardrail[] = [
        { id: 'gr-1', name: 'S3 Public Block', description: 'Impedir buckets públicos.', resourceType: 'aws_s3_bucket', logic: 'acl != "public-read"', severity: Severity.CRITICAL, status: 'enabled' }
      ];
      this.db.set('guardrails', initial);
      return initial;
    }
    return current;
  }

  async saveGuardrail(gr: Guardrail) {
    const current = this.db.get('guardrails');
    this.db.set('guardrails', [gr, ...current]);
    return true;
  }

  async fetchCloudDrifts() { return this.db.get('drifts'); }
  async resolveDrift(id: string) {
    const drifts = this.db.get('drifts');
    this.db.set('drifts', drifts.filter((d: DriftItem) => d.id !== id));
    return true;
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY));
    const activeGuardrails = (await this.getGuardrails()).filter(g => g.status === 'enabled');
    const model = 'gemini-3-pro-preview';
    const prompt = `Audit the HCL for flaws and violations of: ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}`).join('\n')}. Return JSON: { "findings": [...] }`;
    try {
      const response = await ai.models.generateContent({ model, contents: prompt + "\n\nCode:\n" + code, config: { responseMimeType: "application/json" } });
      const findings = JSON.parse(response.text || '{}').findings || [];
      const vulns = findings.map((f: any, i: number) => ({ ...f, id: `v-${Date.now()}-${i}`, status: ScanStatus.OPEN }));
      const score = this.calculateScore(vulns, this.db.get('drifts'));
      this.db.set('vulnerabilities', vulns);
      return { vulns, score };
    } catch (e) { return { vulns: [], score: this.calculateScore([], []) }; }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;
    const infraBase = Math.max(0, 100 - (criticals * 20) - (highs * 10));
    return { total: infraBase, infrastructure: infraBase, secrets: 100, compliance: Math.max(0, infraBase - 5), drift: drifts.length === 0 ? 100 : 70, finops: 100, trend: 0 };
  }

  async generateAssetInsights(assets: Asset[]) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Analyze this cloud inventory: ${JSON.stringify(assets)}. Identify 3 critical security or cost insights. Return JSON array of {title, impact, recommendation}.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }
  async logEvent(event: any) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }
  async getSystemSettings() { return this.db.getSingle('settings', { accessKeyId: 'AKIA...', region: 'us-east-1', notifications: { autoFix: true, driftSync: false, soc2Logging: true } }); }
  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async getSubscriptionStatus() { return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' }); }
  async upgradeToPro(isPro: boolean) { const sub = { tier: isPro ? 'pro' : 'team', expires: '2026-12-31', currency: 'USD' }; this.db.set('subscription', sub); return sub; }
}

