  category: 'compute' | 'storage' | 'network' | 'security' | 'identity';
  provider: 'AWS' | 'Azure' | 'GCP';
  region: string;
  status: 'running' | 'stopped' | 'terminated';
  riskScore: number;
  cost: number;
  tags: Record<string, string>;
}

export interface Guardrail {
