export interface TimelineEvent {
  id: string;
  type: 'SCAN' | 'RISK' | 'PR' | 'COMPLIANCE' | 'DRIFT' | 'PIPELINE' | 'POLICY' | 'FINOPS' | 'ORG' | 'TEST' | 'GLOBAL' | 'INCIDENT';
