import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { AIAssistant } from './components/AIAssistant';
import { LiveAssistant } from './components/LiveAssistant';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { FinOps } from './pages/FinOps';
import { Roadmap } from './pages/Roadmap';
import { Organization } from './pages/Organization';
import { SecurityTesting } from './pages/SecurityTesting';
import { WarRoom } from './pages/WarRoom';
import { PostMortem } from './pages/PostMortem';
import { PolicyForge } from './pages/PolicyForge';
import { Inventory } from './pages/Inventory';
import { SentinelMap } from './pages/SentinelMap';
import { KnowledgeBase } from './pages/KnowledgeBase';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun, ScanStatus, Project } from './types';
import { API } from './services/backend';
import { dbService } from './services/dbService';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read"
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(localStorage.getItem('cg_active_project'));

  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);

  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([]);

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  const activeProject = useMemo(() => projects.find(p => p.id === activeProjectId), [projects, activeProjectId]);
  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    if (isAuthenticated) {
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (activeProjectId) {
      localStorage.setItem('cg_active_project', activeProjectId);
      // Simular carregamento de dados específicos do projeto
      if (activeProjectId === 'proj-2') {
         setVulnerabilities(v => v.length > 0 ? v : []);
      }
    }
  }, [activeProjectId]);

  const loadInitialData = async () => {
    try {
      const [timeline, initialPolicies, initialVulns, initialDrifts, initialProjects] = await Promise.all([
        API.getTimeline(), API.getPolicies(), API.getVulnerabilities(), API.fetchCloudDrifts(), dbService.getProjects()
      ]);
      setTimelineEvents(timeline || []);
      setPolicies(initialPolicies || []);
      setVulnerabilities(initialVulns || []);
      setDrifts(initialDrifts || []);
      setProjects(initialProjects || []);

      if (!activeProjectId && initialProjects.length > 0) {
        setActiveProjectId(initialProjects[0].id);
      }
      setIsInitializing(false);
    } catch (e) { 
      setIsInitializing(false); 
    }
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const onScanFinished = (vulns: Vulnerability[]) => {
    setVulnerabilities(vulns);
    showNotification(`Scan concluído no ambiente ${activeProject?.name}.`);
    API.logEvent({
      type: 'SCAN', title: 'Relatório Gerado',
      description: `Ambiente ${activeProject?.name} analisado. ${vulns.length} riscos encontrados.`,
      severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW
    }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
  };

  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    const targetVuln = vulnerabilities.find(v => v.id === vulnId);
    if (!targetVuln) return;
    const resourceParts = targetVuln.resource.split('.');
    const regex = new RegExp(`resource\\s+"${resourceParts[0]}"\\s+"${resourceParts[1]}"\\s*{[\\s\\S]*?}`, 'g');
    if (regex.test(terraformCode)) {
      setTerraformCode(terraformCode.replace(regex, newSnippet));
      const updatedVulns = vulnerabilities.filter(v => v.id !== vulnId);
      setVulnerabilities(updatedVulns);
      await API.setVulnerabilities(updatedVulns);
      showNotification("Patch aplicado com sucesso via IA.");
    }
  };

  const handleResolveIncident = (inc: Vulnerability, logs: string[]) => {
    setVulnerabilities(v => v.map(vi => vi.id === inc.id ? {...inc, status: ScanStatus.RESOLVED, containmentLog: logs} : vi));
    API.logEvent({
      type: 'INCIDENT',
      title: 'Incidente Resolvido',
      description: `Resposta ativa concluída para ${inc.title}. Relatório RCA gerado.`,
      severity: Severity.LOW
    });
    setCurrentView('post-mortem');
  };

  if (isInitializing) return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
      <Loader2 className="text-primary-500 animate-spin" size={64} />
      <span className="text-slate-500 font-black uppercase text-[10px] tracking-[0.4em]">Readying Guardian Core...</span>
    </div>
  );

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={() => { setIsAuthenticated(true); loadInitialData(); }} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={() => { setIsAuthenticated(true); loadInitialData(); }} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        onNavigate={setCurrentView} 
        onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cg_auth'); }} 
        isAuditorMode={isAuditorMode}
        hasActiveIncident={!!activeIncident && activeIncident.status !== ScanStatus.RESOLVED}
      />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
          activeProjectId={activeProjectId}
          projects={projects}
          onProjectChange={setActiveProjectId}
        />
        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 border backdrop-blur-md bg-slate-900/90 border-primary-500/20">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-[10px] font-black uppercase tracking-widest">{toast.message}</span>
          </div>
        )}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'sentinel' && <SentinelMap />}
          {currentView === 'knowledge-base' && <KnowledgeBase />}
          {currentView === 'inventory' && <Inventory />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={onScanFinished} vulnerabilities={vulnerabilities} onApplyFix={handleApplyFix} onSimulateBlast={(v) => { setActiveIncident(v); setCurrentView('war-room'); }} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'policy-forge' && <PolicyForge onNotify={showNotification} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'security-tests' && <SecurityTesting />}
          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={handleResolveIncident} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
        </div>
        {isLiveAssistantOpen && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveAssistantOpen(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem, Guardrail, Asset, ThreatData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getGlobalThreats(): Promise<ThreatData[]> {
    return [
      { id: 't-1', type: 'Exploit', region: 'us-east-1', intensity: 85, targets: ['S3', 'IAM'], timestamp: new Date().toISOString() },
      { id: 't-2', type: 'Botnet', region: 'eu-west-1', intensity: 45, targets: ['EC2'], timestamp: new Date().toISOString() },
      { id: 't-3', type: 'Leak', region: 'sa-east-1', intensity: 92, targets: ['RDS'], timestamp: new Date().toISOString() },
      { id: 't-4', type: 'DDoS', region: 'ap-southeast-1', intensity: 20, targets: ['CloudFront'], timestamp: new Date().toISOString() }
    ];
  }

  async getAssets(): Promise<Asset[]> {
    const current = this.db.get('assets');
    if (!current || current.length === 0) {
      const initial: Asset[] = [
        { id: 'as-1', name: 'prod-api-server', type: 'aws_instance', category: 'compute', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 12, cost: 45.5, tags: { env: 'prod' } },
        { id: 'as-2', name: 'customer-data-bucket', type: 'aws_s3_bucket', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 85, cost: 120.0, tags: { env: 'prod', data: 'sensitive' } },
        { id: 'as-3', name: 'auth-db-primary', type: 'aws_db_instance', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 45, cost: 240.0, tags: { env: 'prod' } },
        { id: 'as-4', name: 'edge-gateway-main', type: 'aws_api_gateway', category: 'network', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 5, cost: 15.2, tags: { env: 'prod' } }
      ];
      this.db.set('assets', initial);
      return initial;
    }
    return current;
  }

  async createRemediationPR(vulnId: string, fixCode: string): Promise<{ prUrl: string; branch: string }> {
    await new Promise(r => setTimeout(r, 1500));
    const branchName = `fix/security-remediation-${vulnId.slice(-4)}`;

    await this.logEvent({
      type: 'PR',
      title: 'Pull Request Aberto',
      description: `Auto-Remediação IA: Corrigindo vulnerabilidade ${vulnId}. Branch: ${branchName}`,
      severity: Severity.LOW
    });

    return {
      prUrl: `https://github.com/org/infra/pull/${Math.floor(Math.random() * 1000)}`,
      branch: branchName
    };
  }

  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const modelName = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. 
    Provide 3 hypothetical but realistic global cloud security news items for today. 
    Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '[]');
    } catch (e) {
      return [{ title: "Credential Leak Pattern", description: "Increase in AWS IAM abuse detected globally.", severity: Severity.HIGH }];
    }
  }

  async suggestFix(vulnerability: string, codeContext: string): Promise<string> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Provide a Terraform HCL code snippet to fix the following vulnerability: "${vulnerability}". Context: \`\`\`hcl\n${codeContext}\n\`\`\` Return only the corrected HCL code block.`;
    try {
      const resp = await ai.models.generateContent({ model: modelName, contents: prompt });
      return resp.text || "/* AI Fix unavailable */";
    } catch (e) { return "/* Error generating fix suggestion */"; }
  }

  async generateDefensiveTactics(title: string, resource: string): Promise<any[]> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `You are a DevSecOps Security Responder. An incident has occurred: "${title}" on resource "${resource}". Generate 4 immediate tactical containment actions. Return JSON array: { id, title, desc }.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async generateRootCauseAnalysis(incident: Vulnerability): Promise<any> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Perform a forensic Root Cause Analysis for this incident: ${JSON.stringify(incident)}. Return JSON: { summary, rootCause, prevention (array), auditEvidenceHash }.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '{}');
    } catch (e) { return {}; }
  }

  async getGuardrails() {
    const current = this.db.get('guardrails');
    if (!current || current.length === 0) {
      const initial: Guardrail[] = [
        { id: 'gr-1', name: 'S3 Public Block', description: 'Impedir buckets públicos.', resourceType: 'aws_s3_bucket', logic: 'acl != "public-read"', severity: Severity.CRITICAL, status: 'enabled' }
      ];
      this.db.set('guardrails', initial);
      return initial;
    }
    return current;
  }

  async saveGuardrail(gr: Guardrail) {
    const current = this.db.get('guardrails');
    this.db.set('guardrails', [gr, ...current]);
    return true;
  }

  async fetchCloudDrifts() { return this.db.get('drifts'); }
  async resolveDrift(id: string) {
    const drifts = this.db.get('drifts');
    this.db.set('drifts', drifts.filter((d: DriftItem) => d.id !== id));
    return true;
  }

  async getScanHistory() {
    return this.db.get('scan_history');
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY));
    const activeGuardrails = (await this.getGuardrails()).filter(g => g.status === 'enabled');
    const modelName = 'gemini-3-pro-preview';
    const prompt = `
      As a CloudGuardian Security Auditor, analyze the following Terraform HCL for security vulnerabilities and compliance issues (SOC2, ISO27001, HIPAA).
      Focus on these active guardrails:
      ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}`).join('\n')}

      Code to analyze:
      \`\`\`hcl
      ${code}
      \`\`\`

      Return a JSON response:
      {
        "findings": [
          {
            "ruleId": "string (e.g. COMP_SOC2_S3_PRIV)",
            "title": "string",
            "severity": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
            "resource": "string (e.g. aws_s3_bucket.bucket_name)",
            "description": "string",
            "remediation": "string",
            "complianceMapping": ["SOC2_CC6.1", "ISO27001_A.10"],
            "type": "security" | "finops" | "best_practice",
            "impactScore": number (0-100),
            "explorationSteps": ["step 1", "step 2"]
          }
        ]
      }
    `;

    try {
      const response = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });

      const findings = JSON.parse(response.text || '{}').findings || [];
      const vulns = findings.map((f: any, i: number) => ({ 
        ...f, 
        id: `v-${Date.now()}-${i}`, 
        status: ScanStatus.OPEN 
      }));

      const score = this.calculateScore(vulns, this.db.get('drifts'));
      this.db.set('vulnerabilities', vulns);

      const scanRecord = {
        id: `scan-${Date.now()}`,
        timestamp: new Date().toISOString(),
        score: score.total
      };
      const history = this.db.get('scan_history');
      this.db.set('scan_history', [scanRecord, ...history].slice(0, 10));

      return { vulns, score };
    } catch (e) { 
      console.error("Scan failed:", e);
      return { vulns: [], score: this.calculateScore([], []) }; 
    }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;

    const infraBase = Math.max(0, 100 - (criticals * 25) - (highs * 15));
    const complianceBase = Math.max(0, infraBase - (openVulns.length * 2));

    return { 
      total: Math.round((infraBase * 0.4) + (complianceBase * 0.3) + (100 * 0.3)), 
      infrastructure: infraBase, 
      secrets: 100, 
      compliance: complianceBase, 
      drift: drifts.length === 0 ? 100 : Math.max(0, 100 - (drifts.length * 10)), 
      finops: 100, 
      trend: 0 
    };
  }

  async generateAssetInsights(assets: Asset[]) {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Analyze this cloud inventory: ${JSON.stringify(assets)}. Identify 3 critical security or cost insights. Return JSON array of {title, impact, recommendation}.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }
  async logEvent(event: any) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }
  async getSystemSettings() { return this.db.getSingle('settings', { accessKeyId: 'AKIA...', region: 'us-east-1', notifications: { autoFix: true, driftSync: false, soc2Logging: true } }); }
  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async getSubscriptionStatus() { return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' }); }
  async upgradeToPro(isPro: boolean) { const sub = { tier: isPro ? 'pro' : 'team', expires: '2026-12-31', currency: 'USD' }; this.db.set('subscription', sub); return sub; }
}

