import { API } from './services/backend';
import { dbService } from './services/dbService';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read"
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(localStorage.getItem('cg_active_project'));

  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);
  const [isScanning, setIsScanning] = useState(false);

  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([]);

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);

  const activeProject = useMemo(() => projects.find(p => p.id === activeProjectId), [projects, activeProjectId]);
  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    if (isAuthenticated) {
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (activeProjectId) {
      localStorage.setItem('cg_active_project', activeProjectId);
    }
  }, [activeProjectId]);

  const loadInitialData = async () => {
    try {
      const [timeline, initialPolicies, initialVulns, initialDrifts, initialProjects] = await Promise.all([
        API.getTimeline(), API.getPolicies(), API.getVulnerabilities(), API.fetchCloudDrifts(), dbService.getProjects()
      ]);
      setTimelineEvents(timeline || []);
      setPolicies(initialPolicies || []);
      setVulnerabilities(initialVulns || []);
      setDrifts(initialDrifts || []);
      setProjects(initialProjects || []);

      if (!activeProjectId && initialProjects.length > 0) {
        setActiveProjectId(initialProjects[0].id);
      }
      setIsInitializing(false);
    } catch (e) { 
      setIsInitializing(false); 
    }
  };

  const showNotification = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const triggerGlobalScan = useCallback(async () => {
    setIsScanning(true);
    try {
      const result = await API.scanInfrastructure(terraformCode);
      setVulnerabilities(result.vulns);
      showNotification(`Scan concluído com sucesso. ${result.vulns.length} itens detectados.`);

      const evt = await API.logEvent({
        type: 'SCAN',
        title: 'Security Pulse Scan',
        description: `Varredura manual disparada. Status: ${result.vulns.length === 0 ? 'Limpo' : 'Risco Detectado'}.`,
        severity: result.vulns.length > 0 ? Severity.HIGH : Severity.LOW
      });
      setTimelineEvents(prev => [evt, ...prev]);
    } catch (e) {
      showNotification("Falha ao iniciar varredura de infraestrutura.", "error");
    } finally {
      setIsScanning(false);
    }
  }, [terraformCode, showNotification]);

  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    const targetVuln = vulnerabilities.find(v => v.id === vulnId);
    if (!targetVuln) return;
    const resourceParts = targetVuln.resource.split('.');
    const regex = new RegExp(`resource\\s+"${resourceParts[0]}"\\s+"${resourceParts[1]}"\\s*{[\\s\\S]*?}`, 'g');
    if (regex.test(terraformCode)) {
      setTerraformCode(terraformCode.replace(regex, newSnippet));
      const updatedVulns = vulnerabilities.filter(v => v.id !== vulnId);
      setVulnerabilities(updatedVulns);
      await API.setVulnerabilities(updatedVulns);
      showNotification("Patch aplicado com sucesso via IA.");
    }
  };

  const handleResolveIncident = (inc: Vulnerability, logs: string[]) => {
    setVulnerabilities(v => v.map(vi => vi.id === inc.id ? {...inc, status: ScanStatus.RESOLVED, containmentLog: logs} : vi));
    API.logEvent({
      type: 'INCIDENT',
      title: 'Incidente Resolvido',
      description: `Resposta ativa concluída para ${inc.title}. Relatório RCA gerado.`,
      severity: Severity.LOW
    });
    setCurrentView('post-mortem');
  };

  if (isInitializing) return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
      <Loader2 className="text-primary-500 animate-spin" size={64} />
      <span className="text-slate-500 font-black uppercase text-[10px] tracking-[0.4em]">Readying Guardian Core...</span>
    </div>
  );

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={() => { setIsAuthenticated(true); loadInitialData(); }} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={() => { setIsAuthenticated(true); loadInitialData(); }} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        onNavigate={setCurrentView} 
        onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cg_auth'); }} 
        isAuditorMode={isAuditorMode}
        hasActiveIncident={!!activeIncident && activeIncident.status !== ScanStatus.RESOLVED}
      />
      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
          activeProjectId={activeProjectId}
          projects={projects}
          onProjectChange={setActiveProjectId}
        />
        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 border backdrop-blur-md bg-slate-900/90 border-primary-500/20">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-[10px] font-black uppercase tracking-widest">{toast.message}</span>
          </div>
        )}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} isScanning={isScanning} onTriggerScan={triggerGlobalScan} />}
          {currentView === 'sentinel' && <SentinelMap />}
          {currentView === 'knowledge-base' && <KnowledgeBase />}
          {currentView === 'inventory' && <Inventory />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={(vulns) => setVulnerabilities(vulns)} vulnerabilities={vulnerabilities} onApplyFix={handleApplyFix} onSimulateBlast={(v) => { setActiveIncident(v); setCurrentView('war-room'); }} isScanning={isScanning} onTriggerScan={triggerGlobalScan} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} focusedResourceId={activeIncident?.resource} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'policy-forge' && <PolicyForge onNotify={showNotification} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'security-tests' && <SecurityTesting />}
          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={handleResolveIncident} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
        </div>
        {isLiveAssistantOpen && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveAssistantOpen(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

