};

class DBService {
  private async load(): Promise<DatabaseSchema> {
    const raw = localStorage.getItem(DB_KEY);
    if (!raw) {
      localStorage.setItem(DB_KEY, JSON.stringify(INITIAL_DB));
      return INITIAL_DB;
    }
    return JSON.parse(raw);
  }

  private async save(db: DatabaseSchema): Promise<void> {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  }

  // Generic Getters
  async getTable<T extends keyof DatabaseSchema>(table: T): Promise<DatabaseSchema[T]> {
    const db = await this.load();
    return db[table];
  }

  // Project Logic
  async upsertProject(project: Project) {
    const db = await this.load();
    const idx = db.projects.findIndex(p => p.id === project.id);
    if (idx > -1) db.projects[idx] = project;
    else db.projects.push(project);
    await this.save(db);
  }

  // Vulnerability Logic
  async setVulnerabilities(vulns: Vulnerability[]) {
    const db = await this.load();
    db.vulnerabilities = vulns;
    await this.save(db);
  }

  // Audit Logs
  async logEvent(event: Omit<TimelineEvent, 'id' | 'timestamp'>) {
    const db = await this.load();
    const newEvent: TimelineEvent = {
      ...event,
      id: `evt-${Date.now()}`,
      timestamp: new Date().toISOString()
    };
    db.timeline = [newEvent, ...db.timeline].slice(0, 50);
    await this.save(db);
    return newEvent;
  }

  // Guardrails
  async addGuardrail(gr: Guardrail) {
    const db = await this.load();
    db.guardrails = [gr, ...db.guardrails];
    await this.save(db);
  }
}

export const dbService = new DBService();

import { GoogleGenAI } from "@google/genai";
import { dbService } from './dbService';
import { 
  Vulnerability, TimelineEvent, SecurityScore, Severity, 
  ScanStatus, DriftItem, Guardrail, Asset, ThreatData 
} from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

class CloudGuardianBackend {
  // AI Intel
  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const modelName = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. Provide 3 hypothetical cloud security news for today. Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '[]');
    } catch (e) {
      return [{ title: "Pattern Analysis Delay", description: "Global intel feed is resyncing.", severity: Severity.LOW }];
    }
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY));
    const activeGuardrails = await dbService.getTable('guardrails');
    const modelName = 'gemini-3-pro-preview';

    const prompt = `
      As a CloudGuardian Security Auditor, analyze the following Terraform HCL.
      Check against these active guardrails:
      ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}: ${g.description}`).join('\n')}

      CODE:
      \`\`\`hcl
      ${code}
      \`\`\`

      Return a JSON response with this structure:
      {
        "findings": [
          {
            "ruleId": "string",
            "title": "string",
            "severity": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
            "resource": "resource_type.resource_name",
            "description": "string",
            "remediation": "string",
            "complianceMapping": ["SOC2_CC6.1"],
            "impactScore": number (0-100),
            "explorationSteps": ["step 1"]
          }
        ]
      }
    `;

    try {
      const response = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });

      const findings = JSON.parse(response.text || '{}').findings || [];
      const vulns = findings.map((f: any, i: number) => ({ 
        ...f, 
        id: `v-${Date.now()}-${i}`, 
        status: ScanStatus.OPEN 
      }));

      const drifts = await dbService.getTable('drifts');
      const score = this.calculateScore(vulns, drifts);

      await dbService.setVulnerabilities(vulns);
      await dbService.logEvent({
        type: 'SCAN',
        title: 'Infrastructure Scan Completed',
        description: `Detected ${vulns.length} vulnerabilities. New score: ${score.total}`,
        severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW
      });

      return { vulns, score };
    } catch (e) { 
      console.error("AI Scan Error:", e);
      return { vulns: [], score: this.calculateScore([], []) }; 
    }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;

    const infraBase = Math.max(0, 100 - (criticals * 25) - (highs * 15));
    const complianceBase = Math.max(0, infraBase - (openVulns.length * 2));

    return { 
      total: Math.round((infraBase * 0.4) + (complianceBase * 0.3) + (100 * 0.3)), 
      infrastructure: infraBase, 
      secrets: 100, 
      compliance: complianceBase, 
      drift: drifts.length === 0 ? 100 : Math.max(0, 100 - (drifts.length * 10)), 
      finops: 100, 
      trend: 0 
