    const modelName = 'gemini-3-flash-preview';
    const prompt = `Analyze these cloud assets and provide 3 security/cost insights. Assets: ${JSON.stringify(assets)}. Return JSON array: { impact: "HIGH/MEDIUM/LOW", title: string, recommendation: string }.`;
    try {
