const DB_NAME = 'CloudGuardianDB';
const DB_VERSION = 1;

class DBService {
  private db: IDBDatabase | null = null;

  private async getDB(): Promise<IDBDatabase> {
    if (this.db) return this.db;

    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Define "Tables"
        if (!db.objectStoreNames.contains('projects')) {
          db.createObjectStore('projects', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('members')) {
          db.createObjectStore('members', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('vulnerabilities')) {
          const store = db.createObjectStore('vulnerabilities', { keyPath: 'id' });
          store.createIndex('projectId', 'projectId', { unique: false });
        }
        if (!db.objectStoreNames.contains('timeline')) {
          const store = db.createObjectStore('timeline', { keyPath: 'id' });
          store.createIndex('projectId', 'projectId', { unique: false });
        }
        if (!db.objectStoreNames.contains('policies')) {
          db.createObjectStore('policies', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('drifts')) {
          const store = db.createObjectStore('drifts', { keyPath: 'id' });
          store.createIndex('projectId', 'projectId', { unique: false });
        }
        if (!db.objectStoreNames.contains('guardrails')) {
          db.createObjectStore('guardrails', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('assets')) {
          const store = db.createObjectStore('assets', { keyPath: 'id' });
          store.createIndex('projectId', 'projectId', { unique: false });
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings', { keyPath: 'id' });
        }
      };

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        this.seedInitialData().then(() => resolve(this.db!));
      };

      request.onerror = (event) => reject(request.error);
    });
  }

  private async seedInitialData() {
    const projects = await this.getAll<Project>('projects');
    if (projects.length === 0) {
      await this.save('projects', { 
        id: 'proj-primary', 
        name: 'Infrastructure-Prod', 
        cloud: 'AWS', 
        region: 'us-east-1', 
        status: 'active', 
        lastScan: new Date().toISOString(), 
        score: 85 
      });
      await this.save('members', { 
        id: 'mem-1', 
        name: 'John Doe', 
        email: 'admin@cloudguardian.ai', 
        role: 'admin', 
        lastActive: 'Now' 
      });
      await this.save('settings', {
        id: 'config',
        accessKeyId: 'AKIA' + Math.random().toString(36).substring(7).toUpperCase(),
        region: 'us-east-1',
        tier: 'pro',
        notifications: { autoFix: true, driftSync: false, soc2Logging: true }
      });
    }
  }

  private async save(storeName: string, data: any): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([storeName], 'readwrite');
      const store = transaction.objectStore(storeName);
      store.put(data);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  private async getAll<T>(storeName: string): Promise<T[]> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([storeName], 'readonly');
      const store = transaction.objectStore(storeName);
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  private async getByProject<T>(storeName: string, projectId: string): Promise<T[]> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([storeName], 'readonly');
      const store = transaction.objectStore(storeName);
      const index = store.index('projectId');
      const request = index.getAll(IDBKeyRange.only(projectId));
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  // API Methods
  async getProjects(): Promise<Project[]> { return this.getAll<Project>('projects'); }
  async saveProject(project: Project) { await this.save('projects', project); }

  async getMembers(): Promise<OrgMember[]> { return this.getAll<OrgMember>('members'); }

  async getVulnerabilities(projectId: string): Promise<Vulnerability[]> { 
    return this.getByProject<Vulnerability>('vulnerabilities', projectId); 
  }
  async setVulnerabilities(projectId: string, vulns: Vulnerability[]) {
    // Standard SQL-like 'DELETE then INSERT' for the project context
    const db = await this.getDB();
    const transaction = db.transaction(['vulnerabilities'], 'readwrite');
    const store = transaction.objectStore('vulnerabilities');
    const index = store.index('projectId');
    const request = index.getAllKeys(IDBKeyRange.only(projectId));

    request.onsuccess = () => {
      request.result.forEach(key => store.delete(key));
      vulns.forEach(v => store.put({ ...v, projectId }));
    };
  }

  async logEvent(projectId: string, event: Omit<TimelineEvent, 'id' | 'timestamp' | 'projectId'>) {
    const newEvent: TimelineEvent = {
      ...event,
      id: `evt-${Date.now()}-${Math.random().toString(36).substring(7)}`,
      timestamp: new Date().toISOString(),
      projectId
    };
    await this.save('timeline', newEvent);
    return newEvent;
  }

  async getTimeline(projectId: string): Promise<TimelineEvent[]> {
    return this.getByProject<TimelineEvent>('timeline', projectId);
  }

  async getPolicies(): Promise<Policy[]> { return this.getAll<Policy>('policies'); }
  async getGuardrails(): Promise<Guardrail[]> { return this.getAll<Guardrail>('guardrails'); }
  async saveGuardrail(gr: Guardrail) { await this.save('guardrails', gr); }

  async getSettings() {
    const settings = await this.getAll<any>('settings');
    return settings.find(s => s.id === 'config');
  }
  async updateSettings(settings: any) {
    await this.save('settings', { id: 'config', ...settings });
  }

  async getDrifts(projectId: string): Promise<DriftItem[]> {
    return this.getByProject<DriftItem>('drifts', projectId);
  }

  async removeDrift(id: string) {
    const db = await this.getDB();
    const transaction = db.transaction(['drifts'], 'readwrite');
    transaction.objectStore('drifts').delete(id);
  }
}

