} from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

class CloudGuardianBackend {
  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const modelName = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. Provide 3 hypothetical cloud security news for today. Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });
      return JSON.parse(resp.text || '[]');
    } catch (e) {
      console.error("Threat Briefing failed:", e);
      return [{ title: "Intel Sync Pending", description: "Connectivity to global threat engine is stabilizing.", severity: Severity.LOW }];
    }
  }

  async scanInfrastructure(projectId: string, code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    const activeGuardrails = await dbService.getGuardrails();
    const modelName = 'gemini-3-pro-preview';

    const prompt = `
      As a CloudGuardian Security Auditor, analyze the following Terraform HCL.
      Check against these active guardrails:
      ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}: ${g.description}`).join('\n')}

      CODE:
      \`\`\`hcl
      ${code}
      \`\`\`

      Return a JSON response with this structure:
      {
        "findings": [
          {
            "ruleId": "string",
            "title": "string",
            "severity": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
            "resource": "resource_type.resource_name",
            "description": "string",
            "remediation": "string",
            "complianceMapping": ["SOC2_CC6.1"],
            "impactScore": number (0-100),
            "explorationSteps": ["detailed step to exploit this"]
          }
        ]
      }
    `;

    try {
      const response = await ai.models.generateContent({ 
        model: modelName, 
        contents: prompt, 
        config: { responseMimeType: "application/json" } 
      });

      const findings = JSON.parse(response.text || '{}').findings || [];
      const vulns: Vulnerability[] = findings.map((f: any, i: number) => ({ 
        ...f, 
        id: `v-${Date.now()}-${i}`, 
        status: ScanStatus.OPEN,
        projectId
      }));

      const drifts = await dbService.getDrifts(projectId);
      const score = this.calculateScore(vulns, drifts);

      await dbService.setVulnerabilities(projectId, vulns);
      await dbService.logEvent(projectId, {
        type: 'SCAN',
        title: 'Infrastructure Scan Completed',
        description: `Detected ${vulns.length} vulnerabilities. Global Health Score: ${score.total}`,
        severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW,
        metadata: { score: score.total }
      });

      return { vulns, score };
    } catch (e) { 
      console.error("AI Analysis Core Error:", e);
      return { vulns: [], score: this.calculateScore([], []) }; 
    }
  }

  async createRemediationPR(projectId: string, vulnId: string, fixCode: string) {
    // Simulate real API latency to backend
    await new Promise(r => setTimeout(r, 1500));
    await dbService.logEvent(projectId, {
      type: 'PR',
      title: 'Pull Request Provisioned',
      description: `Auto-Remediation patch for vulnerability ID: ${vulnId.slice(-6)}`,
      severity: Severity.LOW
    });
    return { 
      prUrl: "https://github.com/cloudguardian/infra/pull/" + Math.floor(Math.random() * 500), 
      branch: `security-patch-${vulnId.slice(-4)}` 
    };
  }

  async suggestFix(vulnerability: string, codeContext: string): Promise<string> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Fix the following Terraform security issue: "${vulnerability}". Context: \`\`\`hcl\n${codeContext}\n\`\`\` Return only the HCL code block.`;
    try {
      const resp = await ai.models.generateContent({ model: modelName, contents: prompt });
      return resp.text || "/* Fix generation failed */";
    } catch (e) { return "/* AI logic unit currently offline */"; }
  }

  async generateDefensiveTactics(title: string, resource: string): Promise<any[]> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Generate 4 defensive actions for incident: "${title}" on "${resource}". Format: JSON array of { id, title, desc }.`;
    try {
      const resp = await ai.models.generateContent({ model: modelName, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }

  async generateRootCauseAnalysis(incident: Vulnerability): Promise<any> {
    const modelName = 'gemini-3-pro-preview';
    const prompt = `Perform forensic RCA for: ${incident.title}. Return JSON: { summary, rootCause, prevention (array), auditEvidenceHash }.`;
    try {
      const resp = await ai.models.generateContent({ model: modelName, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '{}');
    } catch (e) { return { summary: 'Error', rootCause: 'Timeout', prevention: [], auditEvidenceHash: 'N/A' }; }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;

    const infraBase = Math.max(0, 100 - (criticals * 25) - (highs * 15));
    const complianceBase = Math.max(0, infraBase - (openVulns.length * 2));

    return { 
      total: Math.round((infraBase * 0.4) + (complianceBase * 0.3) + (100 * 0.3)), 
      infrastructure: infraBase, 
      secrets: 100, 
      compliance: complianceBase, 
      drift: drifts.length === 0 ? 100 : Math.max(0, 100 - (drifts.length * 10)), 
      finops: 100, 
      trend: 0 
    };
  }

  async getGlobalThreats(): Promise<ThreatData[]> {
    return [
      { id: 't-1', type: 'Exploit', region: 'us-east-1', intensity: 85, targets: ['S3', 'IAM'], timestamp: new Date().toISOString() },
      { id: 't-2', type: 'Botnet', region: 'eu-west-1', intensity: 45, targets: ['EC2'], timestamp: new Date().toISOString() }
    ];
  }

  async getAssets(): Promise<Asset[]> {
    return [
      { id: 'as-1', name: 'prod-api-v3', type: 'aws_instance', category: 'compute', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 10, cost: 45, tags: {env: 'prod'}, projectId: 'proj-primary' },
      { id: 'as-2', name: 'customer-archive', type: 'aws_s3_bucket', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 80, cost: 120, tags: {env: 'prod'}, projectId: 'proj-primary' }
    ];
  }

  async generateAssetInsights(assets: Asset[]): Promise<any[]> {
    const modelName = 'gemini-3-flash-preview';
    const prompt = `Analyze these cloud assets: ${JSON.stringify(assets)}. Provide 3 strategic security/finops insights. JSON: { impact, title, recommendation }.`;
    try {
      const resp = await ai.models.generateContent({ model: modelName, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(resp.text || '[]');
    } catch (e) { return []; }
  }
}

