function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAuditorMode, setIsAuditorMode] = useState(false);

  // Database State
  const [projects, setProjects] = useState<Project[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(localStorage.getItem('cg_active_project'));
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);

  // Logic State
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveActive, setIsLiveActive] = useState(false);

  // Sync Global Data on Auth
  useEffect(() => {
    if (isAuthenticated) {
      dbService.getProjects().then(p => {
        setProjects(p);
        if (!activeProjectId && p.length > 0) setActiveProjectId(p[0].id);
        setIsInitializing(false);
      });
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  // Sync Project Data on Switch
  useEffect(() => {
    if (isAuthenticated && activeProjectId) {
      localStorage.setItem('cg_active_project', activeProjectId);
      syncProjectData();
    }
  }, [activeProjectId, isAuthenticated]);

  const syncProjectData = async () => {
    if (!activeProjectId) return;
    const [v, t, d, pol] = await Promise.all([
      dbService.getVulnerabilities(activeProjectId),
      dbService.getTimeline(activeProjectId),
      dbService.getDrifts(activeProjectId),
      dbService.getPolicies()
    ]);
    setVulnerabilities(v);
    setTimelineEvents(t);
    setDrifts(d);
    setPolicies(pol);
  };

  const showNotification = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const triggerGlobalScan = useCallback(async () => {
    if (!activeProjectId) return;
    setIsScanning(true);
    try {
      const result = await API.scanInfrastructure(activeProjectId, terraformCode);
      setVulnerabilities(result.vulns);
      showNotification(`Scan finalized: ${result.vulns.length} risks detected.`);
      await syncProjectData(); 
    } catch (e) {
      showNotification("AI Reasoning Unit Error.", "error");
    } finally {
      setIsScanning(false);
    }
  }, [terraformCode, activeProjectId, showNotification]);

  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    if (!activeProjectId) return;
    const target = vulnerabilities.find(v => v.id === vulnId);
    if (!target) return;

    setTerraformCode(prev => prev.replace(/acl\s*=\s*"public-read"/g, 'acl = "private"'));
    const updated = vulnerabilities.filter(v => v.id !== vulnId);
    setVulnerabilities(updated);

    await dbService.setVulnerabilities(activeProjectId, updated);
    await dbService.logEvent(activeProjectId, { 
      type: 'PR', 
      title: 'Infrastructure Patch Applied', 
      description: `Vulnerability ${target.title} resolved via AI Security Forge.`, 
      severity: Severity.LOW 
    });

    showNotification("Security patch deployed successfully.");
    await syncProjectData();
  };

  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

