          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={async (inc) => {
            const updated = vulnerabilities.filter(v => v.id !== inc.id);
            if (activeProjectId) {
              await dbService.setVulnerabilities(activeProjectId, updated);
              await dbService.logEvent(activeProjectId, { type: 'INCIDENT', title: 'Neutralization Complete', description: `Incident on ${inc.resource} successfully resolved.`, severity: Severity.LOW });
            }
            showNotification("Threat neutralized.");
            setCurrentView('post-mortem');
          }} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
          {currentView === 'knowledge-base' && <KnowledgeBase />}
