import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Header } from './components/Header';
import { AIAssistant } from './components/AIAssistant';
import { LiveAssistant } from './components/LiveAssistant';
import { Dashboard } from './pages/Dashboard';
import { Scanner } from './pages/Scanner';
import { Graph } from './pages/Graph';
import { Compliance } from './pages/Compliance';
import { Settings } from './pages/Settings';
import { Drift } from './pages/Drift';
import { Login } from './pages/Login';
import { LandingPage } from './pages/LandingPage';
import { AutomationHub } from './pages/AutomationHub';
import { ProjectReport } from './pages/ProjectReport';
import { Timeline } from './pages/Timeline';
import { SalesPlaybook } from './pages/SalesPlaybook';
import { PolicyManager } from './pages/PolicyManager';
import { PipelineInsights } from './pages/PipelineInsights';
import { FinOps } from './pages/FinOps';
import { Roadmap } from './pages/Roadmap';
import { Organization } from './pages/Organization';
import { SecurityTesting } from './pages/SecurityTesting';
import { WarRoom } from './pages/WarRoom';
import { PostMortem } from './pages/PostMortem';
import { PolicyForge } from './pages/PolicyForge';
import { Inventory } from './pages/Inventory';
import { SentinelMap } from './pages/SentinelMap';
import { KnowledgeBase } from './pages/KnowledgeBase';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, ScanStatus, Project } from './types';
import { API } from './services/backend';
import { dbService } from './services/dbService';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read"
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isAuditorMode, setIsAuditorMode] = useState(false);

  // Database State
  const [projects, setProjects] = useState<Project[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(localStorage.getItem('cg_active_project'));
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);

  // Logic State
  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveActive, setIsLiveActive] = useState(false);

  // Sync Global Data on Auth
  useEffect(() => {
    if (isAuthenticated) {
      dbService.getProjects().then(p => {
        setProjects(p);
        if (!activeProjectId && p.length > 0) setActiveProjectId(p[0].id);
        setIsInitializing(false);
      });
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  // Sync Project Data on Switch
  useEffect(() => {
    if (isAuthenticated && activeProjectId) {
      localStorage.setItem('cg_active_project', activeProjectId);
      syncProjectData();
    }
  }, [activeProjectId, isAuthenticated]);

  const syncProjectData = async () => {
    if (!activeProjectId) return;
    const [v, t, d, pol] = await Promise.all([
      dbService.getVulnerabilities(activeProjectId),
      dbService.getTimeline(activeProjectId),
      dbService.getDrifts(activeProjectId),
      dbService.getPolicies()
    ]);
    setVulnerabilities(v);
    setTimelineEvents(t);
    setDrifts(d);
    setPolicies(pol);
  };

  const showNotification = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const triggerGlobalScan = useCallback(async () => {
    if (!activeProjectId) return;
    setIsScanning(true);
    try {
      const result = await API.scanInfrastructure(activeProjectId, terraformCode);
      setVulnerabilities(result.vulns);
      showNotification(`Scan finalized: ${result.vulns.length} risks detected.`);
      await syncProjectData(); 
    } catch (e) {
      showNotification("AI Reasoning Unit Error.", "error");
    } finally {
      setIsScanning(false);
    }
  }, [terraformCode, activeProjectId, showNotification]);

  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    if (!activeProjectId) return;
    const target = vulnerabilities.find(v => v.id === vulnId);
    if (!target) return;

    setTerraformCode(prev => prev.replace(/acl\s*=\s*"public-read"/g, 'acl = "private"'));
    const updated = vulnerabilities.filter(v => v.id !== vulnId);
    setVulnerabilities(updated);

    await dbService.setVulnerabilities(activeProjectId, updated);
    await dbService.logEvent(activeProjectId, { 
      type: 'PR', 
      title: 'Infrastructure Patch Applied', 
      description: `Vulnerability ${target.title} resolved via AI Security Forge.`, 
      severity: Severity.LOW 
    });

    showNotification("Security patch deployed successfully.");
    await syncProjectData();
  };

  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  if (isInitializing) return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
      <Loader2 className="text-primary-500 animate-spin" size={64} />
      <span className="text-slate-500 font-black uppercase text-[10px] tracking-widest italic">Syncing Encrypted Storage...</span>
    </div>
  );

  if (!isAuthenticated) return <Login onLogin={() => { setIsAuthenticated(true); localStorage.setItem('cg_auth', 'true'); }} />;

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <Sidebar 
        currentView={currentView} 
        onNavigate={setCurrentView} 
        onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cg_auth'); }} 
        isAuditorMode={isAuditorMode}
        hasActiveIncident={!!activeIncident}
      />

      <main className="flex-1 ml-64 min-h-screen relative flex flex-col overflow-hidden">
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveActive(true)}
          isLiveActive={isLiveActive}
          activeProjectId={activeProjectId}
          projects={projects}
          onProjectChange={setActiveProjectId}
        />

        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 border backdrop-blur-md bg-slate-900/90 border-primary-500/20">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-[10px] font-black uppercase tracking-widest">{toast.message}</span>
          </div>
        )}

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={[]} isScanning={isScanning} onTriggerScan={triggerGlobalScan} />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={(v) => { setVulnerabilities(v); syncProjectData(); }} vulnerabilities={vulnerabilities} onApplyFix={handleApplyFix} onSimulateBlast={(v) => { setActiveIncident(v); setCurrentView('war-room'); }} isScanning={isScanning} onTriggerScan={triggerGlobalScan} activeProjectId={activeProjectId} />}
          {currentView === 'sentinel' && <SentinelMap />}
          {currentView === 'inventory' && <Inventory />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} focusedResourceId={activeIncident?.resource} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'policy-forge' && <PolicyForge onNotify={showNotification} />}
          {currentView === 'security-tests' && <SecurityTesting />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={async (inc) => {
            const updated = vulnerabilities.filter(v => v.id !== inc.id);
            if (activeProjectId) {
              await dbService.setVulnerabilities(activeProjectId, updated);
              await dbService.logEvent(activeProjectId, { type: 'INCIDENT', title: 'Neutralization Complete', description: `Incident on ${inc.resource} successfully resolved.`, severity: Severity.LOW });
            }
            showNotification("Threat neutralized.");
            setCurrentView('post-mortem');
          }} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
          {currentView === 'knowledge-base' && <KnowledgeBase />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'cicd' && <PipelineInsights runs={[]} setRuns={() => {}} onNotify={showNotification} onTimeline={() => {}} activeProjectId={activeProjectId} />}
        </div>

        {isLiveActive && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveActive(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'export default PipelineInsights';
import React, { useState, useEffect, useRef } from 'react';
import { Terminal, Github, GitBranch, ShieldCheck, CheckCircle2, XCircle, Clock, Play, ArrowUpRight, GitCommit, Loader2, ChevronRight, Copy, Check, FileCode, Zap, AlertTriangle, ShieldAlert } from 'lucide-react';
import { PipelineRun, Severity } from '../types';

interface PipelineInsightsProps {
  runs: PipelineRun[];
  setRuns: React.Dispatch<React.SetStateAction<PipelineRun[]>>;
  onNotify: (msg: string) => void;
  onTimeline: (event: any) => void;
  // Added activeProjectId to props
  activeProjectId: string | null;
}

export const PipelineInsights: React.FC<PipelineInsightsProps> = ({ runs, setRuns, onNotify, onTimeline, activeProjectId }) => {
  const [isTriggering, setIsTriggering] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'workflow' | 'pr-simulator'>('history');
  const [logs, setLogs] = useState<string[]>([]);
  const [copied, setCopied] = useState(false);
  const [simulatingPR, setSimulatingPR] = useState(false);
  const logEndRef = useRef<HTMLDivElement>(null);

  const workflowYaml = `name: CloudGuardian Security Scan

on:
  pull_request:
    branches: [ main, develop ]
    paths:
      - '**.tf'
      - '**.tfvars'

jobs:
  security_scan:
    name: CloudGuardian IaC Analysis
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v3

      - name: Run CloudGuardian Engine
        uses: cloudguardian/scanner-action@v1
        with:
          api_key: \${{ secrets.CG_API_KEY }}
          fail_on_critical: true
          output_format: github-pr-comment

      - name: AI Auto-Remediation Suggestion
        if: failure()
        run: echo "CloudGuardian detectou vulnerabilidades. Verifique os comentários no PR."`;

  const addLog = (msg: string) => setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);

  useEffect(() => {
    if (logEndRef.current) logEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(workflowYaml);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    onNotify("Workflow copiado para o clipboard!");
  };

  const triggerManualScan = () => {
    setIsTriggering(true);
    setLogs([]);
    addLog("Initializing CloudGuardian CI/CD Runner v2.4...");

    setTimeout(() => {
      addLog("Fetching Terraform HCL context...");
      setTimeout(() => {
        addLog("Running SAST analysis with Gemini Engine...");
        setTimeout(() => {
          addLog("Policy validation: SOC2 CC6.6 - PASS");
          setTimeout(() => {
            addLog("Policy validation: ISO27001 A.10 - PASS");
            setTimeout(() => {
              addLog("Finalizing results and reporting to central dashboard...");

              // Added projectId to fix type error
              const newRun: PipelineRun = {
                id: `run-${Math.floor(Math.random() * 1000)}`,
                projectId: activeProjectId || 'proj-primary',
                branch: 'main',
                status: 'success',
                vulns: 0,
                timestamp: new Date().toISOString(),
                commit: 'manual: security baseline scan'
              };

              setRuns(prev => [newRun, ...prev]);
              setIsTriggering(false);
              onNotify("Pipeline executado com sucesso!");
              onTimeline({
                type: 'PIPELINE',
                title: 'Pipeline Ad-Hoc Concluído',
                description: 'Scan manual de infraestrutura validado. Status: Clean.',
                severity: Severity.LOW
              });
            }, 500);
          }, 400);
        }, 600);
      }, 500);
    }, 500);
  };

  const runPRSimulation = () => {
