import React, { useMemo, useEffect, useState } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, AreaChart, Area, XAxis, YAxis, Tooltip, BarChart, Bar } from 'recharts';
import { 
  DollarSign, RefreshCw, GitPullRequest, ArrowRight, ShieldCheck, 
  Globe, Target, Zap, AlertTriangle, TrendingUp, CheckCircle2, Radar, Newspaper, TrendingDown, Loader2,
  BarChart3, Activity, ShieldAlert, Fingerprint
} from 'lucide-react';
import { SecurityScore, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun } from '../types';
import { API } from '../services/backend';
import { getComplianceReport } from '../services/engine';

interface DashboardProps {
  vulnerabilities: Vulnerability[];
  drifts: DriftItem[];
  score: SecurityScore;
  timeline: TimelineEvent[];
  onNavigate: (view: any) => void;
  policies: Policy[];
  runs: PipelineRun[];
  isScanning?: boolean;
  onTriggerScan?: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  vulnerabilities, drifts, score, onNavigate, isScanning = false, onTriggerScan
}) => {
  const [threats, setThreats] = useState<any[]>([]);
  const [loadingThreats, setLoadingThreats] = useState(false);
  const [history, setHistory] = useState<any[]>([]);

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    setLoadingThreats(true);
    const [threatData, scanHistory] = await Promise.all([
      API.getThreatBriefing(),
      API.getScanHistory()
    ]);
    setThreats(threatData);

    // Process scan history for the trend chart
    const processedHistory = (scanHistory || []).map((h: any) => ({
      time: new Date(h.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      score: h.score || 85,
      rawTime: new Date(h.timestamp).getTime()
    })).sort((a, b) => a.rawTime - b.rawTime);

    setHistory(processedHistory.length > 0 ? processedHistory : [
      { time: '08:00', score: 82 },
      { time: '10:00', score: 85 },
      { time: '12:00', score: 79 },
      { time: '14:00', score: 88 },
      { time: '16:00', score: score.total }
    ]);

    setLoadingThreats(false);
  };

  const complianceData = getComplianceReport(vulnerabilities);
  const compliancePercent = complianceData.length > 0 ? Math.round((complianceData.filter(c => c.status === 'PASS').length / complianceData.length) * 100) : 100;

  const scoreChartData = useMemo(() => [
    { name: 'Score', value: score.total },
    { name: 'Gap', value: Math.max(0, 100 - score.total) },
  ], [score.total]);

  const scoreDrivers = useMemo(() => [
    { name: 'Infra', value: score.infrastructure, color: '#3b82f6', icon: <Globe size={14}/> },
    { name: 'Secrets', value: score.secrets, color: '#ef4444', icon: <Fingerprint size={14}/> },
    { name: 'Compliance', value: score.compliance, color: '#10b981', icon: <ShieldCheck size={14}/> },
    { name: 'Drift', value: score.drift, color: '#f59e0b', icon: <Activity size={14}/> },
    { name: 'FinOps', value: score.finops, color: '#a855f7', icon: <DollarSign size={14}/> },
  ], [score]);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in duration-700 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_#10b981]"></span>
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Fleet Monitor v3.4-Stable</span>
          </div>
          <h2 className="text-5xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
            Command <span className="text-primary-500">Center</span>
          </h2>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={onTriggerScan}
            disabled={isScanning}
            className="neo-card px-6 py-3 rounded-2xl flex items-center gap-4 border border-primary-500/20 bg-primary-500/5 hover:bg-primary-500/10 transition-all active:scale-95 group"
          >
             <div className="p-2 bg-primary-600 rounded-lg shadow-lg group-hover:animate-pulse">
                {isScanning ? <Loader2 size={18} className="text-white animate-spin" /> : <Zap size={18} className="text-white" />}
             </div>
             <div className="text-left">
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Security Pulse</div>
                <div className="text-xs font-black text-white leading-none uppercase">{isScanning ? 'Analyzing Fleet...' : 'Trigger Global Scan'}</div>
             </div>
          </button>

          <div className="neo-card px-6 py-3 rounded-2xl flex items-center gap-4 border border-emerald-500/20 bg-emerald-500/5">
             <div className="p-2 bg-emerald-500 rounded-lg shadow-lg">
                <DollarSign size={18} className="text-white" />
             </div>
             <div>
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Risk ROI Efficiency</div>
                <div className="text-xl font-black text-white leading-none">USD {(vulnerabilities.length * 1450).toLocaleString()}</div>
             </div>
          </div>
          <button onClick={loadDashboardData} className="p-3 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 transition-all text-slate-400">
            <RefreshCw size={20} className={loadingThreats ? 'animate-spin' : ''} />
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        {/* Main Score Gauge & Drivers */}
        <div className="lg:col-span-8 neo-card rounded-[48px] p-10 relative overflow-hidden border border-white/5 shadow-2xl bg-slate-900/40">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
            <div className="flex flex-col items-center justify-center relative min-h-[350px]">
              <div className="w-80 h-80 relative">
                <ResponsiveContainer width="100%" height="100%" aspect={1}>
                  <PieChart>
                    <Pie data={scoreChartData} cx="50%" cy="50%" innerRadius={105} outerRadius={135} dataKey="value" startAngle={225} endAngle={-45} stroke="none" cornerRadius={20}>
                      <Cell fill={score.total > 75 ? "url(#gradGreen)" : "url(#gradRed)"} />
                      <Cell fill="rgba(255,255,255,0.03)" />
                    </Pie>
                    <defs>
                      <linearGradient id="gradGreen" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#10b981" /><stop offset="100%" stopColor="#3b82f6" /></linearGradient>
                      <linearGradient id="gradRed" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#ef4444" /><stop offset="100%" stopColor="#f59e0b" /></linearGradient>
                    </defs>
                  </PieChart>
                </ResponsiveContainer>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <div className={`text-7xl font-black text-white tracking-tighter text-glow ${isScanning ? 'animate-pulse' : ''}`}>{score.total}</div>
                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mt-2">Health Index</div>
                </div>
              </div>
            </div>

            <div className="space-y-8">
              <div className="flex justify-between items-center">
                <h3 className="text-3xl font-black text-white uppercase italic tracking-tighter leading-none">Security <br/><span className="text-primary-500">Breakdown</span></h3>
                <div className={`p-3 bg-white/5 rounded-2xl ${score.trend >= 0 ? 'text-emerald-500' : 'text-red-500'} animate-pulse`}>
                   {score.trend >= 0 ? <TrendingUp size={20} /> : <TrendingDown size={20} />}
                </div>
              </div>

              {/* Score Drivers Visualization */}
              <div className="space-y-4">
                {scoreDrivers.map((driver) => (
                  <div key={driver.name} className="space-y-1">
                    <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                      <div className="flex items-center gap-2">
                        <span className="opacity-60">{driver.icon}</span>
                        <span className="text-slate-400">{driver.name}</span>
                      </div>
                      <span style={{ color: driver.color }}>{driver.value}%</span>
                    </div>
