               <div className="space-y-4 relative z-10 flex-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Pipeline Audit Trail</h4>
                  <div className="space-y-3">
                    {runs.length === 0 ? (
                      <div className="py-12 text-center bg-slate-950/50 rounded-2xl border border-dashed border-slate-800">
                         <p className="text-xs text-slate-600 italic">Nenhum pipeline executado recentemente.</p>
                      </div>
                    ) : (
                      runs.map(run => (
                        <PipelineRunRow key={run.id} {...run} />
