                    )}
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'workflow' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-8 shadow-2xl animate-in fade-in duration-300">
               <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                  <div>
                    <h3 className="text-xl font-black text-white flex items-center gap-2 italic uppercase tracking-tight">
                      <FileCode className="text-primary-500" /> Infrastructure Integration
                    </h3>
                    <p className="text-[10px] text-slate-500 uppercase font-black mt-1">Configure o CloudGuardian em seu ambiente de CI em minutos.</p>
                  </div>

                  <div className="flex gap-2 p-1 bg-slate-950 border border-slate-800 rounded-xl">
                    <button 
                      onClick={() => setWorkflowPlatform('github')}
                      className={`flex items-center gap-2 px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${workflowPlatform === 'github' ? 'bg-white/10 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <Github size={14}/> GitHub
                    </button>
                    <button 
                      onClick={() => setWorkflowPlatform('gitlab')}
