                  </div>
                  <div className="bg-slate-950 border border-slate-800 rounded-3xl p-8 font-mono text-[11px] text-slate-400 overflow-x-auto custom-scrollbar shadow-inner leading-relaxed border-l-4 border-l-primary-500">
                      <pre>{workflowPlatform === 'github' ? githubYaml : gitlabYaml}</pre>
