);

import React, { useState, useEffect, useRef } from 'react';
import { 
  Terminal, Github, GitBranch, ShieldCheck, CheckCircle2, XCircle, 
  Clock, Play, ArrowUpRight, GitCommit, Loader2, ChevronRight, 
  Copy, Check, FileCode, Zap, AlertTriangle, ShieldAlert,
  Gitlab, Cpu, Info, Shield, Activity, GitPullRequest
} from 'lucide-react';
import { PipelineRun, Severity } from '../types';

interface PipelineInsightsProps {
  runs: PipelineRun[];
  setRuns: React.Dispatch<React.SetStateAction<PipelineRun[]>>;
  onNotify: (msg: string) => void;
  onTimeline: (event: any) => void;
  activeProjectId: string | null;
}

export const PipelineInsights: React.FC<PipelineInsightsProps> = ({ runs, setRuns, onNotify, onTimeline, activeProjectId }) => {
  const [isTriggering, setIsTriggering] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'workflow' | 'pr-simulator'>('history');
  const [workflowPlatform, setWorkflowPlatform] = useState<'github' | 'gitlab'>('github');
  const [logs, setLogs] = useState<string[]>([]);
  const [copied, setCopied] = useState(false);
  const [simulatingPR, setSimulatingPR] = useState(false);
  const logEndRef = useRef<HTMLDivElement>(null);

  const githubYaml = `name: CloudGuardian Security Scan

on:
  pull_request:
    branches: [ main, develop ]
    paths:
      - '**.tf'
      - '**.tfvars'

jobs:
  security_scan:
    name: CloudGuardian IaC Analysis
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v3

      - name: Run CloudGuardian Engine
        uses: cloudguardian/scanner-action@v1
        with:
          api_key: \${{ secrets.CG_API_KEY }}
          fail_on_critical: true
          output_format: github-pr-comment

      - name: AI Auto-Remediation Suggestion
        if: failure()
        run: echo "CloudGuardian detectou vulnerabilidades. Verifique os comentários no PR para aplicar o Auto-PR."`;

  const gitlabYaml = `include:
  - project: 'cloudguardian/ci-templates'
    file: '/templates/IaC-Scan.gitlab-ci.yml'

stages:
  - test
  - security

cloudguardian_scan:
  stage: security
  image: cloudguardian/scanner-cli:latest
  script:
    - cg-scan --api-key $CG_API_KEY --dir ./terraform --fail-on critical
  only:
    - merge_requests
  artifacts:
    reports:
      sast: gl-sast-report.json`;

  const addLog = (msg: string) => setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);

  useEffect(() => {
    if (logEndRef.current) logEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const copyToClipboard = () => {
    const yaml = workflowPlatform === 'github' ? githubYaml : gitlabYaml;
    navigator.clipboard.writeText(yaml);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    onNotify("Workflow copiado para o clipboard!");
  };

  const triggerManualScan = () => {
    setIsTriggering(true);
    setLogs([]);
    addLog("Initializing CloudGuardian CI/CD Runner v2.5...");

    setTimeout(() => {
      addLog("Fetching Infrastructure-as-Code context...");
      setTimeout(() => {
        addLog("Running Predictive Analysis with Gemini-3 Engine...");
        setTimeout(() => {
          addLog("Policy validation: SOC2 CC6.6 - PASS");
          setTimeout(() => {
            addLog("Policy validation: ISO27001 A.10 - PASS");
            setTimeout(() => {
              addLog("Finalizing results and pushing to Audit Hub...");

              const newRun: PipelineRun = {
                id: `run-${Math.floor(Math.random() * 1000)}`,
                projectId: activeProjectId || 'proj-primary',
                branch: 'main',
                status: 'success',
                vulns: 0,
                timestamp: new Date().toISOString(),
                commit: 'manual: fleet security baseline'
              };

              setRuns(prev => [newRun, ...prev]);
              setIsTriggering(false);
              onNotify("Pipeline executado com sucesso!");
              onTimeline({
                type: 'PIPELINE',
                title: 'Baseline Scan Concluído',
                description: 'Scan manual validado sem riscos críticos.',
                severity: Severity.LOW
              });
            }, 500);
          }, 400);
        }, 600);
      }, 500);
    }, 500);
  };

  const runPRSimulation = () => {
    setSimulatingPR(true);
    setTimeout(() => {
      const newRun: PipelineRun = {
        id: `run-${Math.floor(Math.random() * 1000)}`,
        projectId: activeProjectId || 'proj-primary',
        branch: 'feat/scale-out-rds',
        status: 'failed',
        vulns: 1,
        timestamp: new Date().toISOString(),
        commit: 'fix: update database capacity',
        prNumber: Math.floor(Math.random() * 100) + 120
      };
      setRuns(prev => [newRun, ...prev]);
      setSimulatingPR(false);
      onNotify("PR Guard: Violação de segurança detectada!");
      onTimeline({
        type: 'PIPELINE',
        title: 'PR Guard: Bloqueio Ativo',
        description: `O PR #${newRun.prNumber} violou políticas de criptografia RDS.`,
        severity: Severity.CRITICAL
      });
    }, 3000);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700 text-slate-200">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2 mb-2">
             <Cpu size={12} className="text-primary-500" />
             <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Shift-Left Automation Engine</span>
          </div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Pipeline <span className="text-primary-500">Insights</span></h2>
          <p className="text-slate-400 text-sm mt-2">Proteja sua infraestrutura integrando segurança nativa em cada Commit e Pull Request.</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={triggerManualScan}
            disabled={isTriggering}
            className="flex items-center gap-2 px-6 py-3 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl border border-slate-700 transition-all shadow-xl disabled:opacity-50 active:scale-95"
          >
            {isTriggering ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {isTriggering ? 'Executing...' : 'Manual Scan'}
          </button>
          <button 
            onClick={runPRSimulation}
            disabled={simulatingPR}
            className="flex items-center gap-3 px-10 py-4 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/40 disabled:opacity-50 active:scale-95 group"
          >
            {simulatingPR ? <Loader2 className="animate-spin" size={16} /> : <Zap size={16} />}
            Simular PR Guard
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex gap-2 p-1 bg-slate-900 rounded-2xl w-fit border border-slate-800">
        <TabButton active={activeTab === 'history'} onClick={() => setActiveTab('history')} label="Run History" icon={<Clock size={14}/>} />
        <TabButton active={activeTab === 'workflow'} onClick={() => setActiveTab('workflow')} label="Integrations" icon={<FileCode size={14}/>} />
        <TabButton active={activeTab === 'pr-simulator'} onClick={() => setActiveTab('pr-simulator')} label="PR Guard Lab" icon={<Github size={14}/>} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 space-y-6">
          {activeTab === 'history' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-8 shadow-2xl relative overflow-hidden flex flex-col">
               <div className="absolute top-0 right-0 p-8 opacity-5">
                  <Activity size={120} />
               </div>

               <div className="flex items-center justify-between relative z-10">
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-500">
                        <ShieldCheck size={24} />
                     </div>
                     <div>
                        <h3 className="text-lg font-bold text-white tracking-tight">Active CI Pipeline Monitoring</h3>
                        <p className="text-xs text-slate-500 font-mono uppercase tracking-widest">Connected to GitHub & GitLab</p>
                     </div>
                  </div>
               </div>

               {isTriggering && (
                 <div className="bg-black/80 rounded-2xl p-6 border border-slate-800 font-mono text-[10px] text-emerald-500 min-h-[160px] max-h-[160px] overflow-y-auto space-y-1 custom-scrollbar animate-in zoom-in-95">
                    {logs.map((log, i) => (
                      <div key={i} className="flex gap-3">
                        <ChevronRight size={10} className="mt-0.5 opacity-50" />
                        <span>{log}</span>
                      </div>
                    ))}
                    <div ref={logEndRef} />
                 </div>
               )}

               <div className="space-y-4 relative z-10 flex-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Pipeline Audit Trail</h4>
                  <div className="space-y-3">
                    {runs.length === 0 ? (
                      <div className="py-12 text-center bg-slate-950/50 rounded-2xl border border-dashed border-slate-800">
                         <p className="text-xs text-slate-600 italic">Nenhum pipeline executado recentemente.</p>
                      </div>
                    ) : (
                      runs.map(run => (
                        <PipelineRunRow key={run.id} {...run} />
                      ))
                    )}
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'workflow' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-8 shadow-2xl animate-in fade-in duration-300">
               <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                  <div>
                    <h3 className="text-xl font-black text-white flex items-center gap-2 italic uppercase tracking-tight">
                      <FileCode className="text-primary-500" /> Infrastructure Integration
                    </h3>
                    <p className="text-[10px] text-slate-500 uppercase font-black mt-1">Configure o CloudGuardian em seu ambiente de CI em minutos.</p>
                  </div>

                  <div className="flex gap-2 p-1 bg-slate-950 border border-slate-800 rounded-xl">
                    <button 
                      onClick={() => setWorkflowPlatform('github')}
                      className={`flex items-center gap-2 px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${workflowPlatform === 'github' ? 'bg-white/10 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <Github size={14}/> GitHub
                    </button>
                    <button 
                      onClick={() => setWorkflowPlatform('gitlab')}
                      className={`flex items-center gap-2 px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${workflowPlatform === 'gitlab' ? 'bg-white/10 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <Gitlab size={14}/> GitLab
                    </button>
                  </div>
               </div>

               <div className="space-y-4">
                  <div className="flex items-center justify-between">
                     <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{workflowPlatform.toUpperCase()} YAML CONFIGURATION</span>
                     <button 
                      onClick={copyToClipboard}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase rounded-xl transition-all"
                    >
                      {copied ? <Check size={14} /> : <Copy size={14} />}
                      {copied ? 'Copiado' : 'Copiar Config'}
                    </button>
                  </div>
                  <div className="bg-slate-950 border border-slate-800 rounded-3xl p-8 font-mono text-[11px] text-slate-400 overflow-x-auto custom-scrollbar shadow-inner leading-relaxed border-l-4 border-l-primary-500">
                      <pre>{workflowPlatform === 'github' ? githubYaml : gitlabYaml}</pre>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="p-6 bg-primary-500/5 border border-primary-500/10 rounded-[32px] space-y-4">
                     <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary-600 rounded-xl">
                           <Zap size={16} className="text-white" />
                        </div>
                        <h4 className="text-xs font-black text-white uppercase tracking-widest">Instalação Rápida</h4>
                     </div>
                     <p className="text-[10px] text-slate-500 leading-relaxed font-bold uppercase">
                        1. Crie o arquivo de workflow em seu repositório.<br/>
                        2. Adicione a variável <code className="text-primary-400">CG_API_KEY</code> nos Secrets.<br/>
                        3. A cada PR, o CloudGuardian validará seu código.
                     </p>
                  </div>

                  <div className="p-6 bg-emerald-500/5 border border-emerald-500/10 rounded-[32px] space-y-4">
                     <div className="flex items-center gap-3">
                        <div className="p-2 bg-emerald-600 rounded-xl">
                           <ShieldCheck size={16} className="text-white" />
                        </div>
                        <h4 className="text-xs font-black text-white uppercase tracking-widest">Policy Enforcement</h4>
                     </div>
                     <p className="text-[10px] text-slate-500 leading-relaxed font-bold uppercase">
                        Configure o parâmetro <code className="text-emerald-400">--fail-on critical</code> para bloquear automaticamente merges que contenham riscos graves.
                     </p>
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'pr-simulator' && (
            <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
               <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-10 space-y-8 shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-8 opacity-5">
                    <Zap size={140} className="text-primary-500" />
                  </div>

                  <div className="flex justify-between items-start relative z-10">
                    <div className="flex gap-6">
                      <div className="w-16 h-16 bg-slate-950 border border-white/5 rounded-[24px] flex items-center justify-center text-primary-500 shadow-xl group hover:border-primary-500/30 transition-all">
                        <Github size={32} />
                      </div>
                      <div>
                        <h3 className="text-2xl font-black text-white tracking-tighter uppercase italic">Autonomous PR Guard</h3>
                        <p className="text-xs text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">Visualização da intervenção IA em tempo real.</p>
                      </div>
                    </div>
                  </div>

                  {/* PR Comment Simulation */}
                  <div className="bg-slate-950 border border-slate-800 rounded-[40px] overflow-hidden shadow-2xl border-l-4 border-l-red-500 relative z-10">
                     <div className="bg-slate-900/80 p-6 border-b border-slate-800 flex justify-between items-center">
                        <div className="flex items-center gap-4">
                           <div className="w-10 h-10 rounded-2xl bg-primary-600 flex items-center justify-center text-white shadow-xl shadow-primary-900/30">
                              <Shield size={20} />
                           </div>
                           <div>
                              <div className="text-xs font-black text-white uppercase italic">cloudguardian-bot <span className="text-[9px] bg-slate-800 text-slate-500 px-2 py-0.5 rounded-full ml-3 not-italic">CERTIFIED_BOT</span></div>
                              <div className="text-[9px] text-slate-600 font-bold uppercase tracking-widest mt-1">Analyzing branch: <span className="text-slate-400">feat/new-rds-cluster</span></div>
                           </div>
                        </div>
                        <div className="p-2 bg-red-500/10 rounded-xl">
                           <AlertTriangle className="text-red-500" size={20} />
                        </div>
                     </div>
                     <div className="p-8 space-y-8">
                        <div className="space-y-3">
                           <h4 className="text-sm font-black text-white uppercase italic tracking-widest flex items-center gap-2">
                             <ShieldAlert size={14} className="text-red-500" /> Policy Violation Detected
                           </h4>
                           <p className="text-xs text-slate-400 leading-relaxed font-medium">
                              O recurso <code className="text-primary-400 font-bold">aws_db_instance.main</code> foi configurado com <code className="text-red-400 font-bold">storage_encrypted = false</code>.
                              Esta configuração é uma violação de nível <span className="text-red-500 font-black">CRÍTICO</span> do framework <span className="text-slate-300 font-bold underline decoration-primary-500">SOC2_CC6.1</span>.
                           </p>
                        </div>

                        <div className="bg-slate-900/60 border border-primary-500/20 rounded-3xl p-6 space-y-4 group hover:border-primary-500/40 transition-all">
                           <div className="flex items-center justify-between">
                              <div className="flex items-center gap-3 text-[10px] font-black text-primary-400 uppercase tracking-[0.2em]">
                                 <Zap size={14} className="animate-pulse" /> Auto-PR Remediation Proposal
                              </div>
                              <div className="text-[9px] font-black text-slate-600 uppercase">Gemini-3 Reasoning Engine</div>
                           </div>
                           <div className="font-mono text-[11px] space-y-2 bg-black/40 p-4 rounded-2xl shadow-inner">
                              <div className="text-red-500/60 line-through">-  storage_encrypted = false</div>
                              <div className="text-emerald-500 font-bold">+  storage_encrypted = true</div>
                              <div className="text-emerald-500 font-bold">+  kms_key_id        = aws_kms_key.rds.arn</div>
                           </div>
                        </div>

                        <div className="flex flex-col sm:flex-row gap-4">
                           <button className="flex-1 py-4 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/40 flex items-center justify-center gap-3 group">
