                           </button>
                           <button className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all border border-slate-700 flex items-center justify-center gap-2">
                              Ver Detalhes do Risco <ArrowUpRight size={14} />
                           </button>
                        </div>
                     </div>
                  </div>
               </div>
            </div>
          )}
        </div>

        <div className="lg:col-span-4 space-y-6">
           <div className="bg-slate-900 border border-white/5 rounded-[40px] p-8 space-y-8 shadow-2xl relative overflow-hidden">
