    <div className="flex items-center gap-5">
      <div className={`w-1.5 h-12 rounded-full transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 shadow-[0_0_15px_#10b981]' : 'bg-red-500 shadow-[0_0_15px_#ef4444]'}`}></div>
      <div className="min-w-0">
        <div className="flex items-center gap-3 mb-2">
           <span className="text-[10px] font-mono text-slate-600 uppercase font-bold tracking-widest">ID: {id.toUpperCase()}</span>
           <div className="flex items-center gap-1.5 text-[9px] text-white font-black bg-slate-800 px-2 py-0.5 rounded-lg border border-white/5">
              <GitBranch size={10} /> {branch}
           </div>
           {prNumber && (
             <div className="flex items-center gap-1.5 text-[9px] text-primary-400 font-black bg-primary-500/10 px-2 py-0.5 rounded-lg border border-primary-500/20">
                <Github size={10}/> PR #{prNumber}
             </div>
           )}
        </div>
        <div className="text-xs font-bold text-white truncate max-w-[250px] flex items-center gap-2 italic uppercase tracking-tight">
           <GitCommit size={14} className="text-slate-600" />
           {commit}
        </div>
      </div>
    </div>
    <div className="text-right flex items-center gap-8">
       <div className="hidden md:block">
          <div className={`text-xs font-black tracking-tighter ${vulns > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
            {vulns === 0 ? 'CLEAN PASS' : `${vulns} RISKS DETECTED`}
          </div>
          <div className="text-[8px] font-black text-slate-600 uppercase tracking-widest mt-1">Audit Status</div>
       </div>
       <div className="flex items-center gap-4">
          <div className="text-right">
             <div className="text-[10px] font-bold text-slate-400 font-mono">
               {new Date(timestamp).toLocaleDateString([], { day: '2-digit', month: '2-digit', year: '2-digit' })}
             </div>
             <div className="mt-1 flex justify-end">
               {status === 'success' ? <CheckCircle2 size={18} className="text-emerald-500" /> : <XCircle size={18} className="text-red-500" />}
             </div>
          </div>
          <button className="p-2 bg-white/5 rounded-xl text-slate-700 group-hover:text-primary-400 transition-all hover:bg-white/10 shadow-inner">
            <ArrowUpRight size={16} />
          </button>
       </div>
    </div>
  </div>
);

const ConfigToggle = ({ label, active }: any) => (
  <div className="flex items-center justify-between group cursor-pointer">
    <span className="text-[11px] font-black text-slate-500 uppercase tracking-widest group-hover:text-slate-200 transition-colors">{label}</span>
    <div className={`w-10 h-5 rounded-full relative transition-all border ${active ? 'bg-primary-600 border-primary-500' : 'bg-slate-900 border-white/10'}`}>
      <div className={`absolute top-0.5 w-3.5 h-3.5 rounded-full transition-all bg-white shadow-xl ${active ? 'right-0.5' : 'left-0.5'}`}></div>
    </div>
  </div>
);

const TabButton = ({ active, onClick, label, icon }: any) => (
  <button 
    onClick={onClick}
    className={`flex items-center gap-3 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
      active ? 'bg-slate-800 text-white shadow-xl border border-white/10' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
    }`}
  >
    <span className={active ? 'text-primary-500' : ''}>{icon}</span>
    {label}
  </button>
);
